CATEGORIE_SPESE = [   # (chiave, emoji, nome, parole che la fanno riconoscere)
    ("spesa", "🛒", "Spesa", "spesa supermercato supermarket alimentari esselunga conad coop lidl carrefour eurospin pam penny mercato frutta verdura pane latte macelleria panetteria salumeria"),
    ("trasporti", "🚗", "Trasporti", "benzina gasolio diesel carburante pieno rifornimento autostrada pedaggio parcheggio treno trenitalia italo biglietto autobus metro taxi uber meccanico gomme bollo tagliando"),
    ("bollette", "💡", "Bollette", "bolletta luce gas acqua fibra wifi internet tari rifiuti enel hera iren canone"),
    ("casa", "🏠", "Casa", "affitto condominio mutuo arredamento mobili ikea elettrodomestico pulizie idraulico elettricista ferramenta"),
    ("mangiare", "🍕", "Mangiare fuori", "ristorante pizza pizzeria bar caffè cappuccino colazione aperitivo sushi panino kebab gelato cena pranzo asporto deliveroo glovo justeat trattoria osteria"),
    ("salute", "💊", "Salute e sport", "farmacia medicine medicina medico dentista visita analisi ottico occhiali palestra fisioterapista piscina"),
    ("svago", "🎬", "Svago", "cinema teatro concerto netflix spotify disney abbonamento videogioco libro libri viaggio vacanza hotel museo biglietti"),
    ("vestiti", "👕", "Vestiti", "vestiti scarpe maglietta maglione pantaloni giacca cappotto zara abbigliamento borsa jeans"),
    ("regali", "🎁", "Regali", "regalo regali compleanno fiori"),
    ("tecnologia", "💻", "Tecnologia", "telefono cellulare smartphone computer cuffie amazon tablet stampante caricatore"),
    ("animali", "🐶", "Animali", "cane gatto veterinario crocchette lettiera"),
    ("altro", "📦", "Altro", ""),
]
CAT_SPESE = {k: {"chiave": k, "emoji": e, "nome": n} for k, e, n, _ in CATEGORIE_SPESE}


def _parole_cat(testo):
    return [w for w in _normalizza(testo).split() if len(w) > 1]


def _parola_simile(w, kw):
    """«bollette» ~ «bolletta», «ristoranti» ~ «ristorante», «pizze» ~ «pizza»; ma «bolletta» non è «bollo»."""
    if w == kw:
        return True
    if len(kw) >= 6:
        return w.startswith(kw[:-1]) and len(w) <= len(kw) + 3
    return len(kw) == 5 and len(w) == 5 and w[:4] == kw[:4]


def categoria_spesa(testo):
    """La categoria dalle parole (benzina → trasporti, pizza → mangiare fuori…)."""
    ws = _parole_cat(testo)
    for chiave, _, nome, parole in CATEGORIE_SPESE:
        for kw in parole.split():
            kw = _senza_accenti(kw)
            if any(_parola_simile(w, kw) for w in ws):
                return chiave
    for chiave, _, nome, _ in CATEGORIE_SPESE:          # «budget trasporti», «spese di svago»
        if _normalizza(nome).split()[0] in ws or chiave in ws:
            return chiave
    return None


def euro(v):
    s = f"{abs(v):,.2f}".replace(",", "§").replace(".", ",").replace("§", ".")
    return ("−" if v < 0 else "") + s + " €"


def _num_it(s):
    s = re.sub(r"\s", "", s)
    if "," in s:
        s = s.replace(".", "").replace(",", ".")
    elif re.fullmatch(r"\d{1,3}(?:\.\d{3})+", s):
        s = s.replace(".", "")
    return float(s)


_NUM_IT = r"\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?"
_RE_IMPORTO = re.compile(r"(?:€\s*(?P<a>" + _NUM_IT + r"))|(?P<b>" + _NUM_IT + r")\s*(?:€|euro\b|eur\b)(?:\s+e\s+(?P<c>\d{1,2})(?:\s*(?:centesimi|cent)\b)?)?", re.I)
_RE_NUMERO_NUDO = re.compile(r"(?<![\d/.:,])(" + _NUM_IT + r")(?![\d/:]|[.,]\d|\s*(?:%|minut|or[ae]\b|giorn|ann|km|kg|litr|volt|bicchier|pagin|passi|settiman|mes|cm|metr))", re.I)


def trova_importo(testo, serve_valuta=True):
    """→ (importo, (inizio, fine)) o (None, None). «23,50 €», «€ 1.234,56», «40 euro e 50», e senza valuta se permesso."""
    m = _RE_IMPORTO.search(testo or "")
    if m:
        v = _num_it(m.group("a") or m.group("b")) + (int(m.group("c")) / 100 if m.group("c") else 0)
        return round(v, 2), m.span()
    if not serve_valuta:          # senza «€»: solo se ha i decimali, è in fondo o è seguito da «di/per/al…» («ho pagato 3 rate» non è una spesa di 3 €)
        for m in _RE_NUMERO_NUDO.finditer(testo or ""):
            dopo = (testo or "")[m.end():].strip()
            if re.search(r"[.,]\d", m.group(1)) or not dopo or re.match(r"(?i)(?:di|per|al|allo|alla|ai|agli|alle|da|dal|dalla|in|nel|nella|x|la|il|lo|le|i|gli|un|una|uno|[.,;!])(?:\b|\s|$)", dopo):
                return round(_num_it(m.group(1)), 2), m.span()
    return None, None


_MESI_RE = "|".join(MESI_IT)
_RE_SPESA_FORTE = re.compile(r"\b(?:ho|abbiamo)\s+(?:appena\s+)?(?:speso|pagato)\b|\bspesi\b|\bpagati\b|\b(?:segna|registra|aggiungi|metti)(?:mi)?\s+(?:una\s+)?spesa\b|\bnuova\s+spesa\b|^spesa\s*[:\-]", re.I)
_RE_SPESA_DEBOLE = re.compile(r"\b(?:ho|abbiamo)\s+(?:appena\s+)?(?:comprato|preso|fatto|ordinato|prenotato|dato|rinnovato)\b", re.I)
_RE_SPESA_DOMANDA = re.compile(r"\?|^(?:quanto|quanti|quando|dove|come|perch[eé]|chi|cosa|se)\b|\blista\s+della\s+spesa\b|\bmi\s+(?:ricordi|ricordo)\b", re.I)
_RE_SPESE_Q = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:quanto\s+(?:ho|abbiamo)\s+speso|quanti\s+soldi\s+(?:ho|abbiamo)\s+speso|(?:le\s+)?(?:mie\s+)?spese\b|riepilogo\s+(?:delle\s+)?spese|resoconto\s+(?:delle\s+)?spese|come\s+sto\s+(?:messo\s+)?(?:a|con\s+i)\s+soldi|come\s+va\s+il\s+budget|com['’]?\s*[eè]\s+(?:messo\s+)?il\s+budget|(?:il\s+)?(?:mio\s+)?budget$|quanto\s+mi\s+resta(?:\s+da\s+spendere)?)(?P<resto>.*)$", re.I)
_RE_BUDGET = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:imposta|metti|fissa|cambia|setta|porta)\s+(?:il\s+)?budget|budget|il\s+mio\s+budget\s+[eè])(?:\s+(?:mensile|del\s+mese|al\s+mese))?(?:\s+(?:per\s+(?:la\s+|il\s+|i\s+|le\s+|lo\s+)?|di\s+|della\s+|del\s+|dei\s+|delle\s+)?(?P<cat>[a-zà-ù ]{3,22}?))?\s+(?:a|di|=|:)?\s*(?P<imp>€?\s*\d[\d.,]*\s*(?:€|euro)?)(?:\s+al\s+mese)?$", re.I)


class Spese:
    def __init__(self):
        self._lock = threading.Lock()

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "spese.json")

    def _carica(self):
        try:
            with open(self._file(), encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                d.setdefault("spese", [])
                d.setdefault("budget", {})
                return d
        except Exception:
            pass
        return {"spese": [], "budget": {}}

    def _salva(self, d):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(tmp, self._file())

    def tutte(self):
        return self._carica()["spese"]

    def budget(self):
        return self._carica()["budget"]

    def aggiungi(self, importo, descrizione, categoria=None, data=None, fonte="chat", scadenza=None):
        try:
            importo = round(float(importo), 2)
        except (TypeError, ValueError):
            return None, "importo non valido"
        if not (0 < importo < 1_000_000):
            return None, "importo non valido"
        descrizione = re.sub(r"\s+", " ", str(descrizione or "")).strip(" .,:;-")[:80]
        categoria = categoria if categoria in CAT_SPESE else (categoria_spesa(descrizione) or "altro")
        descrizione = descrizione[:1].upper() + descrizione[1:] if descrizione else CAT_SPESE[categoria]["nome"]
        data = data or datetime.date.today()
        s = {"id": uuid.uuid4().hex[:10], "data": data.isoformat() if hasattr(data, "isoformat") else str(data)[:10], "importo": importo,
             "descrizione": descrizione, "categoria": categoria, "fonte": fonte, **({"scadenza": scadenza} if scadenza else {})}
        with self._lock:
            d = self._carica()
            prima = self._tot_mese(d, s["data"][:7])
            d["spese"].append(s)
            d["spese"] = d["spese"][-20000:]
            self._salva(d)
            dopo = prima + importo
            avviso = self._avviso_budget(d, s["data"][:7], prima, dopo, categoria, importo)
        return dict(s, avviso=avviso), None

    @staticmethod
    def _tot_mese(d, mese, categoria=None):
        return round(sum(x["importo"] for x in d["spese"] if x["data"][:7] == mese and (not categoria or x["categoria"] == categoria)), 2)

    def _avviso_budget(self, d, mese, prima, dopo, categoria, importo):
        out = []
        b = d["budget"].get("totale")
        if b:
            out.append(self._soglia(prima, dopo, b, f"del budget di {MESI_IT[int(mese[5:]) - 1]}"))
        bc = d["budget"].get(categoria)
        if bc:
            pc = self._tot_mese(d, mese, categoria)
            out.append(self._soglia(pc - importo, pc, bc, f"del budget per {CAT_SPESE[categoria]['emoji']} {CAT_SPESE[categoria]['nome'].lower()}"))
        return " ".join(x for x in out if x) or None

    @staticmethod
    def _soglia(prima, dopo, b, cosa):
        if prima < b <= dopo:
            return f"🚨 Hai superato il {cosa[4:] if cosa.startswith('del ') else cosa}: {euro(dopo)} su {euro(b)}."
        if prima < 0.8 * b <= dopo:
            p = round(100 * dopo / b)
            return f"⚠️ Hai usato {'l' + chr(39) if str(p).startswith('8') else 'il '}{p}% {cosa} ({euro(dopo)} su {euro(b)})."
        return None

    def elimina(self, sid):
        with self._lock:
            d = self._carica()
            prima = len(d["spese"])
            d["spese"] = [x for x in d["spese"] if x["id"] != sid]
            self._salva(d)
            return len(d["spese"]) < prima

    def imposta_budget(self, importo, categoria=None):
        k = categoria if categoria in CAT_SPESE else "totale"
        with self._lock:
            d = self._carica()
            if importo and importo > 0:
                d["budget"][k] = round(float(importo), 2)
            else:
                d["budget"].pop(k, None)
            self._salva(d)
            return dict(d["budget"])

    def riepilogo(self, da, a, filtro=None, categoria=None):
        """da/a: date (comprese). filtro: parola nella descrizione."""
        d = self._carica()
        f = _senza_accenti(filtro or "").lower()
        voci = [x for x in d["spese"] if da.isoformat() <= x["data"] <= a.isoformat()
                and (not categoria or x["categoria"] == categoria) and (not f or f in _senza_accenti(x["descrizione"]).lower())]
        tot = round(sum(x["importo"] for x in voci), 2)
        cats = {}
        for x in voci:
            cats[x["categoria"]] = cats.get(x["categoria"], 0) + x["importo"]
        per_cat = [dict(CAT_SPESE[k], totale=round(v, 2), perc=round(100 * v / tot) if tot else 0) for k, v in sorted(cats.items(), key=lambda kv: -kv[1])]
        giorni = {}
        for x in voci:
            giorni[x["data"]] = round(giorni.get(x["data"], 0) + x["importo"], 2)
        lung = (a - da).days + 1
        prec = [x for x in d["spese"] if (da - datetime.timedelta(days=lung)).isoformat() <= x["data"] < da.isoformat()
                and (not categoria or x["categoria"] == categoria) and (not f or f in _senza_accenti(x["descrizione"]).lower())]
        out = {"da": da.isoformat(), "a": a.isoformat(), "totale": tot, "n": len(voci), "per_categoria": per_cat, "per_giorno": giorni,
               "prima": round(sum(x["importo"] for x in prec), 2), "voci": sorted(voci, key=lambda x: (x["data"], x["id"]), reverse=True)}
        if da.day == 1 and (da.year, da.month) == (a.year, a.month):           # un mese (intero o fino a oggi): il budget
            mese = da.isoformat()[:7]
            b = d["budget"]
            if b.get("totale"):
                usato = self._tot_mese(d, mese)
                out["budget"] = {"totale": b["totale"], "usato": usato, "perc": round(100 * usato / b["totale"]), "resta": round(b["totale"] - usato, 2)}
            out["budget_categorie"] = [dict(CAT_SPESE[k], budget=v, usato=self._tot_mese(d, mese, k)) for k, v in b.items() if k in CAT_SPESE]
        return out

    @staticmethod
    def periodo(testo, oggi=None):
        """«oggi», «ieri», «questa settimana», «settimana scorsa», «mese scorso», «a settembre», «quest'anno» → (da, a, etichetta)."""
        oggi = oggi or datetime.date.today()
        tl = _senza_accenti((testo or "").lower())
        primo = oggi.replace(day=1)
        if re.search(r"\boggi\b", tl):
            return oggi, oggi, "Oggi"
        if re.search(r"\bieri\b", tl):
            g = oggi - datetime.timedelta(days=1)
            return g, g, "Ieri"
        if re.search(r"\b(?:settimana\s+scorsa|scorsa\s+settimana)\b", tl):
            lun = oggi - datetime.timedelta(days=oggi.weekday() + 7)
            return lun, lun + datetime.timedelta(days=6), "La settimana scorsa"
        if re.search(r"\b(?:questa\s+settimana|settimana)\b", tl):
            return oggi - datetime.timedelta(days=oggi.weekday()), oggi, "Questa settimana"
        if re.search(r"\b(?:mese\s+scorso|scorso\s+mese)\b", tl):
            fine = primo - datetime.timedelta(days=1)
            return fine.replace(day=1), fine, f"A {MESI_IT[fine.month - 1]}"
        if re.search(r"\bquest['’ ]?anno\b|\bnell['’ ]?anno\b", tl):
            return oggi.replace(month=1, day=1), oggi, f"Nel {oggi.year}"
        m = re.search(r"\b(?:a|di|in|nel\s+mese\s+di)\s+(" + _senza_accenti(_MESI_RE) + r")\b", tl)
        if m:
            n = [_senza_accenti(x) for x in MESI_IT].index(m.group(1)) + 1
            anno = oggi.year if n <= oggi.month else oggi.year - 1
            da = datetime.date(anno, n, 1)
            fine = (da.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - datetime.timedelta(days=1)
            return da, min(fine, oggi) if (anno, n) == (oggi.year, oggi.month) else fine, f"A {MESI_IT[n - 1]}"
        return primo, oggi, f"Questo mese ({MESI_IT[oggi.month - 1]})"

    @staticmethod
    def testo_riepilogo(r, etichetta, cosa=""):
        if not r["n"]:
            return f"💶 {etichetta}{cosa}: nessuna spesa segnata. Dimmi per esempio «ho speso 23 € di benzina»."
        righe = [f"💶 {etichetta}{cosa} hai speso **{euro(r['totale'])}** ({r['n']} spes{'a' if r['n'] == 1 else 'e'})."]
        if len(r["per_categoria"]) > 1 or not cosa:
            righe += [f"- {c['emoji']} {c['nome']}: {euro(c['totale'])} ({c['perc']}%)" for c in r["per_categoria"][:6]]
        b = r.get("budget")
        if b:
            oggi = datetime.date.today()
            fine_mese = ((oggi.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - oggi).days
            if b["resta"] >= 0:
                righe.append(f"🎯 Budget: {euro(b['usato'])} su {euro(b['totale'])} ({b['perc']}%) · ti restano **{euro(b['resta'])}**"
                             + (f", circa {euro(b['resta'] / fine_mese)} al giorno fino a fine mese." if r["a"][:7] == oggi.isoformat()[:7] and fine_mese > 0 else "."))
            else:
                righe.append(f"🚨 Budget superato: {euro(b['usato'])} su {euro(b['totale'])} (+{euro(-b['resta'])}).")
        if r["prima"]:
            dlt = round(100 * (r["totale"] - r["prima"]) / r["prima"])
            righe.append(f"{'📉' if dlt < 0 else '📈'} Rispetto al periodo prima ({euro(r['prima'])}): {'+' if dlt > 0 else ''}{dlt}%" + (" 👍" if dlt < 0 else ""))
        return "\n".join(righe)

    def router(self, testo, cervello=None):
        t = re.sub(r"\s+", " ", (testo or "").strip())
        tl = t.lower().rstrip(" ?!.")
        if re.match(r"^(?:cancella|elimina|togli|annulla)\s+(?:l['’]\s*)?ultima\s+spesa$", tl):
            sp = self.tutte()
            if not sp:
                return {"testo": "💶 Non c'è nessuna spesa da cancellare."}
            x = sp[-1]
            self.elimina(x["id"])
            return {"testo": f"🗑️ Cancellata l'ultima spesa: {x['descrizione']} ({euro(x['importo'])}, {x['data']})."}
        m = _RE_BUDGET.match(t.rstrip(" ?!."))
        if m and re.search(r"\d", m.group("imp")):
            imp = trova_importo(m.group("imp"), serve_valuta=False)[0]
            cat = categoria_spesa(m.group("cat") or "") if m.group("cat") and not re.fullmatch(r"\s*(?:totale|generale|mensile)\s*", m.group("cat") or "") else None
            if imp is None:
                return None
            b = self.imposta_budget(imp, cat)
            cosa = f"per {CAT_SPESE[cat]['emoji']} {CAT_SPESE[cat]['nome'].lower()}" if cat else "del mese"
            oggi = datetime.date.today()
            usato = self._tot_mese(self._carica(), oggi.isoformat()[:7], cat)
            return {"testo": f"🎯 Budget {cosa}: **{euro(imp)}**. Finora a {MESI_IT[oggi.month - 1]} ne hai usati {euro(usato)} ({round(100 * usato / imp)}%). Ti avviso all'80% e se lo superi.",
                    "budget": b}
        m = _RE_SPESE_Q.match(tl)
        if m and not re.search(r"\b(?:lista|liste)\b", tl):
            resto = m.group("resto") or ""
            da, a, etichetta = self.periodo(resto)
            parole = [w for w in _normalizza(resto).split() if len(w) > 3 and w not in _STOP and w not in (
                "questo", "questa", "mese", "settimana", "scorso", "scorsa", "anno", "oggi", "ieri", "finora", "fino", "adesso", "totale", "spese", "speso",
                "budget", "nell", "quest", "soldi", "messo") and _senza_accenti(w) not in [_senza_accenti(x) for x in MESI_IT]]
            filtro, cat, cosa = None, None, ""
            for w in parole:
                if any(_senza_accenti(w)[:max(4, len(w) - 1)] in _senza_accenti(x["descrizione"]).lower() for x in self.tutte()):
                    filtro, cosa = _senza_accenti(w)[:max(4, len(w) - 1)], f" per «{w}»"
                    break
            if not filtro and parole:
                cat = categoria_spesa(" ".join(parole))
                if cat:
                    cosa = f" in {CAT_SPESE[cat]['emoji']} {CAT_SPESE[cat]['nome'].lower()}"
            r = self.riepilogo(da, a, filtro, cat)
            return {"testo": self.testo_riepilogo(r, etichetta, cosa), "spese": dict({k: r[k] for k in ("da", "a", "totale", "n", "per_categoria", "prima")},
                    titolo=etichetta + cosa, **({"budget": r["budget"]} if r.get("budget") else {}), voci=r["voci"][:8])}
        forte = _RE_SPESA_FORTE.search(t)
        if not forte and not _RE_SPESA_DEBOLE.search(t):
            return None
        if _RE_SPESA_DOMANDA.search(t) or len(t) > 160:
            return None
        imp, span = trova_importo(t, serve_valuta=not forte)
        if imp is None:
            return None
        data = datetime.date.today()
        if re.search(r"\b(?:l['’]\s*altro\s*ieri|avantieri)\b", tl):
            data -= datetime.timedelta(days=2)
        elif re.search(r"\bieri\b", tl):
            data -= datetime.timedelta(days=1)
        desc = t[:span[0]] + " " + t[span[1]:]
        desc = re.sub(r"(?i)\b(?:(?:maik|zep)[,!]?|oggi|ieri|l['’]\s*altro\s*ieri|avantieri|stamattina|stasera|appena|euro|eur|€|in\s+tutto|in\s+totale|circa|tipo)\b", " ", desc)
        desc = re.sub(r"(?i)\b(?:ho|abbiamo)\s+(?:speso|pagato|comprato|preso|fatto|ordinato|prenotato|dato|rinnovato)\b|\bspesi\b|\bpagati\b|\b(?:segna|registra|aggiungi|metti)(?:mi)?\s+(?:una\s+)?spesa(?:\s+di)?\b|\bnuova\s+spesa\b|^\s*spesa\s*[:\-]", " ", desc)
        desc = re.sub(r"\s+", " ", desc).strip(" ,.:;-!")
        for _ in range(3):
            desc = re.sub(r"(?i)^(?:di|per|al|allo|alla|ai|agli|alle|a|in|da|dal|dalla|nel|nella|un|una|uno|il|lo|la|i|gli|le|l['’]|e|del|della|dei|delle|con)\s+", "", desc).strip()
            desc = re.sub(r"(?i)\s+(?:di|per|al|alla|a|in|da|e|con)$", "", desc).strip()
        desc = re.sub(r"(?i)^l['’]\s*", "", desc)
        cat = categoria_spesa(desc) or categoria_spesa(t)
        s, err = self.aggiungi(imp, desc, cat, data)
        if not s:
            return {"testo": "💶 " + err}
        c = CAT_SPESE[s["categoria"]]
        oggi = datetime.date.today()
        tot = self._tot_mese(self._carica(), oggi.isoformat()[:7])
        quando = "" if data == oggi else (" (ieri)" if (oggi - data).days == 1 else f" ({data.strftime('%d/%m')})")
        testo = f"💶 Segnato: **{s['descrizione']}** {euro(s['importo'])}{quando} → {c['emoji']} {c['nome']}. Questo mese: {euro(tot)}."
        if s.get("avviso"):
            testo += "\n" + s["avviso"]
        return {"testo": testo, "spesa": s}

    # ── 💡 bollette e scontrini (da un PDF o una foto già letti) ──
    @staticmethod
    def dati_bolletta(testo):
        t = re.sub(r"[ \t]+", " ", testo or "")
        imp = None
        m = re.search(r"(?:totale\s+(?:da\s+pagare|fattura|bolletta|dovuto|documento|complessivo)|importo(?:\s+(?:da\s+pagare|totale|dovuto|complessivo))?|da\s+pagare|totale\s+euro|totale)"
                      r"[^\d\n]{0,40}?(\d{1,3}(?:\.\d{3})*,\d{2}|\d+[.,]\d{2})", t, re.I)
        if m:
            imp = _num_it(m.group(1))
        else:
            imp = trova_importo(t)[0]
        scad = None
        m = re.search(r"(?:entro\s+(?:il\s+)?|scadenza(?:\s+(?:del\s+)?(?:pagamento|bolletta|fattura))?\s*[:\-]?\s*(?:il\s+)?|scade\s+il\s+|data\s+(?:di\s+)?scadenza\s*[:\-]?\s*)"
                      r"(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{2,4})", t, re.I)
        if m:
            g, me, a = int(m.group(1)), int(m.group(2)), int(m.group(3))
            a += 2000 if a < 100 else 0
            try:
                scad = datetime.date(a, me, g)
            except ValueError:
                scad = None
        else:
            m = re.search(r"(?:entro\s+(?:il\s+)?|scadenza\s*[:\-]?\s*(?:il\s+)?|scade\s+il\s+)(\d{1,2})\s+(" + _MESI_RE + r")\s+(\d{4})", t, re.I)
            if m:
                try:
                    scad = datetime.date(int(m.group(3)), MESI_IT.index(m.group(2).lower()) + 1, int(m.group(1)))
                except ValueError:
                    scad = None
        tl = t.lower()
        tipo = next((n for rx, n in ((r"\bluce\b|energia\s+elettrica|\bkwh\b", "luce"), (r"\bgas\b|\bsmc\b|metano", "gas"), (r"\bacqua\b|idric", "acqua"),
                                     (r"\btari\b|rifiuti", "rifiuti (TARI)"), (r"fibra|internet|adsl|telefon|mobile|giga", "internet e telefono"),
                                     (r"condomin", "condominio")) if re.search(rx, tl)), None)
        return {"importo": round(imp, 2) if imp else None, "scadenza": scad, "tipo": tipo}

    def registra_documento(self, testo, nome="", scontrino=False, cervello=None):
        """Bolletta o scontrino letti da un file → spesa (e la scadenza in calendario). → {testo, spesa?, evento?}"""
        d = self.dati_bolletta(testo)
        if not d["importo"] and cervello and cervello.disponibile():
            j = cervello.pensa_json("Da questo documento (bolletta, fattura o scontrino) estrai in JSON: importo totale da pagare (numero), "
                                    "scadenza (AAAA-MM-GG o vuoto), tipo (luce, gas, acqua, telefono, … o vuoto).\n\n" + testo[:6000]) or {}
            try:
                d["importo"] = round(float(str(j.get("importo", "")).replace(",", ".")), 2) or None
            except ValueError:
                pass
            try:
                d["scadenza"] = d["scadenza"] or (datetime.date.fromisoformat(str(j.get("scadenza"))[:10]) if j.get("scadenza") else None)
            except ValueError:
                pass
            d["tipo"] = d["tipo"] or (str(j.get("tipo") or "").strip().lower() or None)
        if not d["importo"]:
            return {"testo": "💶 Non trovo l'importo in questo documento. Dimmelo tu: «ho pagato la bolletta della luce 87,40»."}
        if scontrino:
            prima = next((r.strip() for r in (testo or "").split("\n") if len(r.strip()) > 2), "")
            desc, cat = ("Scontrino " + (prima.title() if prima.isupper() else prima)[:40]).strip(), categoria_spesa(testo) or "spesa"
        else:
            desc, cat = ("Bolletta " + d["tipo"]) if d["tipo"] else ("Bolletta" if re.search(r"bollett|fattur", (testo + nome).lower()) else (nome or "Documento")), "bollette"
        s, err = self.aggiungi(d["importo"], desc, cat, fonte="documento", scadenza=d["scadenza"].isoformat() if d["scadenza"] else None)
        if not s:
            return {"testo": "💶 " + err}
        c = CAT_SPESE[s["categoria"]]
        out = {"testo": f"{c['emoji']} **{s['descrizione']}**: {euro(s['importo'])} segnata nelle spese ({c['nome']}).", "spesa": s}
        if d["scadenza"]:
            quando = datetime.datetime.combine(d["scadenza"], datetime.time(9, 0))
            e, _ = CAL.aggiungi(f"Scade: {s['descrizione'].lower()} ({euro(s['importo'])})", quando, 15)
            if e:
                gg = (d["scadenza"] - datetime.date.today()).days
                out["evento"] = e
                out["testo"] += (f" Scade il **{d['scadenza'].day} {MESI_IT[d['scadenza'].month - 1]} {d['scadenza'].year}**"
                                 + (f" (tra {gg} giorni)" if 1 < gg < 60 else " (domani!)" if gg == 1 else " (oggi!)" if gg == 0 else " (è già scaduta!)" if gg < 0 else "")
                                 + ": l'ho messa in calendario e quel giorno ti avviso. 📅")
        if s.get("avviso"):
            out["testo"] += "\n" + s["avviso"]
        return out


SPESE = Spese()
_RE_DOC_SPESA = re.compile(r"\b(?:aggiungi|metti|segna|registra|inserisci|salva|mettila|segnala|aggiungila|registrala|segnalo)\b[^.?!\n]{0,40}\b(?:spes[ae]|bollett[ae]|scontrin[oi]|fattur[ae]|ricevut[ae])\b"
                           r"|\b(?:quanto|quando)\b[^.?!\n]{0,30}\b(?:pagare|scade)\b[^.?!\n]{0,30}\b(?:segna|calendario|ricorda)", re.I)


# ── ✅ ABITUDINI: serie di giorni, obiettivi al giorno, promemoria ──
_EMOJI_ABITUDINI = [(r"acqua|bere|bicchier", "💧"), (r"palestra|allenament|pesi|workout|flession|addominal", "💪"), (r"corr|corsa|running|jogging", "🏃"),
                    (r"cammin|passi|passeggiat", "🚶"), (r"legg|libr|pagin|capitol", "📚"), (r"medit|respir|mindful|yoga", "🧘"), (r"stud|ripass|esercizi", "📖"),
                    (r"dorm|sonno|letto\s+entro|a\s+letto", "😴"), (r"frutt|verdur|mangi|dieta|cucin", "🍎"), (r"fum|sigarett", "🚭"), (r"inglese|spagnolo|lingua|duolingo", "🗣️"),
                    (r"diario|scriv", "✍️"), (r"chitarr|piano|suon|musica", "🎸"), (r"vitamin|medicin|pillol", "💊"), (r"denti|filo", "🦷"), (r"pianta|piante|annaff", "🪴"),
                    (r"bici|cicl", "🚴"), (r"nuot|piscina", "🏊"), (r"telefono|social|schermo", "📵")]
_VERBI_INFINITO = {"corso": "correre", "letto": "leggere", "bevuto": "bere", "camminato": "camminare", "studiato": "studiare", "preso": "prendere",
                   "mangiato": "mangiare", "scritto": "scrivere", "meditato": "meditare", "suonato": "suonare", "ripassato": "ripassare", "nuotato": "nuotare",
                   "fatto": "fare", "dormito": "dormire", "annaffiato": "annaffiare", "allenato": "allenare", "pedalato": "pedalare"}
_GIORNI_AB = [(r"lun(?:ed[iì])?", 0), (r"mar(?:ted[iì])?", 1), (r"mer(?:coled[iì])?", 2), (r"gio(?:ved[iì])?", 3), (r"ven(?:erd[iì])?", 4), (r"sab(?:ato)?", 5), (r"dom(?:enica)?", 6)]
_RE_AB_TEMPO = re.compile(r"\b(?:ogni\s+giorno|tutti\s+i\s+giorni|al\s+giorno|ogni\s+(?:luned|marted|mercoled|gioved|venerd|sabato|domenica|mattina|sera)\w*|"
                          r"\d+\s+volte\s+(?:a(?:lla)?|alla|per)\s+settimana|nei\s+giorni\s+feriali|(?:dal\s+)?luned[iì]\s+al\s+venerd[iì]|nel\s+weekend|nel\s+fine\s+settimana|"
                          r"(?:il|di|ogni)\s+(?:luned|marted|mercoled|gioved|venerd|sabato|domenica)\w*)\b", re.I)
_RE_AB_CREA = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:nuova|aggiungi(?:\s+una)?|crea(?:\s+una)?|imposta(?:\s+una)?|metti(?:\s+una)?)\s+abitudine\s*[:,]?\s*(?P<a>.+)"
                         r"|voglio\s+(?:prendere\s+l['’]\s*abitudine\s+di\s+|abituarmi\s+a\s+|iniziare\s+a\s+|cominciare\s+a\s+|riuscire\s+a\s+)?(?P<b>.+))$", re.I)
_RE_AB_FATTO = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:oggi\s+|anche\s+oggi\s+)?ho\s+(?:appena\s+|già\s+|gia\s+)?(?P<v>fatto|finito|completato|bevuto|letto|meditato|corso|camminato|studiato|preso|"
                          r"mangiato|scritto|suonato|ripassato|nuotato|dormito|annaffiato|pedalato)|(?P<v2>fatto|completato|finito)\s*[:!,]|segna(?:mi)?\s+(?:che\s+ho\s+(?:fatto\s+)?|come\s+fatt[oa]\s+)?|"
                          r"mi\s+sono\s+(?P<v3>allenat[oa]))\s*(?P<resto>.*)$", re.I)
_RE_AB_ELENCO = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:come\s+vanno|come\s+sto\s+andando\s+con)\s+(?:le\s+)?(?:mie\s+)?abitudini|(?:le\s+)?(?:mie\s+)?abitudini|"
                           r"(?:i\s+)?(?:miei\s+)?obiettivi\s+(?:di\s+oggi|giornalieri)|cosa\s+(?:mi\s+)?manca\s+(?:da\s+fare\s+)?oggi|serie|le\s+mie\s+serie)$", re.I)
_TRAGUARDI = (3, 7, 14, 21, 30, 50, 75, 100, 150, 200, 365)


class Abitudini:
    def __init__(self):
        self._lock = threading.Lock()
        self.avvisi = []

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "abitudini.json")

    def _carica(self):
        try:
            with open(self._file(), encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                for k, v in (("abitudini", []), ("log", {}), ("avvisati", {})):
                    d.setdefault(k, v)
                return d
        except Exception:
            pass
        return {"abitudini": [], "log": {}, "avvisati": {}}

    def _salva(self, d):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(tmp, self._file())

    def elenco(self):
        return self._carica()["abitudini"]

    @staticmethod
    def interpreta(testo):
        """«bere 8 bicchieri d'acqua al giorno alle 10», «palestra lun mer ven alle 19», «leggere 3 volte a settimana» → campi."""
        t = re.sub(r"\s+", " ", testo or "").strip(" .!?,")
        tl = t.lower()
        giorni, settimanale = list(range(7)), 0
        m = re.search(r"\b(\d+)\s+volte\s+(?:a(?:lla)?|per)\s+settimana\b", tl)
        if m:
            settimanale = max(1, min(7, int(m.group(1))))
        elif re.search(r"\bnei\s+giorni\s+feriali\b|\b(?:dal\s+)?luned[iì]\s+al\s+venerd[iì]\b|\bferiali\b", tl):
            giorni = [0, 1, 2, 3, 4]
        elif re.search(r"\bnel\s+(?:weekend|fine\s+settimana)\b", tl):
            giorni = [5, 6]
        else:
            g = sorted({n for rx, n in _GIORNI_AB if re.search(r"\b" + rx + r"\b", tl) and not re.search(r"\b(?:ogni|tutti\s+i)\s+giorn", tl)})
            if g and not re.search(r"\b(?:ogni\s+giorno|tutti\s+i\s+giorni|al\s+giorno)\b", tl):
                giorni = g
        ora = ""
        m = re.search(r"\b(?:alle|verso\s+le|ore)\s+(\d{1,2})(?:[:.](\d{2}))?\b", tl)
        if m and int(m.group(1)) < 24:
            ora = f"{int(m.group(1)):02d}:{int(m.group(2) or 0):02d}"
        elif re.search(r"\b(?:la|di|ogni)\s+mattina\b", tl):
            ora = "08:00"
        elif re.search(r"\b(?:la|di|ogni)\s+sera\b", tl):
            ora = "21:00"
        obiettivo, unita = 1, ""
        m = re.search(r"\b(\d+)\s+(bicchier\w*|pagin\w*|minut\w*|km|chilometri|passi|volte|esercizi|flession\w*|capitol\w*|parole|ore|litri|addominal\w*|serie)\b", tl)
        if m and not re.search(r"\bvolte\s+(?:a(?:lla)?|per)\s+settimana", tl[m.start():m.end() + 20]) and re.match(r"bicchier|volte", m.group(2)):
            obiettivo, unita = max(1, min(100, int(m.group(1)))), m.group(2)     # si contano bicchieri e volte; «leggere 20 pagine» = fatto o non fatto
        nome = _RE_AB_TEMPO.sub(" ", t)
        nome = re.sub(r"(?i)\b(?:alle|verso\s+le|ore)\s+\d{1,2}(?:[:.]\d{2})?\b|\b(?:la|di|ogni)\s+(?:mattina|sera)\b|\b\d+\s+volte\s+(?:a(?:lla)?|per)\s+settimana\b", " ", nome)
        g_rx = "|".join(rx for rx, _ in _GIORNI_AB)
        nome = re.sub(r"(?i)(?:\b(?:il|di|e|,)\s*)?\b(?:" + g_rx + r")\b(?:\s*(?:,|e)\s*\b(?:" + g_rx + r")\b)*", " ", nome) if giorni != list(range(7)) and len(giorni) < 7 else nome
        nome = re.sub(r"\s+", " ", nome).strip(" ,.:;-")
        nome = re.sub(r"(?i)^(?:di|a|che|l['’]\s*abitudine\s+di)\s+", "", nome).strip()
        nome = (nome[:1].upper() + nome[1:])[:60] if nome else ""
        emoji = next((e for rx, e in _EMOJI_ABITUDINI if re.search(rx, _senza_accenti(tl))), "⭐")
        return {"nome": nome, "emoji": emoji, "giorni": giorni, "settimanale": settimanale, "ora": ora, "obiettivo": obiettivo, "unita": unita}

    def crea(self, nome, emoji="⭐", giorni=None, settimanale=0, ora="", obiettivo=1, unita=""):
        nome = re.sub(r"\s+", " ", str(nome or "")).strip()[:60]
        if len(nome) < 2:
            return None, "manca il nome dell'abitudine"
        if ora and not re.fullmatch(r"\d{2}:\d{2}", str(ora)):
            ora = ""
        giorni = sorted({int(g) for g in (giorni if giorni else range(7)) if 0 <= int(g) <= 6}) or list(range(7))
        with self._lock:
            d = self._carica()
            vecchia = next((a for a in d["abitudini"] if _normalizza(a["nome"]) == _normalizza(nome)), None)
            if not vecchia and len(d["abitudini"]) >= 30:
                return None, "hai già 30 abitudini: eliminane qualcuna"
            a = {"id": vecchia["id"] if vecchia else uuid.uuid4().hex[:8], "nome": nome, "emoji": str(emoji or "⭐")[:4], "giorni": giorni,
                 "settimanale": int(settimanale or 0), "ora": ora or "", "obiettivo": max(1, int(obiettivo or 1)), "unita": str(unita or "")[:20],
                 "creata": vecchia["creata"] if vecchia else datetime.date.today().isoformat()}
            d["abitudini"] = [x for x in d["abitudini"] if x["id"] != a["id"]] + [a]
            self._salva(d)
        return a, None

    def elimina(self, aid):
        with self._lock:
            d = self._carica()
            prima = len(d["abitudini"])
            d["abitudini"] = [a for a in d["abitudini"] if a["id"] != aid]
            for g in d["log"].values():
                g.pop(aid, None)
            self._salva(d)
            return len(d["abitudini"]) < prima

    _GENERICHE = {"pagine", "minuti", "ore", "km", "chilom", "volte", "passi", "appena", "sera", "mattin", "oggi", "tutti", "tutte", "tutto", "anche", "finalm"}

    def trova(self, testo, verbo=""):
        """L'abitudine di cui parla una frase («ho bevuto un bicchiere d'acqua» → «Bere 8 bicchieri d'acqua»).
        Se la frase ha parole sue, almeno una deve esserci nel nome; se c'è solo il verbo («ho meditato»), basta il verbo."""
        contenuto = {w for w in _token(testo) if not w.isdigit() and w not in self._GENERICHE and w not in {v[:6] for v in _VERBI_INFINITO}}
        tv = {_VERBI_INFINITO.get(verbo.lower(), verbo.lower())[:6]} if verbo else set()
        tv |= {_VERBI_INFINITO[w][:6] for w in _normalizza(testo).split() if w in _VERBI_INFINITO}
        tv.discard("fare")
        meglio, punti = None, 0
        for a in self.elenco():
            ta = _token(a["nome"]) | {w[:6] for w in _normalizza(a["nome"]).split() if len(w) > 2}
            pc, pv = len(contenuto & ta), len(tv & ta)
            p = pc * 2 + pv if contenuto else pv
            if (pc if contenuto else pv) and p > punti:
                meglio, punti = a, p
        return meglio

    @staticmethod
    def _previsto(a, giorno):
        return bool(a.get("settimanale")) or giorno.weekday() in a.get("giorni", list(range(7)))

    @staticmethod
    def _fatto(d, a, giorno):
        return d["log"].get(giorno.isoformat(), {}).get(a["id"], 0)

    @staticmethod
    def _inizio(a, d, oggi):
        """Da quando conta: la creazione, o il primo giorno segnato «a posteriori» se viene prima."""
        try:
            creata = datetime.date.fromisoformat(a.get("creata", oggi.isoformat()))
        except ValueError:
            creata = oggi
        segnati = [g for g, v in d["log"].items() if v.get(a["id"])]
        return min(creata, datetime.date.fromisoformat(min(segnati))) if segnati else creata

    def serie(self, a, d=None, oggi=None):
        """→ (serie attuale, record). Giornaliere: giorni previsti di fila; «N volte a settimana»: settimane di fila."""
        d = d or self._carica()
        oggi = oggi or datetime.date.today()
        inizio = max(self._inizio(a, d, oggi), oggi - datetime.timedelta(days=730))
        if a.get("settimanale"):
            n = a["settimanale"]
            sett = []
            lun = oggi - datetime.timedelta(days=oggi.weekday())
            while lun + datetime.timedelta(days=6) >= inizio:
                c = sum(1 for i in range(7) if self._fatto(d, a, lun + datetime.timedelta(days=i)) >= a.get("obiettivo", 1))
                sett.append(c >= n)
                lun -= datetime.timedelta(days=7)
            cur = 0
            for i, ok in enumerate(sett):
                if ok:
                    cur += 1
                elif i > 0:
                    break
            rec = run = 0
            for ok in reversed(sett):
                run = run + 1 if ok else 0
                rec = max(rec, run)
            return cur, max(rec, cur)
        giorni = []
        g = oggi
        while g >= inizio:
            if self._previsto(a, g):
                giorni.append((g, self._fatto(d, a, g) >= a.get("obiettivo", 1)))
            g -= datetime.timedelta(days=1)
        cur = 0
        for i, (g, ok) in enumerate(giorni):
            if ok:
                cur += 1
            elif not (i == 0 and g == oggi):        # oggi non è ancora finito: non spezza la serie
                break
        rec = run = 0
        for g, ok in reversed(giorni):
            run = run + 1 if ok else 0
            rec = max(rec, run)
        return cur, max(rec, cur)

    def stato(self, a, d=None, oggi=None):
        d = d or self._carica()
        oggi = oggi or datetime.date.today()
        cur, rec = self.serie(a, d, oggi)
        inizio = self._inizio(a, d, oggi)
        sett = []
        for i in range(6, -1, -1):
            g = oggi - datetime.timedelta(days=i)
            sett.append({"data": g.isoformat(), "fatto": self._fatto(d, a, g), "previsto": g >= inizio and self._previsto(a, g)})   # prima che esistesse non conta
        lun = oggi - datetime.timedelta(days=oggi.weekday())
        questa = sum(1 for i in range(oggi.weekday() + 1) if self._fatto(d, a, lun + datetime.timedelta(days=i)) >= a.get("obiettivo", 1))
        return dict(a, oggi=self._fatto(d, a, oggi), previsto_oggi=self._previsto(a, oggi), fatta_oggi=self._fatto(d, a, oggi) >= a.get("obiettivo", 1),
                    serie=cur, record=rec, settimana=sett, questa_settimana=questa)

    def tutte_stato(self):
        d = self._carica()
        return [self.stato(a, d) for a in d["abitudini"]]

    def segna(self, aid, n=1, giorno=None):
        giorno = giorno or datetime.date.today()
        with self._lock:
            d = self._carica()
            a = next((x for x in d["abitudini"] if x["id"] == aid), None)
            if not a:
                return None
            prima_cur = self.serie(a, d, giorno)[0]
            era_fatta = self._fatto(d, a, giorno) >= a["obiettivo"]
            log = d["log"].setdefault(giorno.isoformat(), {})
            log[aid] = max(0, min(a["obiettivo"] * 5, log.get(aid, 0) + int(n)))
            if not log[aid]:
                log.pop(aid)
            self._salva(d)
            st = self.stato(a, d, giorno)
        st["appena_fatta"] = st["fatta_oggi"] and not era_fatta
        st["traguardo"] = st["serie"] if st["appena_fatta"] and st["serie"] in _TRAGUARDI and st["serie"] > prima_cur else None
        return st

    @staticmethod
    def riga(st):
        prog = f"{st['oggi']}/{st['obiettivo']}{(' ' + st['unita']) if st['unita'] else ''}" if st["obiettivo"] > 1 else ("✅" if st["fatta_oggi"] else "—")
        if st.get("settimanale"):
            prog = f"{st['questa_settimana']}/{st['settimanale']} questa settimana"
        serie = f" · 🔥 {st['serie']} {'settiman' + ('a' if st['serie'] == 1 else 'e') if st.get('settimanale') else 'giorn' + ('o' if st['serie'] == 1 else 'i')}" if st["serie"] else ""
        return f"{st['emoji']} **{st['nome']}**: {prog}{serie}"

    def testo_segnato(self, st):
        nome = f"{st['emoji']} {st['nome']}"
        if st["fatta_oggi"]:
            if st.get("settimanale"):
                base = f"✅ {nome}: fatto! {st['questa_settimana']}/{st['settimanale']} questa settimana."
            else:
                base = f"✅ {nome}: fatto per oggi!" + (f" ({st['oggi']}/{st['obiettivo']} {st['unita']})".rstrip() if st["obiettivo"] > 1 else "")
            if st["serie"] > 1:
                u = "settimane" if st.get("settimanale") else "giorni"
                base += f" 🔥 Serie: **{st['serie']} {u} di fila**" + (" — è il tuo record! 🏆" if st["serie"] >= st["record"] and st["serie"] > 2 else f" (record: {st['record']})") + "."
            if st.get("traguardo"):
                base += f"\n🎉 **{st['traguardo']} {'settimane' if st.get('settimanale') else 'giorni'} di fila!** Bravissimo, continua così!"
            return base
        manca = st["obiettivo"] - st["oggi"]
        return f"{nome}: {st['oggi']}/{st['obiettivo']} {st['unita']}".rstrip() + f" oggi. Ne mancano {manca}, ce la fai! 💪"

    def router(self, testo):
        t = re.sub(r"\s+", " ", (testo or "").strip())
        tl = t.lower().rstrip(" ?!.")
        m = re.match(r"^(?:elimina|cancella|togli|rimuovi)\s+(?:l['’]\s*)?abitudine\s+(.+)$", tl)
        if m:
            a = self.trova(m.group(1)) or next((x for x in self.elenco() if _normalizza(m.group(1)) in _normalizza(x["nome"])), None)
            if not a:
                return {"testo": f"✅ Non trovo l'abitudine «{m.group(1)}»."}
            self.elimina(a["id"])
            return {"testo": f"🗑️ Abitudine eliminata: {a['emoji']} {a['nome']}."}
        if _RE_AB_ELENCO.match(tl):
            if not self.elenco():
                return {"testo": "✅ Non hai ancora abitudini. Prova: «nuova abitudine: bere 8 bicchieri d'acqua al giorno» o «voglio leggere ogni sera alle 22»."}
            st = self.tutte_stato()
            fatte = sum(1 for x in st if x["fatta_oggi"] or (x.get("settimanale") and x["questa_settimana"] >= x["settimanale"]))
            prev = [x for x in st if x["previsto_oggi"]]
            testa = f"✅ Le tue abitudini (oggi {fatte}/{len(prev)} fatte):" if prev else "✅ Le tue abitudini:"
            return {"testo": testa + "\n" + "\n".join("- " + self.riga(x) for x in st), "abitudini": st}
        m = _RE_AB_CREA.match(t.rstrip(" .!"))
        if m:
            corpo = m.group("a") or m.group("b")
            if m.group("b") and not _RE_AB_TEMPO.search(corpo):
                return None                             # «voglio una pizza» non è un'abitudine
            x = self.interpreta(corpo)
            if not x["nome"]:
                return {"testo": "✅ Che abitudine? Per esempio «nuova abitudine: palestra lun mer ven alle 19»."}
            a, err = self.crea(**x)
            if not a:
                return {"testo": "✅ " + err}
            if a.get("settimanale"):
                quando = f"{a['settimanale']} volte a settimana"
            elif len(a["giorni"]) == 7:
                quando = "ogni giorno"
            else:
                quando = ", ".join(GIORNI_LUNGHI[g] for g in a["giorni"])
            obj = f", obiettivo {a['obiettivo']} {a['unita']}".rstrip() + " al giorno" if a["obiettivo"] > 1 else ""
            promem = f" Ti ricordo alle {a['ora']} se non l'hai ancora fatto." if a["ora"] else " Se vuoi un promemoria dimmi l'ora (es. «… alle 19»)."
            return {"testo": f"✅ Nuova abitudine: {a['emoji']} **{a['nome']}** — {quando}{obj}.{promem} Quando la fai dimmi «ho fatto {a['nome'].lower()}» 🔥",
                    "abitudine": self.stato(a)}
        m = _RE_AB_FATTO.match(t.rstrip(" .!"))
        if m and self.elenco():
            verbo = m.group("v") or m.group("v2") or (("allenato") if m.group("v3") else "")
            resto = m.group("resto") or ""
            a = self.trova(resto + " " + (verbo or ""), verbo or "")
            if not a:
                return None
            n = 1
            mn = re.search(r"\b(\d{1,4})\b", resto)
            if a["obiettivo"] > 1:
                if mn:
                    n = int(mn.group(1))
                elif re.search(r"\b(?:tutt[io]|tutte)\b", resto.lower()):
                    n = a["obiettivo"]
            if re.search(r"\bieri\b", tl):
                st = self.segna(a["id"], n, datetime.date.today() - datetime.timedelta(days=1))
            else:
                st = self.segna(a["id"], n)
            return {"testo": self.testo_segnato(st), "abitudine": st}
        return None

    def controlla_promemoria(self, ora=None):
        ora = ora or datetime.datetime.now()
        oggi = ora.date()
        nuovi = []
        with self._lock:
            d = self._carica()
            avv = d["avvisati"].setdefault(oggi.isoformat(), [])
            for a in d["abitudini"]:
                if not a.get("ora") or a["id"] in avv or not self._previsto(a, oggi):
                    continue
                h, mi = map(int, a["ora"].split(":"))
                t0 = datetime.datetime.combine(oggi, datetime.time(h, mi))
                if not (t0 <= ora < t0 + datetime.timedelta(minutes=90)):
                    continue
                st = self.stato(a, d, oggi)
                if st["fatta_oggi"] or (a.get("settimanale") and st["questa_settimana"] >= a["settimanale"]):
                    continue
                avv.append(a["id"])
                serie = f" Sei a {st['serie']} {'settimane' if a.get('settimanale') else 'giorni'} di fila 🔥: non spezzare la serie!" if st["serie"] >= 2 else ""
                nuovi.append({"id": a["id"], "emoji": a["emoji"], "nome": a["nome"],
                              "testo": f"⏰ {a['emoji']} È ora di: **{a['nome']}**" + (f" ({st['oggi']}/{a['obiettivo']} {a['unita']})".rstrip() if a["obiettivo"] > 1 else "") + "." + serie})
            d["avvisati"] = {k: v for k, v in d["avvisati"].items() if k >= (oggi - datetime.timedelta(days=3)).isoformat()}
            self._salva(d)
            self.avvisi = (self.avvisi + nuovi)[-20:]
        return nuovi

    def prendi_avvisi(self):
        with self._lock:
            a, self.avvisi = self.avvisi, []
        return a


ABITUDINI = Abitudini()


# ── 🧠 RICERCA PER SIGNIFICATO: gli «embedding» di Ollama (es. nomic-embed-text), salvati su disco ──
class Vettori:
    def __init__(self):
        self._lock = threading.Lock()
        self._dati = None
        self._q = {}
        self.attiva, self.errore, self._provato = False, "", 0.0
        self._evento = threading.Event()
        self._thread = None
        self.lavoro = False

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "vettori.json")

    def _carica(self):
        if self._dati is None:
            try:
                with open(self._file(), encoding="utf-8") as f:
                    d = json.load(f)
                self._dati = d if isinstance(d, dict) and d.get("modello") == CONFIG["modello_embed"] else {"modello": CONFIG["modello_embed"], "v": {}}
            except Exception:
                self._dati = {"modello": CONFIG["modello_embed"], "v": {}}
        return self._dati

    def _salva(self):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(self._dati, f, separators=(",", ":"))
        os.replace(tmp, self._file())

    @staticmethod
    def chiave(testo):
        return hashlib.sha1(testo.encode("utf-8")).hexdigest()[:16]

    @staticmethod
    def _prefisso(testi, tipo):
        if "nomic" in CONFIG["modello_embed"]:          # nomic-embed-text lavora meglio così
            return [("search_query: " if tipo == "q" else "search_document: ") + t for t in testi]
        return testi

    def _chiedi(self, testi, timeout=60):
        """→ vettori normalizzati (lunghezza 1). Prova /api/embed (Ollama nuovo) e poi /api/embeddings (vecchio)."""
        base = CONFIG["ollama_base"]
        try:
            req = urllib.request.Request(base + "/api/embed", data=json.dumps({"model": CONFIG["modello_embed"], "input": testi, "keep_alive": CONFIG["keep_alive"]}).encode("utf-8"),
                                         headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                vv = json.loads(r.read().decode("utf-8")).get("embeddings") or []
        except urllib.error.HTTPError as e:
            if e.code != 404 or "model" in (e.read() or b"").decode("utf-8", "replace").lower():
                raise
            vv = []
            for t in testi:
                req = urllib.request.Request(base + "/api/embeddings", data=json.dumps({"model": CONFIG["modello_embed"], "prompt": t, "keep_alive": CONFIG["keep_alive"]}).encode("utf-8"),
                                             headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=timeout) as r:
                    vv.append(json.loads(r.read().decode("utf-8")).get("embedding") or [])
        if len(vv) != len(testi) or not all(vv):
            raise ValueError("risposta senza vettori")
        out = []
        for v in vv:
            n = math.sqrt(sum(x * x for x in v)) or 1.0
            out.append([round(x / n, 5) for x in v])
        return out

    def pronta(self):
        """Ollama ha il modello per gli embedding? (riprova ogni 5 minuti)"""
        if not CONFIG["embed"]:
            return False
        if self.attiva or time.time() - self._provato < 300:
            return self.attiva
        self._provato = time.time()
        try:
            self._chiedi(["prova"], timeout=8)
            self.attiva, self.errore = True, ""
        except Exception as e:
            self.attiva = False
            self.errore = (f"manca il modello: ollama pull {CONFIG['modello_embed']}" if isinstance(e, urllib.error.HTTPError) and e.code in (400, 404)
                           else "Ollama non risponde")[:120]
        return self.attiva

    def get(self, testo):
        return self._carica()["v"].get(self.chiave(testo))

    def vettore_domanda(self, q):
        q = (q or "").strip()[:2000]
        if not q:
            return None
        if q in self._q:
            return self._q[q]
        try:
            v = self._chiedi(self._prefisso([q], "q"), timeout=15)[0]
        except Exception:
            self.attiva, self._provato = False, time.time()
            return None
        self._q[q] = v
        if len(self._q) > 128:
            self._q.pop(next(iter(self._q)))
        return v

    def indicizza(self, pezzi, lotto=16):
        """Calcola (e salva) i vettori dei pezzi che non li hanno ancora. → quanti nuovi."""
        if not self.pronta():
            return 0
        with self._lock:
            d = self._carica()
            manca = list(dict.fromkeys(p for p in pezzi if self.chiave(p) not in d["v"]))
        n = 0
        for i in range(0, len(manca), lotto):
            parte = manca[i:i + lotto]
            try:
                vv = self._chiedi(self._prefisso(parte, "d"))
            except Exception as e:
                self.errore = str(e)[:120]
                break
            with self._lock:
                for p, v in zip(parte, vv):
                    d["v"][self.chiave(p)] = v
                n += len(parte)
                if n % (lotto * 8) == 0 or i + lotto >= len(manca):
                    self._salva()
        if n:
            with self._lock:
                vivi = {self.chiave(p) for p in pezzi}
                if len(d["v"]) > len(vivi) * 1.5 + 50:      # pulizia dei pezzi dei documenti eliminati
                    d["v"] = {k: v for k, v in d["v"].items() if k in vivi}
                self._salva()
        return n

    def _lavoratore(self, memoria):
        while True:
            self._evento.wait()
            self._evento.clear()
            try:
                self.lavoro = True
                with memoria._lock:
                    pezzi = [p for doc in memoria.documenti for p in doc.get("pezzi", [])]
                self.indicizza(pezzi)
            except Exception as e:
                print(f"  ⚠  vettori: {e}")
            finally:
                self.lavoro = False

    def programma(self, memoria):
        """In sottofondo: prepara i vettori dei documenti nuovi (la ricerca funziona subito, con le parole)."""
        if not CONFIG["embed"]:
            return
        if self._thread is None:
            self._thread = threading.Thread(target=self._lavoratore, args=(memoria,), daemon=True)
            self._thread.start()
        self._evento.set()

    def info(self, memoria):
        with memoria._lock:
            pezzi = [p for doc in memoria.documenti for p in doc.get("pezzi", [])]
        d = self._carica()
        pronti = sum(1 for p in pezzi if self.chiave(p) in d["v"])
        return {"attiva": bool(CONFIG["embed"] and self.attiva), "modello": CONFIG["modello_embed"], "pronti": pronti, "totale": len(pezzi),
                "errore": "" if self.attiva else (self.errore if CONFIG["embed"] else "spenta (MAIK_EMBED=0)"), "lavoro": self.lavoro}


VETTORI = Vettori()


# ── 📊 LA TUA SETTIMANA ──
_RE_SETTIMANA = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:com['’]?\s*[eè]\s+andata\s+(?:la\s+)?(?:mia\s+)?settimana|come\s+(?:mi\s+)?[eè]\s+andata\s+la\s+settimana|"
                           r"(?:il\s+)?riepilogo\s+(?:della\s+)?(?:mia\s+)?settimana(?:le)?|(?:il\s+)?resoconto\s+(?:della\s+)?settimana(?:le)?|(?:la\s+)?mia\s+settimana|"
                           r"bilancio\s+(?:della\s+)?settimana|riepilogo\s+settimanale)$", re.I)


def riepilogo_settimana(memoria, oggi=None):
    oggi = oggi or datetime.date.today()
    da = oggi - datetime.timedelta(days=6)
    sp = SPESE.riepilogo(da, oggi)
    ab = ABITUDINI.tutte_stato()
    abit = []
    for a in ab:
        if a.get("settimanale"):
            fatti, prev = a["questa_settimana"], a["settimanale"]
        else:
            prev = sum(1 for g in a["settimana"] if g["previsto"])
            fatti = sum(1 for g in a["settimana"] if g["previsto"] and g["fatto"] >= a["obiettivo"])
        abit.append({"emoji": a["emoji"], "nome": a["nome"], "fatti": fatti, "previsti": prev, "serie": a["serie"]})
    inizio = datetime.datetime.combine(da, datetime.time())
    passati = [o for o in CAL.occorrenze(inizio, datetime.datetime.combine(oggi + datetime.timedelta(days=1), datetime.time())) if o["inizio"] <= datetime.datetime.now()]
    prossimi = [{"quando": o["inizio"].strftime("%d/%m") + ("" if o["tutto_giorno"] else " " + o["inizio"].strftime("%H:%M")), "titolo": o["titolo"]}
                for o in CAL.occorrenze(datetime.datetime.now(), datetime.datetime.combine(oggi + datetime.timedelta(days=8), datetime.time()))][:5]
    with memoria._lock:
        docs = [x for x in memoria.documenti if x.get("aggiunto", "")[:10] >= da.isoformat()]
        chiacchiere = sum(1 for x in memoria.diario if x.get("quando", "")[:10] >= da.isoformat() and x.get("tu"))
        umori = [valenza_umore(u.get("umore", ""), u.get("intensita", 5)) for u in memoria.umore if u.get("data", "") >= da.isoformat()]
    riunioni = [x for x in docs if x.get("nome", "").startswith("Riunione ")]
    out = {"da": da.isoformat(), "a": oggi.isoformat(), "spese": {"totale": sp["totale"], "prima": sp["prima"], "n": sp["n"], "top": sp["per_categoria"][:3]},
           "abitudini": abit, "eventi": {"passati": len(passati), "prossimi": prossimi}, "riunioni": len(riunioni),
           "documenti": len(docs) - len(riunioni), "chiacchierate": chiacchiere, "umore": round(sum(umori) / len(umori), 1) if umori else None}
    r = [f"📊 **La tua settimana** ({da.day} {MESI_IT[da.month - 1][:3]} – {oggi.day} {MESI_IT[oggi.month - 1][:3]})"]
    if sp["n"]:
        dlt = f" ({'+' if sp['totale'] >= sp['prima'] else ''}{round(100 * (sp['totale'] - sp['prima']) / sp['prima'])}% rispetto alla settimana prima)" if sp["prima"] else ""
        r.append(f"💶 Spese: **{euro(sp['totale'])}**{dlt}" + (" · " + ", ".join(f"{c['emoji']} {c['nome'].lower()} {euro(c['totale'])}" for c in sp["per_categoria"][:3]) if sp["per_categoria"] else ""))
    else:
        r.append("💶 Spese: niente segnato (dimmi «ho speso …» quando paghi qualcosa).")
    if abit:
        tot_f, tot_p = sum(x["fatti"] for x in abit), sum(x["previsti"] for x in abit) or 1
        r.append(f"✅ Abitudini: **{round(100 * tot_f / tot_p)}%** fatte · " + ", ".join(f"{x['emoji']} {x['fatti']}/{x['previsti']}" + (f" 🔥{x['serie']}" if x["serie"] >= 3 else "") for x in abit[:6]))
    r.append(f"📅 Impegni fatti: {len(passati)}" + (" · in arrivo: " + ", ".join(f"{p['titolo']} ({p['quando']})" for p in prossimi[:3]) if prossimi else ""))
    extra = []
    if riunioni:
        extra.append(f"📝 {len(riunioni)} riunion{'e' if len(riunioni) == 1 else 'i'}")
    if out["documenti"]:
        extra.append(f"📚 {out['documenti']} document{'o' if out['documenti'] == 1 else 'i'} nuov{'o' if out['documenti'] == 1 else 'i'}")
    fatte_sett = sum(1 for a in ATTIVITA.tutte() if (a.get("fatta") or "")[:10] >= da.isoformat())          # v17
    foc = ATTIVITA.statistiche(da, oggi)
    out.update(attivita_fatte=fatte_sett, pomodori=foc["pomodori"], minuti_focus=foc["minuti"])
    if fatte_sett:
        extra.append(f"✅ {fatte_sett} {'cosa fatta' if fatte_sett == 1 else 'cose fatte'}")
    if foc["pomodori"]:
        extra.append(f"🍅 {foc['pomodori']} pomodor{'o' if foc['pomodori'] == 1 else 'i'}")
    if chiacchiere:
        extra.append(f"💬 {chiacchiere} messaggi tra noi")
    if extra:
        r.append(" · ".join(extra))
    if out["umore"] is not None:
        r.append(f"💙 Umore medio: {out['umore']}/10" + (" — settimana serena! 😊" if out["umore"] >= 6.5 else " — tieni duro, ci sono io." if out["umore"] < 4.5 else ""))
    bravo = []
    if sp["prima"] and sp["totale"] < sp["prima"]:
        bravo.append("hai speso meno della settimana prima")
    if abit and sum(x["fatti"] for x in abit) / (sum(x["previsti"] for x in abit) or 1) >= 0.8:
        bravo.append("con le abitudini sei stato costante")
    r.append(("🌟 Bravo: " + " e ".join(bravo) + "!") if bravo else "🌱 La prossima settimana proviamo a fare ancora meglio, un passo alla volta.")
    return {"testo": "\n".join(r), "settimana": out}


# ════════════════════════════════════════════════════════════
# V17 — MAIK TI AIUTA A FARE LE COSE: cose da fare con priorità e scadenze, pomodori, il piano della giornata, la chiusura
# ════════════════════════════════════════════════════════════
_PRIO_ALTA = re.compile(r"(?:\b(?:urgente|urgentissim[oa]|importante|importantissim[oa]|priorit[aà]\s+alta|alta\s+priorit[aà]|subito)\b|!!+)", re.I)
_PRIO_BASSA = re.compile(r"\b(?:quando\s+(?:hai|ho)\s+tempo|priorit[aà]\s+bassa|bassa\s+priorit[aà]|non\s+(?:è\s+)?urgente|con\s+calma|prima\s+o\s+poi)\b", re.I)
_RE_DATA_ESPLICITA = re.compile(r"\b(?:(?:entro|per|prima\s+di|scade)\s+(?:il\s+|l['’]\s*)?|il\s+)(\d{1,2})(?:\s*[/.\-]\s*(\d{1,2})(?:\s*[/.\-]\s*(\d{2,4}))?|\s+(" + "|".join(MESI_IT) + r")(?:\s+(\d{4}))?)\b", re.I)
_RE_DATA_PAROLA = re.compile(r"\b(?:(?:entro|per|prima\s+di)\s+(?:(?:il|la|lo)\s+)?)?(oggi|stasera|domani(?:\s+(?:mattina|sera|pomeriggio))?|dopodomani|"
                             r"(?:(?:questo|questa|prossimo|prossima)\s+)?(?:luned[iì]|marted[iì]|mercoled[iì]|gioved[iì]|venerd[iì]|sabato|domenica)(?:\s+prossim[oa])?|"
                             r"fine\s+settimana|(?:la\s+)?(?:prossima\s+settimana|settimana\s+prossima)|fine\s+mese)\b(?:\s+(?:alle|verso\s+le|entro\s+le)\s+\d{1,2}(?:[:.]\d{2})?)?", re.I)
_ICONA_PRIO = {"alta": "🔴", "normale": "🟡", "bassa": "⚪"}


def interpreta_attivita(testo, oggi=None):
    """«chiamare il commercialista entro venerdì, urgente #lavoro (30 min)» → {testo, priorita, scadenza, ora, progetto, durata}."""
    oggi = oggi or datetime.date.today()
    t = re.sub(r"\s+", " ", str(testo or "")).strip()
    priorita = "alta" if _PRIO_ALTA.search(t) else "bassa" if _PRIO_BASSA.search(t) else "normale"
    t = _PRIO_BASSA.sub(" ", _PRIO_ALTA.sub(" ", t))
    progetto = ""
    m = re.search(r"#([\wàèéìòù]{2,24})", t)
    if m:
        progetto, t = m.group(1).lower(), t[:m.start()] + t[m.end():]
    durata = 0
    m = re.search(r"\(\s*(?:circa\s+)?(\d{1,3})\s*(min(?:uti)?|m|h|or[ae])\s*\)", t, re.I)
    if m:
        durata = int(m.group(1)) * (60 if m.group(2).lower()[0] in "ho" else 1)
        t = t[:m.start()] + t[m.end():]
    scadenza, ora = None, ""
    m = _RE_DATA_ESPLICITA.search(t)
    if m:
        try:
            g = int(m.group(1))
            if m.group(4):
                mese, anno = MESI_IT.index(m.group(4).lower()) + 1, int(m.group(5) or oggi.year)
            else:
                mese = int(m.group(2) or oggi.month)
                anno = int(m.group(3)) + (2000 if m.group(3) and len(m.group(3)) == 2 else 0) if m.group(3) else oggi.year
            scadenza = datetime.date(anno, mese, g)
            if scadenza < oggi and not (m.group(3) or m.group(5)):
                scadenza = scadenza.replace(year=scadenza.year + 1)                          # «il 3 gennaio» a dicembre = l'anno dopo
            t = t[:m.start()] + t[m.end():]
        except (ValueError, IndexError):
            scadenza = None
    if not scadenza:
        m = _RE_DATA_PAROLA.search(t)
        if m:
            frase = m.group(0)
            w = _senza_accenti(m.group(1).lower())
            if "fine settimana" in w:
                scadenza = oggi + datetime.timedelta(days=6 - oggi.weekday())                # domenica
            elif "settimana" in w:
                scadenza = oggi + datetime.timedelta(days=7 - oggi.weekday() + 4)        # venerdì della settimana dopo
            elif w == "oggi":
                scadenza = oggi
            elif "fine mese" in w:
                scadenza = (oggi.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - datetime.timedelta(days=1)
            else:
                q, _ = parse_quando(frase, datetime.datetime.combine(oggi, datetime.time(datetime.datetime.now().hour, datetime.datetime.now().minute)))
                if q:
                    scadenza = q.date()
                    if re.search(r"\b(?:alle|verso\s+le|entro\s+le)\s+\d", frase) or w == "stasera":
                        ora = q.strftime("%H:%M")
            if scadenza:
                t = t[:m.start()] + t[m.end():]
    t = re.sub(r"\s+", " ", t).strip(" ,.;:-")
    t = re.sub(r"(?i)\s+(?:entro|per|prima\s+di|e|,)$", "", t).strip(" ,.;:-")
    t = re.sub(r"(?i)^(?:di|che\s+devo|devo)\s+", "", t).strip()
    return {"testo": (t[:1].upper() + t[1:])[:140], "priorita": priorita, "scadenza": scadenza.isoformat() if scadenza else "", "ora": ora, "progetto": progetto, "durata": durata}


def quando_scade(s, oggi=None):
    if not s:
        return ""
    oggi = oggi or datetime.date.today()
    d = datetime.date.fromisoformat(s[:10])
    gg = (d - oggi).days
    if gg < 0:
        return "in ritardo di " + (f"{-gg} giorni" if gg < -1 else "un giorno")
    if gg == 0:
        return "oggi"
    if gg == 1:
        return "domani"
    if gg < 7:
        return GIORNI_LUNGHI[d.weekday()]
    return f"{d.day} {MESI_IT[d.month - 1][:3]}"


_RE_ATT_AGGIUNGI = [
    re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:aggiungi|metti|scrivi|segna|inserisci)(?:mi)?\s+(?:(?:alle|tra\s+le|nelle|nella\s+lista\s+delle)\s+(?:mie\s+)?cose\s+da\s+fare|(?:alla|nella)\s+(?:mia\s+)?(?:to-?do(?:\s+list)?|lista\s+(?:delle\s+)?(?:attivit[aà]|cose\s+da\s+fare)))\s*[:,]?\s*(?P<t>.+)$", re.I),
    re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:aggiungi|metti|segna)\s+(?P<t>.+?)\s+(?:alle|tra\s+le|nelle)\s+(?:mie\s+)?cose\s+da\s+fare$", re.I),
    re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:nuova\s+attivit[aà]|nuovo\s+compito|nuova\s+cosa\s+da\s+fare|cosa\s+da\s+fare|to-?do)\s*[:,]\s*(?P<t>.+)$", re.I),
    re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:ricordati\s+che\s+)?devo\s+(?P<t>.+?\bentro\b.+)$", re.I),
]
_RE_ATT_ELENCO = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:cosa\s+(?:devo|ho\s+da|mi\s+resta\s+da)\s+fare|che\s+cosa\s+devo\s+fare|(?:le\s+)?(?:mie\s+)?cose\s+da\s+fare|(?:la\s+)?(?:mia\s+)?to-?do(?:\s+list)?|"
                            r"(?:le\s+)?(?:mie\s+)?attivit[aà]|(?:i\s+)?(?:miei\s+)?compiti|cosa\s+c['’]?[eè]\s+da\s+fare)(?P<q>\s+(?:oggi|domani|questa\s+settimana|in\s+settimana|per\s+oggi|per\s+domani|in\s+ritardo))?$", re.I)
_RE_ATT_FATTO = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:ho\s+)?(?:fatto|finito|completato|terminato|chiuso)|fatt[oa]|segna(?:mi)?\s+(?:come\s+)?(?:fatt[oa]|completat[oa])|spunta)\s*[:!,]?\s+(?P<t>.+)$", re.I)
_RE_ATT_TOGLI = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:cancella|elimina|togli|rimuovi)\s+(?:dalle\s+(?:mie\s+)?cose\s+da\s+fare|l['’]\s*attivit[aà]|(?:il\s+)?compito)\s+(?P<t>.+)$", re.I)
_RE_ATT_RIMANDA = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:sposta|rimanda|posticipa)\s+(?P<t>.+?)\s+(?:a|al|alla|per|di)\s+(?P<q>domani|dopodomani|luned[iì]|marted[iì]|mercoled[iì]|gioved[iì]|venerd[iì]|sabato|domenica|(?:la\s+)?prossima\s+settimana)$", re.I)
_RE_PIANO = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:pianifica|organizza|programma)(?:mi)?\s+(?:la\s+)?(?:mia\s+)?giornata(?:\s+di\s+(?:oggi|domani))?|(?:il\s+)?piano\s+(?:della\s+|di\s+)?(?:giornata|oggi)|"
                       r"come\s+(?:mi\s+)?organizzo\s+(?:la\s+giornata|oggi)|aiutami\s+a\s+organizzare\s+(?:la\s+)?giornata)$", re.I)
_RE_GIORNATA = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:com['’]?\s*[eè]\s+andata\s+(?:la\s+giornata|oggi)|come\s+[eè]\s+andata\s+oggi|chiud(?:i|iamo)\s+la\s+giornata|fine\s+(?:della\s+)?giornata|"
                          r"bilancio\s+(?:della\s+)?giornata|(?:il\s+)?riepilogo\s+(?:di\s+oggi|della\s+giornata))$", re.I)
_RE_POMODORI = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:quanti\s+pomodori\s+(?:ho\s+fatto|abbiamo\s+fatto)|quanto\s+(?:mi\s+sono|sono\s+stato|sono\s+stata)\s+concentrat[oa]|(?:le\s+)?(?:mie\s+)?statistiche\s+(?:della\s+)?concentrazione|(?:i\s+)?(?:miei\s+)?pomodori)(?P<q>\s+(?:oggi|ieri|questa\s+settimana|in\s+settimana))?$", re.I)


class Attivita:
    def __init__(self):
        self._lock = threading.Lock()

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "attivita.json")

    def _carica(self):
        try:
            with open(self._file(), encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                d.setdefault("attivita", [])
                d.setdefault("sessioni", [])
                return d
        except Exception:
            pass
        return {"attivita": [], "sessioni": []}

    def _salva(self, d):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(tmp, self._file())

    def tutte(self):
        return self._carica()["attivita"]

    def aperte(self):
        return [a for a in self.tutte() if not a.get("fatta")]

    @staticmethod
    def _ordine(a, oggi=None):
        """In ritardo e in scadenza prima, poi le urgenti, poi le altre (le più vecchie prima)."""
        oggi = (oggi or datetime.date.today()).isoformat()
        s = a.get("scadenza") or "9999-99-99"
        return (0 if s < oggi else 1 if s == oggi else 2, {"alta": 0, "normale": 1, "bassa": 2}[a.get("priorita", "normale")], s, a.get("ora") or "99", a.get("creata", ""))

    def aggiungi(self, testo, priorita="normale", scadenza="", ora="", progetto="", durata=0, fonte="chat"):
        testo = re.sub(r"\s+", " ", str(testo or "")).strip()[:140]
        if len(testo) < 2:
            return None, "manca cosa devi fare"
        a = {"id": uuid.uuid4().hex[:8], "testo": testo, "priorita": priorita if priorita in _ICONA_PRIO else "normale", "scadenza": str(scadenza or "")[:10],
             "ora": str(ora or "")[:5], "progetto": str(progetto or "")[:24], "durata": int(durata or 0), "creata": datetime.datetime.now().isoformat(timespec="seconds"),
             "fatta": None, "pomodori": 0, "fonte": fonte}
        with self._lock:
            d = self._carica()
            d["attivita"].append(a)
            d["attivita"] = d["attivita"][-3000:]
            self._salva(d)
        return a, None

    def aggiungi_testo(self, testo, fonte="chat", quando=""):
        x = interpreta_attivita(testo + (" " + quando if quando else ""))
        return self.aggiungi(fonte=fonte, **x)

    def modifica(self, aid, **campi):
        with self._lock:
            d = self._carica()
            a = next((x for x in d["attivita"] if x["id"] == aid), None)
            if not a:
                return None
            for k, v in campi.items():
                if k in ("testo", "priorita", "scadenza", "ora", "progetto", "durata", "pomodori", "fissata"):
                    a[k] = v
                elif k == "fatta":
                    a["fatta"] = datetime.datetime.now().isoformat(timespec="seconds") if v else None
            self._salva(d)
            return dict(a)

    def elimina(self, aid):
        with self._lock:
            d = self._carica()
            prima = len(d["attivita"])
            d["attivita"] = [a for a in d["attivita"] if a["id"] != aid]
            self._salva(d)
            return len(d["attivita"]) < prima

    def trova(self, testo, aperte=True):
        """L'attività di cui parla la frase (parole in comune; a pari merito quella che scade prima)."""
        tok = {w for w in _token(testo) if not w.isdigit()}
        if not tok:
            return None
        meglio, punti = None, 0
        for a in sorted(self.aperte() if aperte else self.tutte(), key=self._ordine):
            p = len(tok & _token(a["testo"]))
            if p > punti:
                meglio, punti = a, p
        return meglio

    def vista(self, filtro="tutte", oggi=None):
        oggi = oggi or datetime.date.today()
        o = oggi.isoformat()
        if filtro == "fatte":
            return sorted([a for a in self.tutte() if a.get("fatta")], key=lambda a: a["fatta"], reverse=True)[:100]
        L = sorted(self.aperte(), key=lambda a: self._ordine(a, oggi))
        if filtro == "oggi":            # scadute, in scadenza oggi, e le urgenti (senza data o che scadono entro dopodomani)
            entro2 = (oggi + datetime.timedelta(days=2)).isoformat()
            return [a for a in L if (a["scadenza"] and a["scadenza"] <= o) or (a["priorita"] == "alta" and (not a["scadenza"] or a["scadenza"] <= entro2))]
        if filtro == "domani":
            return [a for a in L if a["scadenza"] == (oggi + datetime.timedelta(days=1)).isoformat()]
        if filtro == "settimana":
            return [a for a in L if a["scadenza"] and a["scadenza"] <= (oggi + datetime.timedelta(days=7)).isoformat()]
        if filtro == "ritardo":
            return [a for a in L if a["scadenza"] and a["scadenza"] < o]
        return L

    @staticmethod
    def riga(a, oggi=None):
        q = quando_scade(a.get("scadenza"), oggi)
        extra = ([("⚠️ " if q.startswith("in ritardo") else "") + q + (" alle " + a["ora"] if a.get("ora") else "")] if q else []) + (["#" + a["progetto"]] if a.get("progetto") else []) + (["🍅" * min(a["pomodori"], 6)] if a.get("pomodori") else [])
        return f"{_ICONA_PRIO.get(a['priorita'], '🟡')} {a['testo']}" + (f" ({', '.join(extra)})" if extra else "")

    # ── 🍅 sessioni di concentrazione ──
    def sessione(self, minuti, aid="", testo="", completa=True, inizio=None):
        minuti = max(0, min(240, int(minuti or 0)))
        if minuti < 1:
            return None
        fine = datetime.datetime.now()
        s = {"id": uuid.uuid4().hex[:8], "inizio": (inizio or (fine - datetime.timedelta(minutes=minuti))).isoformat(timespec="seconds"),
             "fine": fine.isoformat(timespec="seconds"), "minuti": minuti, "attivita": aid or "", "testo": str(testo or "")[:140], "completa": bool(completa)}
        with self._lock:
            d = self._carica()
            d["sessioni"].append(s)
            d["sessioni"] = d["sessioni"][-5000:]
            if aid and completa:
                for a in d["attivita"]:
                    if a["id"] == aid:
                        a["pomodori"] = a.get("pomodori", 0) + 1
            self._salva(d)
        return s

    def statistiche(self, da, a):
        ss = [s for s in self._carica()["sessioni"] if da.isoformat() <= s["fine"][:10] <= a.isoformat()]
        per = {}
        for s in ss:
            k = s["testo"] or "senza attività"
            per[k] = per.get(k, 0) + (1 if s["completa"] else 0)
        giorni = {}
        for s in ss:
            giorni[s["fine"][:10]] = giorni.get(s["fine"][:10], 0) + s["minuti"]
        return {"pomodori": sum(1 for s in ss if s["completa"]), "minuti": sum(s["minuti"] for s in ss), "sessioni": len(ss),
                "per_attivita": sorted(([k, v] for k, v in per.items() if v), key=lambda x: -x[1]), "per_giorno": giorni}

    # ── il router ──
    def router(self, testo):
        t = re.sub(r"\s+", " ", (testo or "").strip())
        tl = t.lower().rstrip(" ?!.")
        for rx in _RE_ATT_AGGIUNGI:
            m = rx.match(t.rstrip(" .!"))
            if m:
                pezzi = [p.strip() for p in re.split(r"\s*;\s*|\n+", m.group("t")) if p.strip()]
                fatte = []
                for p in pezzi[:10]:
                    a, err = self.aggiungi_testo(p)
                    if a:
                        fatte.append(a)
                if not fatte:
                    return {"testo": "✅ Cosa devo segnare? Per esempio «aggiungi alle cose da fare: chiamare il commercialista entro venerdì»."}
                if len(fatte) == 1:
                    a = fatte[0]
                    return {"testo": f"✅ Aggiunta alle cose da fare: **{a['testo']}**" + (f" — scade {quando_scade(a['scadenza'])}" if a["scadenza"] else "")
                            + (" · 🔴 urgente" if a["priorita"] == "alta" else "") + (f" · #{a['progetto']}" if a["progetto"] else "") + ".", "attivita": a}
                return {"testo": f"✅ Aggiunte {len(fatte)} cose da fare:\n" + "\n".join("- " + self.riga(a) for a in fatte), "attivita_lista": {"titolo": "Aggiunte", "voci": fatte}}
        m = _RE_ATT_TOGLI.match(tl)
        if m:
            a = self.trova(m.group("t"))
            if not a:
                return {"testo": f"✅ Non trovo «{m.group('t')}» tra le cose da fare."}
            self.elimina(a["id"])
            return {"testo": f"🗑️ Tolta dalle cose da fare: {a['testo']}."}
        m = _RE_ATT_RIMANDA.match(tl)
        if m:
            a = self.trova(m.group("t"))
            if a:
                x = interpreta_attivita("x per " + m.group("q"))
                b = self.modifica(a["id"], scadenza=x["scadenza"])
                return {"testo": f"📆 Spostata a {quando_scade(b['scadenza'])}: {b['testo']}.", "attivita": b}
        m = _RE_ATT_ELENCO.match(tl)
        if m:
            return self.elenco_testo((m.group("q") or "").strip())
        if _RE_PIANO.match(tl):
            return pianifica_giornata()
        if _RE_GIORNATA.match(tl):
            return fine_giornata()
        m = _RE_POMODORI.match(tl)
        if m:
            q = _senza_accenti((m.group("q") or "oggi").strip().lower())
            oggi = datetime.date.today()
            da, a, et = (oggi - datetime.timedelta(days=1), oggi - datetime.timedelta(days=1), "Ieri") if q == "ieri" else \
                        (oggi - datetime.timedelta(days=oggi.weekday()), oggi, "Questa settimana") if "settimana" in q else (oggi, oggi, "Oggi")
            st = self.statistiche(da, a)
            if not st["sessioni"]:
                return {"testo": f"🍅 {et} nessun pomodoro. Prova: «concentrazione 25 minuti sulla relazione» (o il tasto Q)."}
            ore = f"{st['minuti'] // 60} or{'a' if st['minuti'] // 60 == 1 else 'e'} e {st['minuti'] % 60} minuti" if st["minuti"] >= 60 else f"{st['minuti']} minuti"
            return {"testo": f"🍅 {et}: **{st['pomodori']} pomodor{'o' if st['pomodori'] == 1 else 'i'}**, {ore} di concentrazione."
                    + ("\n" + "\n".join(f"- {k}: {'🍅' * min(v, 10)}" for k, v in st["per_attivita"][:6]) if st["per_attivita"] else ""), "focus": st}
        return None

    def elenco_testo(self, q=""):
        q = _senza_accenti(q.lower())
        oggi = datetime.date.today()
        if not q:
            L = self.vista("tutte")
            if not L:
                return {"testo": "✅ Non hai cose da fare segnate. Dimmi «aggiungi alle cose da fare: …» 🎉", "attivita_lista": {"titolo": "Cose da fare", "voci": []}}
            return {"testo": f"✅ Le tue cose da fare ({len(L)}):\n" + "\n".join("- " + self.riga(a) for a in L[:15]) + (f"\n…e altre {len(L) - 15}" if len(L) > 15 else ""),
                    "attivita_lista": {"titolo": "Cose da fare", "voci": L[:30]}}
        giorno = oggi + datetime.timedelta(days=1) if "domani" in q else oggi
        if "settimana" in q:
            L, titolo = self.vista("settimana"), "Questa settimana"
        elif "ritardo" in q:
            L, titolo = self.vista("ritardo"), "In ritardo"
        else:
            L, titolo = self.vista("domani" if "domani" in q else "oggi"), "Domani" if "domani" in q else "Oggi"
        righe = [f"📋 **{titolo}**"]
        if "settimana" not in q and "ritardo" not in q:
            ag = CAL.agenda(datetime.datetime.combine(giorno, datetime.time()), 1)
            if ag["n"]:
                righe.append("📅 Impegni: " + " · ".join(f"{e['ora']} {e['titolo']}" for e in ag["giorni"][0]["eventi"][:6]))
            if giorno == oggi:
                ab = [a for a in ABITUDINI.tutte_stato() if a["previsto_oggi"] and not a["fatta_oggi"] and not a.get("settimanale")]
                if ab:
                    righe.append("💪 Abitudini: " + ", ".join(f"{a['emoji']} {a['nome']}" for a in ab[:5]))
        if L:
            righe.append("✅ Da fare:\n" + "\n".join("- " + self.riga(a) for a in L[:12]))
        else:
            righe.append("✅ Niente in scadenza" + (" 🎉" if len(righe) == 1 else "") + ".")
        senza = [a for a in self.vista("tutte") if a not in L][:3] if titolo == "Oggi" else []
        if senza:
            righe.append("💡 Se hai tempo: " + ", ".join(a["testo"] for a in senza))
        return {"testo": "\n".join(righe), "attivita_lista": {"titolo": titolo, "voci": L[:30]}}

    def router_fatto(self, testo):
        m = _RE_ATT_FATTO.match(re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" .!"))
        if not m or not self.aperte():
            return None
        a = self.trova(m.group("t"))
        if not a:
            return None
        b = self.modifica(a["id"], fatta=True)
        resto = len(self.vista("oggi"))
        return {"testo": f"✅ Fatto: **{b['testo']}** 🎉" + (f" Per oggi ne restano {resto}." if resto else " Per oggi non resta niente in scadenza!"), "attivita": b}


ATTIVITA = Attivita()


# ── 🗓️ il piano della giornata (senza modello: impegni fissi, abitudini, cose da fare negli spazi liberi, pause) ──
def _hm(t):
    return t.strftime("%H:%M")


def pianifica_giornata(ora=None, inizio_h=None, fine_h=None):
    ora = ora or datetime.datetime.now()
    inizio_h = inizio_h if inizio_h is not None else CONFIG["giornata"][0]
    fine_h = fine_h if fine_h is not None else CONFIG["giornata"][1]
    giorno = ora.date()
    fine = datetime.datetime.combine(giorno, datetime.time(fine_h))
    domani = False
    if ora >= fine - datetime.timedelta(minutes=45):                 # la giornata è finita: il piano di domani
        giorno, domani = giorno + datetime.timedelta(days=1), True
        fine = datetime.datetime.combine(giorno, datetime.time(fine_h))
        inizio = datetime.datetime.combine(giorno, datetime.time(inizio_h))
    else:
        m = (ora.minute // 15 + 1) * 15
        inizio = max(datetime.datetime.combine(giorno, datetime.time(inizio_h)), ora.replace(minute=0, second=0, microsecond=0) + datetime.timedelta(minutes=m))
    fissi = []
    for o in CAL.occorrenze(datetime.datetime.combine(giorno, datetime.time()), datetime.datetime.combine(giorno + datetime.timedelta(days=1), datetime.time())):
        if not o["tutto_giorno"] and o["fine"] > inizio and o["inizio"] < fine:
            fissi.append({"inizio": max(o["inizio"], inizio), "fine": min(o["fine"], fine), "tipo": "evento", "titolo": o["titolo"] + (f" ({o['luogo']})" if o["luogo"] else ""), "icona": "📅"})
    for a in ABITUDINI.elenco():
        if a.get("ora") and ABITUDINI._previsto(a, giorno) and not (not domani and ABITUDINI.stato(a)["fatta_oggi"]):
            h, mi = map(int, a["ora"].split(":"))
            t0 = datetime.datetime.combine(giorno, datetime.time(h, mi))
            dur = 60 if re.search(r"palestra|allenament|corr|nuot|bici|calcio|tennis", a["nome"], re.I) else 20
            if inizio <= t0 < fine:
                fissi.append({"inizio": t0, "fine": min(fine, t0 + datetime.timedelta(minutes=dur)), "tipo": "abitudine", "titolo": a["nome"], "icona": a["emoji"], "id": a["id"]})
    p0, p1 = datetime.datetime.combine(giorno, datetime.time(13)), datetime.datetime.combine(giorno, datetime.time(14))
    if inizio < p1 and fine > p0 and not any(f["inizio"] < p1 and f["fine"] > p0 for f in fissi):
        fissi.append({"inizio": max(p0, inizio), "fine": p1, "tipo": "pranzo", "titolo": "Pranzo", "icona": "🍝"})
    fissi.sort(key=lambda f: f["inizio"])
    buchi, t = [], inizio
    for f in fissi:
        if f["inizio"] > t:
            buchi.append([t, f["inizio"]])
        t = max(t, f["fine"])
    if t < fine:
        buchi.append([t, fine])
    oggi_iso = giorno.isoformat()
    da_fare = sorted(ATTIVITA.aperte(), key=lambda a: ATTIVITA._ordine(a, giorno))
    blocchi, messe, fuori = [], [], []
    for a in da_fare:
        dur = a.get("durata") or (50 if a["priorita"] != "bassa" else 25)
        posto = False
        for b in buchi:
            if (b[1] - b[0]).total_seconds() / 60 >= dur:
                blocchi.append({"inizio": b[0], "fine": b[0] + datetime.timedelta(minutes=dur), "tipo": "attivita", "titolo": a["testo"], "icona": _ICONA_PRIO[a["priorita"]],
                                "id": a["id"], "scade": quando_scade(a["scadenza"], giorno), "pomodori": max(1, round(dur / 25))})
                b[0] += datetime.timedelta(minutes=dur)
                if (b[1] - b[0]).total_seconds() >= 10 * 60:
                    blocchi.append({"inizio": b[0], "fine": b[0] + datetime.timedelta(minutes=10), "tipo": "pausa", "titolo": "Pausa", "icona": "☕"})
                    b[0] += datetime.timedelta(minutes=10)
                messe.append(a)
                posto = True
                break
        if not posto and (a["scadenza"] and a["scadenza"] <= oggi_iso or a["priorita"] == "alta"):
            fuori.append(a)
    tutti = sorted(fissi + blocchi, key=lambda x: x["inizio"])
    while tutti and tutti[-1]["tipo"] == "pausa":
        tutti.pop()
    titolo = ("Il piano di domani" if domani else "Il tuo piano di oggi") + f" ({_hm(inizio)}–{_hm(fine)})"
    if not tutti:
        return {"testo": f"🗓️ {titolo}: niente in programma, giornata libera! 🎉 Aggiungi qualcosa con «aggiungi alle cose da fare: …».",
                "piano": {"titolo": titolo, "blocchi": [], "fuori": []}}
    righe = [f"🗓️ **{titolo}**"]
    for x in tutti:
        extra = f" ({x['scade']})" if x.get("scade") and x["tipo"] == "attivita" else ""
        righe.append(f"- {_hm(x['inizio'])}–{_hm(x['fine'])} {x['icona']} {x['titolo']}{extra}")
    if fuori:
        righe.append("⚠️ Non ci stanno: " + ", ".join(a["testo"] for a in fuori[:5]) + " — vuoi spostarle a domani?")
    restano = [a for a in da_fare if a not in messe and a not in fuori]
    if restano:
        righe.append(f"💡 Altre {len(restano)} cose senza fretta restano in lista.")
    righe.append("▶ Premi «Inizia» su un'attività e mi concentro con te (🍅 25 minuti + pausa).")
    js = lambda x: dict({k: v for k, v in x.items() if k not in ("inizio", "fine")}, inizio=_hm(x["inizio"]), fine=_hm(x["fine"]))
    return {"testo": "\n".join(righe), "piano": {"titolo": titolo, "domani": domani, "blocchi": [js(x) for x in tutti], "fuori": [{"id": a["id"], "testo": a["testo"]} for a in fuori]}}


# ── 🌙 chiudiamo la giornata ──
def fine_giornata(ora=None):
    ora = ora or datetime.datetime.now()
    oggi = ora.date()
    o = oggi.isoformat()
    fatte = [a for a in ATTIVITA.tutte() if (a.get("fatta") or "")[:10] == o]
    restano = [a for a in ATTIVITA.vista("oggi", oggi) if a.get("scadenza") and a["scadenza"] <= o]
    st = ATTIVITA.statistiche(oggi, oggi)
    ab = ABITUDINI.tutte_stato()
    prev = [a for a in ab if a["previsto_oggi"] and not a.get("settimanale")]
    ab_fatte = [a for a in prev if a["fatta_oggi"]]
    sp = SPESE.riepilogo(oggi, oggi)
    dom = CAL.agenda(datetime.datetime.combine(oggi + datetime.timedelta(days=1), datetime.time()), 1)
    righe = [f"🌙 **La tua giornata** ({data_it(ora)})"]
    righe.append(f"✅ Fatte: {len(fatte)}" + (" — " + ", ".join(a["testo"] for a in fatte[:6]) if fatte else ""))
    if st["sessioni"]:
        righe.append(f"🍅 Concentrazione: {st['pomodori']} pomodor{'o' if st['pomodori'] == 1 else 'i'}, {st['minuti']} minuti")
    if prev:
        righe.append(f"💪 Abitudini: {len(ab_fatte)}/{len(prev)}" + (" · mancano: " + ", ".join(f"{a['emoji']} {a['nome']}" for a in prev if not a["fatta_oggi"])[:200] if len(ab_fatte) < len(prev) else " — tutte! 🔥"))
    if sp["n"]:
        righe.append(f"💶 Spese di oggi: {euro(sp['totale'])}")
    if restano:
        righe.append("⏭️ Da spostare: " + ", ".join(a["testo"] for a in restano[:6]) + " — premi «sposta a domani».")
    if dom["n"]:
        righe.append("📅 Domani: " + " · ".join(f"{e['ora']} {e['titolo']}" for e in dom["giorni"][0]["eventi"][:4]))
    voto = len(fatte) + st["pomodori"] + len(ab_fatte)
    righe.append("🌟 Giornata produttiva, complimenti! Ora riposati. 😴" if voto >= 5 else "🌱 Ogni giorno un passo: domani si riparte. Buona serata! 💙")
    return {"testo": "\n".join(righe), "giornata": {"fatte": [{"id": a["id"], "testo": a["testo"]} for a in fatte], "restano": [{"id": a["id"], "testo": a["testo"]} for a in restano],
                                                   "pomodori": st["pomodori"], "minuti": st["minuti"], "abitudini": [len(ab_fatte), len(prev)], "spese": sp["totale"]}}


# ════════════════════════════════════════════════════════════
# v18 — MAIK PENSA AVANTI: ricorda le chiacchierate, ti propone idee, legge le foto
# ════════════════════════════════════════════════════════════

# ── 🧠 RICORDI: le chiacchierate passate, ritrovate per significato (embedding) o per parole (BM25) ──
_RE_RIC_CUE = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:"
                         r"(?:ti\s+|te\s+(?:lo|ne)\s+)?ricordi\b|ricordi\s+quando\b|"
                         r"(?:(?:che\s+)?cosa|quando|cosa\s+mai)\s+(?:ti\s+|t['’]\s*)(?:avevo|ho)\s+(?:mai\s+|già\s+|gia\s+)?(?:detto|parlato|raccontato|scritto|accennato|chiesto|spiegato)\b|"
                         r"(?:(?:che\s+)?cosa|quando)\s+(?:avevamo|abbiamo)\s+(?:deciso|detto|stabilito|concluso)\s+(?:su|sul|sulla|sullo|sui|sugli|sulle|di|del|della|dello|dei|degli|delle|per|riguardo|a\s+proposito)\b|"
                         r"ti\s+(?:avevo|ho)\s+(?:mai|già|gia)\s+(?:parlato|detto|raccontato)\b|"
                         r"(?:ne\s+)?(?:avevamo|abbiamo)\s+(?:già|gia)\s+parlato\b)", re.I)
_RE_RIC_TOGLI = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:ti\s+|te\s+(?:lo|ne)\s+)?ricordi\s*(?:che\s+cosa|cosa|quello\s+che|quel\s+che|quando|di\s+quando|se|che)?\s*)?"
                           r"(?:(?:che\s+)?cosa\s+|quando\s+|cosa\s+mai\s+)?(?:ti\s+|t['’]\s*)?(?:ne\s+)?(?:avevo|ho|avevamo|abbiamo)?\s*(?:mai\s+|già\s+|gia\s+)?"
                           r"(?:detto|parlato|raccontato|scritto|accennato|chiesto|spiegato|deciso|stabilito|concluso)?\s*", re.I)
_RE_RIC_PREP = re.compile(r"^(?:(?:su|sul|sulla|sullo|sui|sugli|sulle|di|del|della|dello|dei|degli|delle|riguardo\s+(?:a|al|alla|allo|ai|agli|alle)|"
                          r"a\s+proposito\s+(?:di|del|della|dello|dei|degli|delle)|per|che|quello\s+che|a|al|alla|ai|alle|con)\s+|"
                          r"(?:sull|dell|d|all|riguardo\s+all|a\s+proposito\s+dell)['’]\s*)", re.I)
_RE_RIC_GIORNO = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:(?:di\s+)?(?:che\s+)?(?:cosa|cos['’]|che)\s*(?:abbiamo|avevamo)\s+(?:parlato|chiacchierato|discusso)|"
                            r"(?:(?:che\s+)?cosa|cos['’])\s*ci\s+siamo\s+detti|riassumi(?:mi)?\s+(?:le\s+)?(?:nostre\s+)?(?:chiacchierate|conversazioni|chat)|"
                            r"(?:le\s+)?(?:nostre\s+)?(?:chiacchierate|conversazioni)\s+(?:di|del|della))\s*(?P<q>.*)$", re.I)
_RE_RIC_TEMPO = [(re.compile(r"\b(?:l['’]\s*altro\s*ieri|ieri\s+l['’]\s*altro)\b", re.I), "altroieri"),
                 (re.compile(r"\bieri\b", re.I), "ieri"),
                 (re.compile(r"\b(?:oggi|stamattina|stamani|stasera|stanotte|stamane)\b", re.I), "oggi"),
                 (re.compile(r"\b(?:la\s+)?settimana\s+(?:scorsa|passata)\b", re.I), "sett_scorsa"),
                 (re.compile(r"\bquesta\s+settimana\b", re.I), "settimana"),
                 (re.compile(r"\b(?:il\s+)?mese\s+(?:scorso|passato)\b", re.I), "mese_scorso"),
                 (re.compile(r"\bquesto\s+mese\b", re.I), "mese"),
                 (re.compile(r"\bnegli\s+ultimi\s+(\d{1,2})\s+giorni\b", re.I), "ultimi")]


def periodo_ricordi(q, oggi=None):
    """«ieri», «lunedì», «la settimana scorsa», «il 3 ottobre» → (da, a, etichetta, resto della frase) oppure None."""
    oggi = oggi or datetime.date.today()
    for rx, k in _RE_RIC_TEMPO:
        m = rx.search(q or "")
        if not m:
            continue
        resto = (q[:m.start()] + " " + q[m.end():]).strip()
        if k == "altroieri":
            g = oggi - datetime.timedelta(days=2)
            return g, g, "L'altro ieri", resto
        if k == "ieri":
            g = oggi - datetime.timedelta(days=1)
            return g, g, "Ieri", resto
        if k == "oggi":
            return oggi, oggi, "Oggi", resto
        if k == "sett_scorsa":
            lun = oggi - datetime.timedelta(days=oggi.weekday() + 7)
            return lun, lun + datetime.timedelta(days=6), "La settimana scorsa", resto
        if k == "settimana":
            return oggi - datetime.timedelta(days=oggi.weekday()), oggi, "Questa settimana", resto
        if k == "mese_scorso":
            fine = oggi.replace(day=1) - datetime.timedelta(days=1)
            return fine.replace(day=1), fine, f"A {MESI_IT[fine.month - 1]}", resto
        if k == "mese":
            return oggi.replace(day=1), oggi, "Questo mese", resto
        n = max(1, min(60, int(m.group(1))))
        return oggi - datetime.timedelta(days=n - 1), oggi, f"Negli ultimi {n} giorni", resto
    m = re.search(r"\b(luned[iì]|marted[iì]|mercoled[iì]|gioved[iì]|venerd[iì]|sabato|domenica)(?:\s+scors[oa])?\b", q or "", re.I)
    if m:
        w = next(i for i, g in enumerate(GIORNI_LUNGHI) if _senza_accenti(g) == _senza_accenti(m.group(1).lower()))
        g = oggi - datetime.timedelta(days=(oggi.weekday() - w) % 7 or 7)
        return g, g, GIORNI_LUNGHI[w].capitalize(), (q[:m.start()] + " " + q[m.end():]).strip()
    m = re.search(r"\b(?:il\s+|l['’]\s*)?(\d{1,2})\s+(" + "|".join(MESI_IT) + r")(?:\s+(\d{4}))?\b", q or "", re.I)
    if m:
        try:
            g = datetime.date(int(m.group(3) or oggi.year), MESI_IT.index(m.group(2).lower()) + 1, int(m.group(1)))
            if g > oggi and not m.group(3):
                g = g.replace(year=g.year - 1)
            return g, g, f"Il {g.day} {MESI_IT[g.month - 1]}", (q[:m.start()] + " " + q[m.end():]).strip()
        except ValueError:
            pass
    return None


class Ricordi:
    """v18: ritrova le chiacchierate passate. Con il modello degli embedding (lo stesso dei documenti) le trova
    per significato («la mia macchina» trova «l'auto»), sempre anche per parole. I vettori in ricordi_vettori.json."""

    def __init__(self):
        self._lock = threading.Lock()
        self._dati = None
        self._tok = {}
        self._evento = threading.Event()
        self._thread = None
        self.lavoro = False

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "ricordi_vettori.json")

    def _carica(self):
        if self._dati is None:
            try:
                with open(self._file(), encoding="utf-8") as f:
                    d = json.load(f)
                self._dati = d if isinstance(d, dict) and d.get("modello") == CONFIG["modello_embed"] else {"modello": CONFIG["modello_embed"], "v": {}}
            except Exception:
                self._dati = {"modello": CONFIG["modello_embed"], "v": {}}
        return self._dati

    def _salva(self):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(self._dati, f, separators=(",", ":"))
        os.replace(tmp, self._file())

    @staticmethod
    def testo(x):
        tu = re.sub(r"\s+", " ", re.sub(r"\[📎[^\]]*\]", "", x.get("tu") or "")).strip()
        ai = re.sub(r"\s+", " ", x.get("ai") or "").strip()
        return ((f"Persona: {tu[:600]}\n" if tu else "") + f"MAIK: {ai[:300]}").strip()

    @staticmethod
    def chiave(x):
        return Vettori.chiave((x.get("quando") or "") + "|" + (x.get("tu") or "")[:300] + "|" + (x.get("ai") or "")[:80])

    def _parole_di(self, x):
        k = self.chiave(x)
        t = self._tok.get(k)
        if t is None:
            t = self._tok[k] = collections.Counter(_parole(self.testo(x)))
            if len(self._tok) > 4000:
                try:
                    self._tok.pop(next(iter(self._tok)))
                except (RuntimeError, StopIteration, KeyError):      # un'altra richiesta lo sta toccando: pazienza
                    pass
        return t

    # in sottofondo: i vettori delle chiacchierate nuove (16 alla volta)
    def indicizza(self, memoria, massimo=256):
        if not CONFIG["embed"] or not VETTORI.pronta():
            return 0
        with memoria._lock:
            diario = [x for x in memoria.diario if (x.get("tu") or "").strip()]
        with self._lock:
            d = self._carica()
            manca = [x for x in diario if self.chiave(x) not in d["v"]][-massimo:]
        n = 0
        for i in range(0, len(manca), 16):
            parte = manca[i:i + 16]
            try:
                vv = VETTORI._chiedi(Vettori._prefisso([self.testo(x) for x in parte], "d"))
            except Exception as e:
                VETTORI.errore = str(e)[:120]
                break
            with self._lock:
                for x, v in zip(parte, vv):
                    d["v"][self.chiave(x)] = v
                n += len(parte)
        if n:
            with self._lock:
                vivi = {self.chiave(x) for x in diario}
                if len(d["v"]) > len(vivi) * 1.3 + 50:            # le chiacchierate cancellate
                    d["v"] = {k: v for k, v in d["v"].items() if k in vivi}
                self._salva()
        return n

    def _lavoratore(self, memoria):
        while True:
            self._evento.wait()
            self._evento.clear()
            try:
                self.lavoro = True
                self.indicizza(memoria)
            except Exception as e:
                print(f"  ⚠  ricordi: {e}")
            finally:
                self.lavoro = False

    def programma(self, memoria):
        if not CONFIG["embed"]:
            return
        if self._thread is None:
            self._thread = threading.Thread(target=self._lavoratore, args=(memoria,), daemon=True)
            self._thread.start()
        self._evento.set()

    def info(self, memoria):
        with memoria._lock:
            diario = [x for x in memoria.diario if (x.get("tu") or "").strip()]
        v = self._carica()["v"]
        return {"chiacchierate": len(diario), "pronte": sum(1 for x in diario if self.chiave(x) in v), "lavoro": self.lavoro,
                "per_significato": bool(CONFIG["embed"] and VETTORI.attiva)}

    def cerca(self, memoria, query, k=4, escludi=(), da=None, a=None, rigida=True, soglia=None):
        """→ [{quando, sessione, titolo, tu, ai, simile?, punteggio, per_significato?}] le chiacchierate più vicine alla domanda."""
        q = set(_parole(query))
        with memoria._lock:
            diario = list(memoria.diario)
            titoli = {s["id"]: s.get("titolo", "") for s in memoria.sessioni}
        el = []
        for x in diario:
            if not (x.get("tu") or "").strip():
                continue
            g = (x.get("quando") or "")[:10]
            if (da and g < da.isoformat()) or (a and g > a.isoformat()):
                continue
            if self.chiave(x) in escludi:
                continue
            el.append(x)
        if not el or not (q or (query or "").strip()):
            return []
        qv = VETTORI.vettore_domanda(query) if CONFIG["embed"] and VETTORI.pronta() else None
        vett = self._carica()["v"] if qv is not None else {}
        docs = [self._parole_di(x) for x in el]
        N = len(docs)
        media = sum(sum(d.values()) for d in docs) / N or 1
        df = collections.Counter(w for d in docs for w in set(d) if w in q)
        k1, b = 1.4, 0.75
        punti = []
        for i, (x, tf) in enumerate(zip(el, docs)):
            s, comuni, lung = 0.0, 0, sum(tf.values())
            for w in q:
                f = tf.get(w)
                if f:
                    comuni += 1
                    n = df[w]
                    s += math.log(1 + (N - n + 0.5) / (n + 0.5)) * f * (k1 + 1) / (f + k1 * (1 - b + b * lung / media))
            ok_parole = s > 0 and (not rigida or (comuni >= min(2, len(q)) and comuni / max(1, len(q)) >= 0.34))
            v = vett.get(self.chiave(x)) if qv is not None else None
            sim = sum(map(operator.mul, qv, v)) if v is not None and len(v) == len(qv) else None
            punti.append((s, ok_parole, sim, i, x))
        best = max((p[2] for p in punti if p[2] is not None), default=None)
        max_s = max((p[0] for p in punti), default=0) or 1
        soglia = CONFIG["ricordi_soglia"] if soglia is None else soglia
        scelti = []
        for s, ok_parole, sim, i, x in punti:
            ok_senso = sim is not None and sim >= soglia and sim >= best - 0.1
            if ok_parole or ok_senso:
                voto = 0.45 * s / max_s + (0.55 * max(0.0, (sim - 0.3) / 0.7) if sim is not None else 0.0) + 0.02 * i / N   # a pari merito la più recente
                scelti.append((voto, sim, ok_senso and not ok_parole, s, x))
        scelti.sort(key=lambda t: -t[0])
        out = []
        for voto, sim, solo_senso, s, x in scelti[:k]:
            sid = x.get("sessione") or Memoria.PRINCIPALE
            out.append(dict({"quando": x.get("quando", ""), "sessione": sid, "titolo": titoli.get(sid, ""), "tu": (x.get("tu") or "")[:400],
                             "ai": (x.get("ai") or "")[:400], "punteggio": round(s, 2)},
                            **({"simile": round(sim, 3)} if sim is not None else {}), **({"per_significato": True} if solo_senso else {})))
        return sorted(out, key=lambda r: r["quando"])

    @staticmethod
    def _data(r):
        try:
            g = datetime.date.fromisoformat(r["quando"][:10])
        except ValueError:
            return r["quando"][:10]
        oggi = datetime.date.today()
        if g == oggi:
            return "oggi"
        if g == oggi - datetime.timedelta(days=1):
            return "ieri"
        return f"{g.day} {MESI_IT[g.month - 1]}" + ("" if g.year == oggi.year else f" {g.year}")

    def contesto(self, memoria, testo, sessione=None):
        """Per il system prompt: le chiacchierate passate che c'entrano con la domanda (non quelle già nella chat)."""
        if len(_parole(testo)) < 2 or not memoria.diario:
            return "", []
        esclusi = {self.chiave(x) for x in memoria.ultimi_scambi(6, sessione or Memoria.PRINCIPALE)} | {self.chiave(x) for x in memoria.diario[-2:]}
        trovati = self.cerca(memoria, testo, k=3, escludi=esclusi, rigida=True, soglia=max(CONFIG["ricordi_soglia"], 0.66))
        if not trovati:
            return "", []
        righe = "\n".join(f"- {self._data(r)}: la persona ha scritto «{_testo_breve(r['tu'], 220)}» — tu hai risposto «{_testo_breve(r['ai'], 160)}»" for r in trovati)
        return ("\n\n--- DALLE VOSTRE CHIACCHIERATE PASSATE (ricordi pertinenti: usali solo se c'entrano, con naturalezza, "
                f"es. «come mi avevi detto {self._data(trovati[-1])}…») ---\n{righe}\n--- FINE RICORDI ---",
                [{"quando": r["quando"], "tu": _testo_breve(r["tu"], 90), "sessione": r["sessione"], "titolo": r["titolo"]} for r in trovati])

    def domanda(self, testo):
        """«ti ricordi cosa ti avevo detto su mio fratello?» → {tema, periodo?} (oppure None se non è una domanda sui ricordi)."""
        t = re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" ?!.")
        if not _RE_RIC_CUE.match(t) or re.match(r"^(?:(?:maik|zep)[,!]?\s+)?ricordami\b", t, re.I):
            return None
        resto = _RE_RIC_TOGLI.sub("", t, count=1).strip()
        per = periodo_ricordi(resto)
        if per:
            resto = per[3]
        for _ in range(3):
            resto = _RE_RIC_PREP.sub("", resto, count=1).strip()
        resto = re.sub(r"\b(?:la\s+volta\s+scorsa|l['’]\s*altra\s+volta|tempo\s+fa|qualche\s+(?:giorno|settimana|mese)\s+fa|di\s+recente|ultimamente|prima)\b", "", resto, flags=re.I).strip(" ,")
        return {"tema": resto[:120], "periodo": per[:3] if per else None}

    def risposta_domanda(self, memoria, d, sessione=None):
        """→ (testo per il modello, meta) se trovo qualcosa; altrimenti None (risponde il modello con la memoria che ha)."""
        if not d or not (d["tema"] or d["periodo"]):
            return None
        da, a = (d["periodo"][0], d["periodo"][1]) if d["periodo"] else (None, None)
        q = d["tema"] or ""
        trovati = self.cerca(memoria, q, k=4, da=da, a=a, rigida=False) if q and _parole(q) else []
        if not trovati and d["periodo"] and not (q and _parole(q)):
            return None
        if not trovati:
            return None
        meta = {"tema": d["tema"], "periodo": d["periodo"][2] if d["periodo"] else "", "risultati": [dict(r, data=self._data(r)) for r in trovati]}
        righe = "\n".join(f"- {self._data(r)}{(' (chat «' + r['titolo'] + '»)') if r['titolo'] else ''}: la persona ha scritto «{_testo_breve(r['tu'], 300)}»; "
                          f"tu hai risposto «{_testo_breve(r['ai'], 200)}»" for r in trovati)
        return righe, meta

    @classmethod
    def testo_senza_modello(cls, meta):
        righe = [f"🧠 Sì, me lo ricordo! Ecco cosa ci siamo detti" + (f" su **{meta['tema']}**" if meta["tema"] else "") + ":"]
        for r in meta["risultati"]:
            righe.append(f"• **{r['data']}** — mi avevi scritto: «{_testo_breve(r['tu'], 160)}»")
        return "\n".join(righe)

    def router(self, testo, memoria):
        """«di cosa abbiamo parlato ieri?», «cosa ci siamo detti la settimana scorsa?» → le chat di quel giorno."""
        t = re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" ?!.")
        m = _RE_RIC_GIORNO.match(t)
        if not m:
            return None
        q = m.group("q") or ""
        per = periodo_ricordi(q)
        if not per:
            if _parole(re.sub(r"^(?:di|su|del|della|sul|sulla)\s+", "", q)):
                return None                                   # «di cosa abbiamo parlato sul lavoro» → per significato
            oggi = datetime.date.today()
            per = (oggi - datetime.timedelta(days=6), oggi, "Negli ultimi 7 giorni", "")
        da, a, etichetta = per[:3]
        with memoria._lock:
            voci = [x for x in memoria.diario if da.isoformat() <= (x.get("quando") or "")[:10] <= a.isoformat() and (x.get("tu") or "").strip()]
            titoli = {s["id"]: s.get("titolo", "") for s in memoria.sessioni}
            ultimo = next((x for x in reversed(memoria.diario) if (x.get("quando") or "")[:10] < da.isoformat() and (x.get("tu") or "").strip()), None)
        quando = etichetta + (f" ({data_it(da)})" if da == a and etichetta in ("Ieri", "L'altro ieri", "Oggi") else "")
        if not voci:
            t = f"🗓️ {quando} non abbiamo chiacchierato."
            if ultimo:
                g = datetime.date.fromisoformat(ultimo["quando"][:10])
                t += f" L'ultima volta prima è stata {data_it(g)}: chiedimi «di cosa abbiamo parlato il {g.day} {MESI_IT[g.month - 1]}?»."
            return {"testo": t, "ricordi": {"periodo": etichetta, "chat": []}}
        gruppi = collections.OrderedDict()
        for x in voci:
            k = (x["quando"][:10], x.get("sessione") or Memoria.PRINCIPALE)
            gruppi.setdefault(k, []).append(x)
        chat = []
        for (g, sid), xs in list(gruppi.items())[-10:]:
            domande = []
            for x in xs:
                d0 = _testo_breve(re.sub(r"\[📎[^\]]*\]", "📎", x["tu"]), 60)
                if d0 not in domande:
                    domande.append(d0)
            chat.append({"data": g, "ora": xs[0]["quando"][11:16], "sessione": sid, "titolo": titoli.get(sid, ""),
                         "n": len(xs), "domande": domande[:3]})
        piu_giorni = da != a
        righe = [f"🗓️ **{quando}** abbiamo chiacchierato {len(voci)} volt{'a' if len(voci) == 1 else 'e'}" + (", di:" if chat else ".")]
        for c in chat:
            g = datetime.date.fromisoformat(c["data"])
            quando_c = (f"{GIORNI_IT[g.weekday()]} {g.day}/{g.month} " if piu_giorni else "") + c["ora"]
            righe.append(f"• {quando_c} — " + " · ".join(f"«{d}»" for d in c["domande"]) + (f" (chat «{c['titolo']}»)" if c["titolo"] and c["titolo"] != "Chat principale" else "")
                         + (f" — {c['n']} messaggi" if c["n"] > 3 else ""))
        righe.append("Vuoi riprendere un discorso? Tocca «💬 Riapri» oppure chiedimi «ti ricordi cosa ti avevo detto su …?».")
        return {"testo": "\n".join(righe), "ricordi": {"periodo": etichetta, "chat": chat}}


RICORDI = Ricordi()


# ── 💡 PROATTIVO: MAIK ti propone un'idea quando serve (serie a rischio, budget, scadenze, impegni presto, bollette) ──
_RE_PRO_STOP = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:basta|stop|niente\s+pi[uù]|smetti(?:la)?\s+(?:di\s+(?:darmi|dare|farmi|fare|mandarmi)\s+)?|non\s+(?:darmi|mandarmi|farmi)\s+pi[uù]|"
                          r"spegni|disattiva|togli)\s*(?:i\s+|le\s+)?(?:tuoi\s+|tue\s+)?(?:consigli|suggerimenti|idee|avvisi\s+(?:spontanei|proattivi)|consigli\s+spontanei)(?:\s+spontane[ie])?(?:\s+per\s+favore)?$", re.I)
_RE_PRO_VIA = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:riattiva|riaccendi|attiva|accendi|rimetti)\s+(?:i\s+|le\s+)?(?:tuoi\s+|tue\s+)?(?:consigli|suggerimenti|idee)(?:\s+spontane[ie])?$|"
                         r"^(?:(?:maik|zep)[,!]?\s+)?(?:puoi\s+)?(?:ricominciare|tornare)\s+a\s+darmi\s+(?:i\s+)?(?:consigli|suggerimenti|idee)$", re.I)
_RE_PRO_CHIEDI = re.compile(r"^(?:(?:maik|zep)[,!]?\s+)?(?:hai\s+(?:qualche\s+|delle\s+|dei\s+|degli\s+|un['’]?\s*)?(?:idea|idee|consigli|consiglio|suggerimenti|suggerimento)\s+per\s+me|(?:che\s+)?cosa\s+mi\s+consigli(?:\s+di\s+fare)?(?:\s+oggi)?|"
                            r"(?:i\s+)?(?:tuoi\s+)?consigli\s+(?:per\s+)?oggi|c['’]?\s*[eè]\s+qualcosa\s+(?:a\s+cui|che)\s+(?:devo\s+)?(?:stare\s+attent[oa]|pensare|fare\s+attenzione)|"
                            r"a\s+cosa\s+devo\s+stare\s+attent[oa]|sono\s+in\s+regola\s+con\s+tutto)$", re.I)


class Proattivo:
    """v18: ogni tanto MAIK guarda abitudini, spese, cose da fare, calendario e bollette e, se serve, ti propone
    un'idea con i pulsanti per farla subito. Poche al giorno (MAIK_PROATTIVO_MAX), mai nelle ore di silenzio
    (MAIK_SILENZIO, es. 22-8); «basta consigli» le spegne, «riattiva i consigli» le riaccende."""
    REGOLE = {"serie": "🔥 Serie di un'abitudine a rischio (la sera)", "budget": "💶 Di questo passo sfori il budget",
              "scadenze": "📋 Cose che scadono domani (la sera)", "presto": "📅 Impegno presto domattina (la sera)",
              "bollette": "🧾 Bollette in scadenza", "ritardo": "⏰ Cose da fare in ritardo (la mattina)",
              "umore": "💚 Giorni un po' giù"}

    def __init__(self):
        self._lock = threading.Lock()
        self.coda = []
        self._ultimo = 0.0

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "proattivo.json")

    def _carica(self):
        try:
            with open(self._file(), encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                for k, v in (("attivo", True), ("spente", []), ("inviate", {}), ("pagate", [])):
                    d.setdefault(k, v)
                return d
        except Exception:
            pass
        return {"attivo": True, "spente": [], "inviate": {}, "pagate": []}

    def _salva(self, d):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(tmp, self._file())

    @staticmethod
    def silenzio(ora):
        s = CONFIG["silenzio"]
        if not s:
            return False
        a, b = s
        return (a <= ora.hour or ora.hour < b) if a > b else (a <= ora.hour < b)

    def stato(self):
        d = self._carica()
        oggi = datetime.date.today().isoformat()
        return {"attivo": CONFIG["proattivo"] and d["attivo"], "acceso_server": CONFIG["proattivo"], "oggi": len(d["inviate"].get(oggi, [])),
                "massimo": CONFIG["proattivo_max"], "silenzio": "-".join(map(str, CONFIG["silenzio"])) if CONFIG["silenzio"] else "",
                "regole": [{"chiave": k, "nome": v, "on": k not in d["spente"]} for k, v in self.REGOLE.items()]}

    def imposta(self, attivo=None, regola=None, on=None):
        with self._lock:
            d = self._carica()
            if attivo is not None:
                d["attivo"] = bool(attivo)
            if regola in self.REGOLE and on is not None:
                d["spente"] = [r for r in d["spente"] if r != regola] + ([] if on else [regola])
            self._salva(d)
        return self.stato()

    # ── le regole: ognuna → [idea]; un'idea = {id, regola, emoji, testo, azioni: [{etichetta, azione, dati}]} ──
    def idee(self, ora=None, memoria=None, sempre=False):
        """`sempre`: senza guardare l'ora (quando me lo chiedi tu: «hai qualche idea per me?»)."""
        ora = ora or datetime.datetime.now()
        oggi, d = ora.date(), self._carica()
        sera = sempre or ora.hour >= CONFIG["sera"]
        out = []
        # 🔥 serie di un'abitudine giornaliera a rischio
        if sera:
            try:
                dab = ABITUDINI._carica()
                for st in [ABITUDINI.stato(x, dab, oggi) for x in dab["abitudini"]]:
                    if st.get("settimanale") or not st["previsto_oggi"] or st["fatta_oggi"] or st["serie"] < 2:
                        continue
                    manca = f" (sei a {st['oggi']}/{st['obiettivo']} {st['unita']})".rstrip() if st["obiettivo"] > 1 and st["oggi"] else ""
                    out.append({"id": f"serie:{st['id']}:{oggi}", "regola": "serie", "emoji": "🔥",
                                "testo": f"🔥 La tua serie di **{st['emoji']} {st['nome']}** è a **{st['serie']} giorni** di fila{manca}: se la fai entro stasera non si spezza! Ce la fai?",
                                "azioni": [{"etichetta": "✓ Fatto!", "azione": "abitudine_fatta", "dati": {"id": st["id"]}},
                                           {"etichetta": "✅ Abitudini", "azione": "apri", "dati": {"pannello": "abitudini"}}]})
            except Exception as e:
                print(f"  ⚠  proattivo/serie: {e}")
        # 💶 di questo passo sfori il budget del mese (una volta a settimana)
        try:
            ultimo = (oggi.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - datetime.timedelta(days=1)
            if 5 <= oggi.day <= ultimo.day - 2 or sempre:
                b = SPESE.budget()
                dd = {"spese": SPESE.tutte()}
                mese = oggi.isoformat()[:7]
                casi = []
                for cat, lim in b.items():
                    usato = Spese._tot_mese(dd, mese, None if cat == "totale" else cat)
                    if not lim or usato >= lim or usato <= 0:
                        continue
                    prev = usato / max(1, oggi.day) * ultimo.day
                    if prev > lim * 1.05:
                        casi.append((prev / lim, cat, usato, prev, lim))
                if casi:
                    _, cat, usato, prev, lim = max(casi)
                    cosa = "budget del mese" if cat == "totale" else f"budget per {CAT_SPESE[cat]['emoji']} {CAT_SPESE[cat]['nome'].lower()}" if cat in CAT_SPESE else "budget"
                    resta = max(0.0, lim - usato)
                    al_giorno = resta / max(1, (ultimo - oggi).days + 1)
                    out.append({"id": f"budget:{cat}:{oggi.isocalendar()[1]}", "regola": "budget", "emoji": "💶",
                                "testo": f"💶 Di questo passo a fine {MESI_IT[oggi.month - 1]} arrivi a circa **{euro(prev)}**, più del {cosa} di {euro(lim)}. "
                                         f"Per restarci dentro hai {euro(resta)}: circa **{euro(al_giorno)} al giorno**. Vuoi vedere dove va la maggior parte?",
                                "azioni": [{"etichetta": "💶 Vedi le spese", "azione": "apri", "dati": {"pannello": "spese"}}]})
        except Exception as e:
            print(f"  ⚠  proattivo/budget: {e}")
        # 📋 domani scadono…
        if sempre or ora.hour >= CONFIG["sera"] - 2:
            try:
                dom = ATTIVITA.vista("domani", oggi)
                if dom:
                    nomi = ", ".join(f"**{a['testo']}**" for a in dom[:3]) + (f" e altre {len(dom) - 3}" if len(dom) > 3 else "")
                    out.append({"id": f"scadenze:{oggi}", "regola": "scadenze", "emoji": "📋",
                                "testo": f"📋 Domani scade{'' if len(dom) == 1 else 'no'} {nomi}. Vuoi portarti avanti adesso con un pomodoro, o le guardiamo domattina?",
                                "azioni": [{"etichetta": "🍅 Ci lavoro ora", "azione": "focus", "dati": {"id": dom[0]["id"], "testo": dom[0]["testo"]}},
                                           {"etichetta": "📋 Cose da fare", "azione": "apri", "dati": {"pannello": "todo"}}]})
            except Exception as e:
                print(f"  ⚠  proattivo/scadenze: {e}")
        # 📅 un impegno presto domattina → un promemoria un'ora prima
        if sempre or ora.hour >= CONFIG["sera"] - 2:
            try:
                dom0 = datetime.datetime.combine(oggi + datetime.timedelta(days=1), datetime.time(0, 0))
                occ = [o for o in CAL.occorrenze(dom0, dom0 + datetime.timedelta(hours=10, minutes=31)) if not o["tutto_giorno"] and o["inizio"] >= dom0]
                if occ:
                    o = occ[0]
                    prima = o["inizio"] - datetime.timedelta(hours=1)
                    out.append({"id": f"presto:{o['id']}:{oggi}", "regola": "presto", "emoji": "📅",
                                "testo": f"📅 Domani alle **{o['inizio'].strftime('%H:%M')}** hai **{o['titolo']}**" + (f" ({o['luogo']})" if o["luogo"] else "")
                                         + f". Vuoi che ti ricordi di prepararti alle {prima.strftime('%H:%M')}?",
                                "azioni": [{"etichetta": f"⏰ Sì, alle {prima.strftime('%H:%M')}", "azione": "promemoria",
                                            "dati": {"testo": f"Prepararti per: {o['titolo']} (alle {o['inizio'].strftime('%H:%M')})", "quando": prima.isoformat(timespec="minutes")}}]})
            except Exception as e:
                print(f"  ⚠  proattivo/presto: {e}")
        # 🧾 bollette che scadono entro 3 giorni (e non ancora segnate come pagate)
        try:
            for s in SPESE.tutte():
                sc = s.get("scadenza")
                if not sc or s["id"] in d["pagate"] or not (oggi.isoformat() <= sc <= (oggi + datetime.timedelta(days=3)).isoformat()):
                    continue
                q = quando_scade(sc, oggi)
                out.append({"id": f"bolletta:{s['id']}", "regola": "bollette", "emoji": "🧾",
                            "testo": f"🧾 **{s['descrizione']}** da **{euro(s['importo'])}** scade {q}. L'hai già pagata?",
                            "azioni": [{"etichetta": "✓ Già pagata", "azione": "bolletta_pagata", "dati": {"id": s["id"]}},
                                       {"etichetta": "⏰ Ricordamelo domani alle 9", "azione": "promemoria",
                                        "dati": {"testo": f"Pagare: {s['descrizione'].lower()} ({euro(s['importo'])})",
                                                 "quando": datetime.datetime.combine(oggi + datetime.timedelta(days=1), datetime.time(9, 0)).isoformat(timespec="minutes")}}]})
        except Exception as e:
            print(f"  ⚠  proattivo/bollette: {e}")
        # ⏰ cose in ritardo (la mattina): le sposto a domani?
        if sempre or CONFIG["giornata"][0] <= ora.hour < 13:
            try:
                rit = ATTIVITA.vista("ritardo", oggi)
                if len(rit) >= 2:
                    out.append({"id": f"ritardo:{oggi}", "regola": "ritardo", "emoji": "⏰",
                                "testo": f"⏰ Hai **{len(rit)} cose in ritardo**: " + ", ".join(a["testo"] for a in rit[:3]) + ("…" if len(rit) > 3 else "")
                                         + ". Le sposto a domani così ripartiamo puliti, o ne facciamo una adesso?",
                                "azioni": [{"etichetta": "➡️ Sposta a domani", "azione": "rimanda", "dati": {"ids": [a["id"] for a in rit[:50]]}},
                                           {"etichetta": "📋 Vediamole", "azione": "apri", "dati": {"pannello": "todo"}}]})
            except Exception as e:
                print(f"  ⚠  proattivo/ritardo: {e}")
        # 💚 un paio di giorni un po' giù → ti chiedo come va (al massimo ogni 3 giorni)
        if memoria is not None:
            try:
                rec = [u for u in memoria.umore[-4:] if u.get("data", "") >= (oggi - datetime.timedelta(days=3)).isoformat()]
                giu = [u for u in rec if valenza_umore(u.get("umore"), u.get("intensita", 5)) < 4]
                if len(giu) >= 2 and len(giu) >= len(rec) - 1:
                    out.append({"id": f"umore:{oggi.toordinal() // 3}", "regola": "umore", "emoji": "💚",
                                "testo": "💚 Negli ultimi giorni ti ho sentito un po' giù. Come stai adesso? Se ti va di raccontarmi, sono qui.",
                                "azioni": [{"etichetta": "💬 Ti racconto", "azione": "scrivi", "dati": {}}]})
            except Exception as e:
                print(f"  ⚠  proattivo/umore: {e}")
        return [x for x in out if x["regola"] not in d["spente"]]

    def controlla(self, ora=None, memoria=None, forza=False):
        """In sottofondo (ogni MAIK_PROATTIVO_OGNI secondi): le idee nuove vanno in coda per la GUI (GET /proattivo)."""
        if not CONFIG["proattivo"]:
            return []
        if not forza and time.time() - self._ultimo < CONFIG["proattivo_ogni"]:
            return []
        self._ultimo = time.time()
        ora = ora or datetime.datetime.now()
        if self.silenzio(ora):
            return []
        nuove = []
        with self._lock:
            d = self._carica()
            if not d["attivo"]:
                return []
            oggi = ora.date().isoformat()
            inviate = d["inviate"].setdefault(oggi, [])
            tutte = {i for v in d["inviate"].values() for i in v}
            for idea in self.idee(ora, memoria):
                if len(inviate) >= CONFIG["proattivo_max"]:
                    break
                if idea["id"] in tutte:
                    continue
                inviate.append(idea["id"])
                nuove.append(dict(idea, quando=ora.isoformat(timespec="seconds")))
            d["inviate"] = {k: v for k, v in d["inviate"].items() if k >= (ora.date() - datetime.timedelta(days=10)).isoformat()}
            self._salva(d)
            self.coda = (self.coda + nuove)[-10:]
        return nuove

    def prendi(self):
        with self._lock:
            c, self.coda = self.coda, []
        return c

    def esegui(self, azione, dati, memoria):
        """I pulsanti delle idee. → {ok, testo}"""
        dati = dati if isinstance(dati, dict) else {}
        if azione == "abitudine_fatta":
            st = ABITUDINI.segna(str(dati.get("id", "")))
            return {"ok": bool(st), "testo": ABITUDINI.testo_segnato(st) if st else "Non trovo più quell'abitudine.", **({"abitudine": st} if st else {})}
        if azione == "promemoria":
            testo = re.sub(r"\s+", " ", str(dati.get("testo") or "")).strip()[:120]
            try:
                quando = datetime.datetime.fromisoformat(str(dati.get("quando") or ""))
            except ValueError:
                quando = None
            if len(testo) < 2 or not quando:
                return {"ok": False, "testo": "Promemoria non valido."}
            if quando <= datetime.datetime.now():
                quando = datetime.datetime.now() + datetime.timedelta(minutes=5)
            memoria.aggiungi_promemoria(testo, quando, "promemoria")
            return {"ok": True, "testo": f"⏰ Ok! Ti ricordo «{testo}» {fmt_quando(quando)}."}
        if azione == "rimanda":
            q = (datetime.date.today() + datetime.timedelta(days=1)).isoformat()
            n = len([x for x in (ATTIVITA.modifica(str(i), scadenza=q) for i in (dati.get("ids") or [])[:50]) if x])
            return {"ok": bool(n), "testo": f"➡️ Spostat{'a' if n == 1 else 'e'} a domani {n} cos{'a' if n == 1 else 'e'}. Si riparte puliti! 💪" if n else "Niente da spostare."}
        if azione == "bolletta_pagata":
            with self._lock:
                d = self._carica()
                if dati.get("id") and dati["id"] not in d["pagate"]:
                    d["pagate"] = (d["pagate"] + [str(dati["id"])])[-500:]
                self._salva(d)
            return {"ok": True, "testo": "🧾 Perfetto, segnata come pagata: non te la ricordo più. ✅"}
        if azione == "spegni_regola":
            r = str(dati.get("regola", ""))
            if r not in self.REGOLE:
                return {"ok": False, "testo": "Tipo di consiglio sconosciuto."}
            self.imposta(regola=r, on=False)
            return {"ok": True, "testo": f"🔕 Va bene: niente più consigli di questo tipo ({self.REGOLE[r]}). Li riaccendi dalle ⚙️ impostazioni."}
        return {"ok": False, "testo": "Azione sconosciuta."}

    def router(self, testo, memoria):
        t = re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" ?!.")
        if _RE_PRO_STOP.match(t):
            self.imposta(attivo=False)
            return {"testo": "🔕 Va bene, niente più consigli spontanei. Se cambi idea dimmi «riattiva i consigli» (o chiedimi «hai qualche idea per me?» quando vuoi tu)."}
        if _RE_PRO_VIA.match(t):
            st = self.imposta(attivo=True)
            extra = "" if st["acceso_server"] else " (però il server è avviato con MAIK_PROATTIVO=0: toglilo per riceverli)"
            return {"testo": f"💡 Consigli riattivati! Te ne darò al massimo {st['massimo']} al giorno" + (f", mai tra le {st['silenzio'].replace('-', ' e le ')}" if st["silenzio"] else "") + "." + extra}
        if _RE_PRO_CHIEDI.match(t):
            idee = self.idee(memoria=memoria, sempre=True)
            if not idee:
                return {"testo": "💡 Per ora è tutto sotto controllo: niente in ritardo, il budget regge, le serie sono al sicuro e domani non ci sono sorprese. 👍"}
            quante = "l'idea" if len(idee) == 1 else f"{min(5, len(idee))} idee"
            return {"testo": f"💡 Ecco {quante} che ho per te:\n" + "\n".join("• " + x["testo"] for x in idee[:5]), "idee": idee[:5]}
        return None


