# ════════════════════════════════════════════════════════════
# v19 — MAIK PRIME: automazioni, ricerca approfondita, centro di controllo
# ════════════════════════════════════════════════════════════
_CTX = threading.local()          # cosa sta facendo questo thread (in un'automazione: niente comandi del PC)

# ── ⚙️ AUTOMAZIONI: «ogni lunedì alle 9 dimmi quanto ho speso», e MAIK lo fa da solo ──
_VERBI_AUTO = (r"dimmi|dammi|fammi|mandami|leggimi|mostrami|ricordami|ricorda(?:mi)?|fai|prepara(?:mi)?|controlla|cerca|riassumi(?:mi)?|esegui|calcola|"
               r"aggiorna(?:mi)?|pianifica(?:mi)?|chiudiamo|cosa|com['’]|quanto|quanti|quali|che|qual|briefing|notizie|meteo|scrivimi|suggeriscimi|consigliami|motivami|"
               r"accendi|radio|notiziario|storie|ripassiamo|ripasso|interrogami|quante|facciamo|quiz|menu|ricetta|respiriamo|rapporto|aggiornami|situazione|status|"
               r"analizza|confronta|grafico|previsione|in\s+che")   # v24-26: «ogni mattina alle 8 accendi radio maik», «ogni sera alle 21 ripassiamo», «ogni domenica alle 10 fammi il menu della settimana»
_RE_AUTO_CREA = re.compile(r"^(?:(?:maik|zep|prime)[,!]?\s+)?(?:(?:crea|nuova|aggiungi|imposta)\s+(?:un['’]\s*|una\s+)?automazione\s*[:,]?\s*|automazione\s*[:,]\s*)?"
                           r"(?P<quando>(?:ogni|tutti\s+i|tutte\s+le)\s+[^,]+?|nei\s+giorni\s+feriali|nel\s+(?:weekend|fine\s+settimana)|dal\s+luned[iì]\s+al\s+venerd[iì])"
                           r"(?:\s+(?:alle|all['’]|verso\s+le)\s*(?P<ora>\d{1,2}(?:[:.]\d{2})?))?\s*[,:]?\s+(?P<cosa>(?:" + _VERBI_AUTO + r")\b.*)$", re.I)
_RE_AUTO_NOME = r"(?:\s+(?:l['’]\s*)?automazion[ei])"
_RE_AUTO_ELENCO = re.compile(r"^(?:(?:maik|zep|prime)[,!]?\s+)?(?:(?:le\s+)?(?:mie\s+)?automazioni|(?:che|quali)\s+automazioni\s+(?:ho|ci\s+sono|hai)|cosa\s+fai\s+da\s+solo|mostrami\s+le\s+automazioni)$", re.I)
_RE_AUTO_AZIONE = re.compile(r"^(?:(?:maik|zep|prime)[,!]?\s+)?(?P<v>cancella|elimina|togli|rimuovi|ferma|sospendi|metti\s+in\s+pausa|disattiva|riattiva|riprendi|attiva|esegui|lancia|fai\s+partire|prova)"
                             r"\s+(?:l['’]\s*|un['’]\s*)?automazione\s*(?:n(?:umero|\.)?\s*)?(?:del(?:le|la|lo|l['’])?|di|su(?:l|lla|lle|i)?|che|per)?\s*(?P<t>.*)$", re.I)
_GIORNI_AUTO = [(r"luned[iì]", 0), (r"marted[iì]", 1), (r"mercoled[iì]", 2), (r"gioved[iì]", 3), (r"venerd[iì]", 4), (r"sabat[oi]", 5), (r"domenic(?:a|he)", 6)]
_PARTI_GIORNO = [(r"mattin", "08:00"), (r"pomeriggi", "15:00"), (r"\bsera\b|\bsere\b|serat", "21:00"), (r"\bnott", "23:00")]


def interpreta_quando_auto(quando, ora_txt=""):
    """«ogni mattina» + «8» → {giorni: [0..6], ora: "08:00"} · «ogni 2 ore» → {ogni_min: 120} · None se non lo capisco."""
    q = (quando or "").lower()
    m = re.search(r"ogni\s+(\d{1,3})\s+(minut|or[ae])", q)
    if m or re.search(r"ogni\s+(?:mezz['’]?\s*ora|ora|quarto\s+d['’]\s*ora)\b", q):
        if m:
            n = int(m.group(1)) * (60 if m.group(2).startswith("or") else 1)
        else:
            n = 30 if "mezz" in q else 15 if "quarto" in q else 60
        return {"ogni_min": max(15, min(24 * 60, n))}
    if re.search(r"feriali|dal\s+luned[iì]\s+al\s+venerd[iì]", q):
        giorni = [0, 1, 2, 3, 4]
    elif re.search(r"weekend|fine\s+settimana", q):
        giorni = [5, 6]
    else:
        giorni = sorted({n for rx, n in _GIORNI_AUTO if re.search(rx, q)})
        if not giorni:
            if re.search(r"\bgiorn[oi]\b|mattin|sera|pomeriggi|nott|\bdì\b", q):
                giorni = list(range(7))
            elif re.search(r"settiman", q):
                giorni = [0]
            else:
                return None
    ora = None
    if ora_txt:
        p = re.split(r"[:.]", ora_txt)
        h, mi = int(p[0]), int(p[1]) if len(p) > 1 else 0
        if re.search(r"pomeriggi|sera|serat", q) and h < 12:
            h += 12
        if 0 <= h <= 23 and 0 <= mi <= 59:
            ora = f"{h:02d}:{mi:02d}"
        else:
            return None
    ora = ora or next((o for rx, o in _PARTI_GIORNO if re.search(rx, q)), "09:00")
    return {"giorni": giorni, "ora": ora}


def descrivi_quando(a):
    if a.get("ogni_min"):
        n = a["ogni_min"]
        return "ogni ora" if n == 60 else f"ogni {n // 60} ore" if n % 60 == 0 else f"ogni {n} minuti"
    g = a.get("giorni") or []
    if len(g) == 7:
        quando = "ogni giorno"
    elif g == [0, 1, 2, 3, 4]:
        quando = "nei giorni feriali"
    elif g == [5, 6]:
        quando = "nel weekend"
    else:
        nomi = [("la " if x == 6 else "il ") + GIORNI_LUNGHI[x] for x in g]
        quando = "ogni " + GIORNI_LUNGHI[g[0]] if len(g) == 1 else ", ".join(nomi[:-1]) + " e " + nomi[-1]
    return f"{quando} alle {a.get('ora', '09:00')}"


class Automazioni:
    """Le cose che MAIK fa da solo a un orario: un comando qualsiasi della chat («dimmi il meteo e le notizie»,
    «quanto ho speso questa settimana?», «pianificami la giornata»…) o un semplice avviso («ricordami di …»).
    Il risultato arriva nella GUI come messaggio (GET /automazioni/avvisi) e resta nella chat «⚙️ Automazioni».
    Nelle automazioni niente comandi del PC: quelli li confermi sempre tu."""
    MAX = 30

    def __init__(self):
        self._lock = threading.RLock()
        self.avvisi = []
        self._in_corso = set()

    @staticmethod
    def _file():
        return os.path.join(DATA_DIR, "automazioni.json")

    def _carica(self):
        try:
            with open(self._file(), encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                for k, v in (("automazioni", []), ("esiti", []), ("sessione", "")):
                    d.setdefault(k, v)
                return d
        except Exception:
            pass
        return {"automazioni": [], "esiti": [], "sessione": ""}

    def _salva(self, d):
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = self._file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(tmp, self._file())

    @staticmethod
    def prossima(a, dopo=None):
        """La prossima volta che tocca, dopo `dopo`."""
        dopo = dopo or datetime.datetime.now()
        if a.get("ogni_min"):
            try:
                base = datetime.datetime.fromisoformat(a.get("ultima") or a["creata"])
            except (KeyError, ValueError):
                base = dopo
            passo = datetime.timedelta(minutes=a["ogni_min"])
            n = max(1, int((dopo - base) / passo) + 1) if dopo >= base else 1
            return base + n * passo
        h, mi = map(int, a.get("ora", "09:00").split(":"))
        for i in range(0, 8):
            g = dopo.date() + datetime.timedelta(days=i)
            t = datetime.datetime.combine(g, datetime.time(h, mi))
            if g.weekday() in (a.get("giorni") or range(7)) and t > dopo:
                return t
        return dopo + datetime.timedelta(days=7)

    def _vista(self, a):
        return dict(a, descrizione=descrivi_quando(a), prossima=self.prossima(a).isoformat(timespec="minutes") if a.get("attiva", True) else None)

    def elenco(self):
        return [self._vista(a) for a in self._carica()["automazioni"]]

    def esiti(self, n=20):
        return self._carica()["esiti"][-n:]

    def crea(self, comando, quando, testo=""):
        comando = re.sub(r"\s+", " ", str(comando or "")).strip(" .,;:")[:200]
        if len(comando) < 3:
            return None, "manca cosa devo fare"
        if not quando:
            return None, "non ho capito quando (es. «ogni giorno alle 8», «ogni lunedì alle 9», «nei giorni feriali alle 7:30», «ogni 2 ore»)"
        avviso = re.match(r"^(?:ricordami|ricorda(?:mi)?)\s+(?:di\s+|che\s+)?(?P<x>.+)$", comando, re.I)
        a = {"id": uuid.uuid4().hex[:8], "comando": comando, "tipo": "avviso" if avviso else "comando", "avviso": avviso.group("x") if avviso else "",
             "creata": datetime.datetime.now().isoformat(timespec="seconds"), "attiva": True, "ultima": None, "volte": 0, "testo": str(testo or "")[:240],
             **{k: quando[k] for k in ("giorni", "ora", "ogni_min") if k in quando}}
        with self._lock:
            d = self._carica()
            if len(d["automazioni"]) >= self.MAX:
                return None, f"hai già {self.MAX} automazioni: cancellane qualcuna"
            if any(x["comando"].lower() == comando.lower() and descrivi_quando(x) == descrivi_quando(a) for x in d["automazioni"]):
                return None, "c'è già un'automazione uguale"
            d["automazioni"].append(a)
            self._salva(d)
        return self._vista(a), None

    def crea_da_testo(self, testo):
        m = _RE_AUTO_CREA.match(re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" .!"))
        if not m:
            return None, "non ho capito: prova con «ogni giorno alle 8 dimmi il meteo e le notizie»"
        return self.crea(m.group("cosa"), interpreta_quando_auto(m.group("quando"), m.group("ora") or ""), testo)

    def _modifica(self, aid, **campi):
        with self._lock:
            d = self._carica()
            a = next((x for x in d["automazioni"] if x["id"] == aid), None)
            if not a:
                return None
            a.update(campi)
            self._salva(d)
            return self._vista(a)

    def imposta(self, aid, attiva):
        return self._modifica(aid, attiva=bool(attiva))

    def elimina(self, aid):
        with self._lock:
            d = self._carica()
            prima = len(d["automazioni"])
            d["automazioni"] = [x for x in d["automazioni"] if x["id"] != aid]
            self._salva(d)
            return len(d["automazioni"]) < prima

    def trova(self, testo):
        t = (testo or "").strip(" ?!.").lower()
        L = self._carica()["automazioni"]
        if not L:
            return None
        if not t or t in ("questa", "quella", "l'ultima", "ultima"):
            return L[-1] if (len(L) == 1 or t) else None
        if re.fullmatch(r"\d{1,2}", t):
            i = int(t) - 1
            return L[i] if 0 <= i < len(L) else None
        tok = _token(t)
        meglio, punti = None, 0
        for a in L:
            p = len(tok & _token(a["comando"] + " " + descrivi_quando(a)))
            if p > punti:
                meglio, punti = a, p
        return meglio

    def _sessione(self, memoria):
        with self._lock:
            d = self._carica()
            if d["sessione"] and memoria.sessione_valida(d["sessione"]) == d["sessione"]:
                return d["sessione"]
            s = memoria.crea_sessione("⚙️ Automazioni")
            d["sessione"] = s["id"]
            self._salva(d)
            return s["id"]

    def esegui(self, a, motore, avvisa=True):
        """Fa l'automazione adesso → l'esito {id, automazione, descrizione, comando, quando, testo, meta}.
        avvisa=False: il risultato lo mostra già chi l'ha chiesta (non va anche tra gli avvisi della GUI)."""
        ora = datetime.datetime.now()
        if a.get("tipo") == "avviso":
            testo, meta = f"⏰ Ti ricordo: **{a['avviso']}**", {}
        else:
            sid = self._sessione(motore.memoria)
            out, prima = [], getattr(_CTX, "automazione", False)
            _CTX.automazione = True
            cmd = a["comando"]                                     # «dimmi quanto ho speso…» → «quanto ho speso…» (così risponde subito la funzione giusta)
            m = re.match(r"^(?:dimmi|dammi|mostrami|fammi\s+(?:sapere|vedere))\s+(?P<r>(?:quanto|quanti|quante|cosa|che|com['’]|come|quali|qual|le|il|la|lo|i|gli)\b.+)$", cmd, re.I)
            if m:
                cmd = m.group("r")
            try:
                meta = motore.rispondi_stream(cmd, out.append, sessione=sid) or {}
            except Exception as e:
                meta = {"ok": False, "risposta": f"errore: {str(e)[:120]}"}
            finally:
                _CTX.automazione = prima
            if meta.get("comando"):
                testo = "(comando interno)"
            else:
                testo = pulisci_pensiero("".join(out)).strip() or meta.get("risposta") or "Fatto."
        es = {"id": uuid.uuid4().hex[:8], "automazione": a["id"], "descrizione": descrivi_quando(a), "comando": a["comando"],
              "quando": ora.isoformat(timespec="seconds"), "testo": testo[:8000],
              "meta": {k: meta[k] for k in _CHIAVI_META_AUTO if meta.get(k)}}
        with self._lock:
            d = self._carica()
            for x in d["automazioni"]:
                if x["id"] == a["id"]:
                    x["ultima"], x["volte"] = ora.isoformat(timespec="seconds"), x.get("volte", 0) + 1
            d["esiti"] = (d["esiti"] + [{k: es[k] for k in ("id", "automazione", "descrizione", "comando", "quando", "testo")}])[-60:]
            self._salva(d)
            if avvisa:
                self.avvisi = (self.avvisi + [es])[-20:]
        return es

    def _esegui_sicuro(self, a, motore):
        try:
            self.esegui(a, motore)
        except Exception as e:
            print(f"  ⚠  automazione «{a.get('comando', '')[:40]}»: {e}")
        finally:
            with self._lock:
                self._in_corso.discard(a["id"])

    def controlla(self, motore, ora=None, aspetta=False):
        """In sottofondo: fa partire quelle che toccano (al massimo 2 ore di ritardo, poi salta a quella dopo)."""
        ora = ora or datetime.datetime.now()
        da_fare = []
        with self._lock:
            d = self._carica()
            cambiato = False
            for a in d["automazioni"]:
                if not a.get("attiva", True) or a["id"] in self._in_corso:
                    continue
                rif = datetime.datetime.fromisoformat(a.get("ultima") or a["creata"])
                tocca = self.prossima(a, rif)
                if tocca > ora:
                    continue
                if ora - tocca > datetime.timedelta(hours=2):            # il PC era spento: niente valanga di arretrati
                    a["ultima"] = ora.isoformat(timespec="seconds")
                    cambiato = True
                    continue
                self._in_corso.add(a["id"])
                da_fare.append(dict(a))
            if cambiato:
                self._salva(d)
        for a in da_fare:
            if aspetta:
                self._esegui_sicuro(a, motore)
            else:
                threading.Thread(target=self._esegui_sicuro, args=(a, motore), daemon=True).start()
        return [a["id"] for a in da_fare]

    def prendi_avvisi(self):
        with self._lock:
            a, self.avvisi = self.avvisi, []
        return a

    def router(self, testo, motore):
        t = re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" ?!.")
        if _RE_AUTO_ELENCO.match(t):
            L = self.elenco()
            if not L:
                return {"testo": "⚙️ Non hai ancora automazioni. Prova: «**ogni mattina alle 8 dimmi il meteo e le notizie**», «**ogni lunedì alle 9 dimmi quanto ho speso la settimana scorsa**», «**ogni sera alle 22 chiudiamo la giornata**».",
                        "automazioni": []}
            righe = [f"⚙️ **Le tue automazioni** ({len(L)}):"]
            for i, a in enumerate(L, 1):
                righe.append(f"{i}. {'' if a.get('attiva', True) else '⏸ '}**{a['descrizione']}** — «{a['comando']}»" + (f" · fatta {a['volte']} volt{'a' if a['volte'] == 1 else 'e'}" if a.get("volte") else ""))
            return {"testo": "\n".join(righe), "automazioni": L}
        m = _RE_AUTO_AZIONE.match(t)
        if m:
            v = m.group("v").lower()
            a = self.trova(m.group("t"))
            if not a:
                return {"testo": "⚙️ Non trovo quell'automazione. Dimmi «le mie automazioni» per vederle tutte."}
            if v in ("cancella", "elimina", "togli", "rimuovi"):
                self.elimina(a["id"])
                return {"testo": f"🗑️ Tolta l'automazione «{a['comando']}» ({descrivi_quando(a)})."}
            if v in ("ferma", "sospendi", "metti in pausa", "disattiva"):
                x = self.imposta(a["id"], False)
                return {"testo": f"⏸ Sospesa: «{a['comando']}» ({descrivi_quando(a)}). Dimmi «riattiva l'automazione …» per farla ripartire.", "automazione": x}
            if v in ("riattiva", "riprendi", "attiva"):
                x = self.imposta(a["id"], True)
                return {"testo": f"▶️ Riattivata: «{a['comando']}» — {x['descrizione']}.", "automazione": x}
            es = self.esegui(a, motore, avvisa=False)
            return dict({"testo": f"⚙️ **{es['descrizione']}** · «{es['comando']}»\n\n{es['testo']}", "automazione": self._vista(a)}, **es["meta"])
        if _RE_AUTO_CREA.match(t):
            a, err = self.crea_da_testo(t)
            if not a:
                return {"testo": "⚙️ " + err[:1].upper() + err[1:] + "."}
            p = datetime.datetime.fromisoformat(a["prossima"])
            cosa = f"ti ricorderò: «{a['avviso']}»" if a["tipo"] == "avviso" else f"farò da solo: «{a['comando']}»"
            return {"testo": f"⚙️ Fatto! **{a['descrizione'][:1].upper() + a['descrizione'][1:]}** {cosa}. La prima volta: **{fmt_quando(p)}**. "
                             "Il risultato ti arriva qui e resta nella chat «⚙️ Automazioni».", "automazione": a}
        return None


