# ── 🔬 RICERCA APPROFONDITA: più ricerche, legge le fonti, scrive un rapporto con le citazioni (e lo salva nei documenti) ──
_RE_RICERCA_PROFONDA = re.compile(r"^(?:(?:maik|zep|prime)[,!]?\s+)?(?:(?:puoi|potresti)\s+)?(?:(?:fa(?:i|mmi)|esegui|prepara(?:mi)?)\s+(?:una\s+)?ricerca\s+(?:approfondita|completa|dettagliata|seria|a\s+fondo)|"
                                  r"ricerca\s+approfondita|studia(?:mi)?\s+(?:bene|a\s+fondo)|fammi\s+un\s+rapporto(?:\s+(?:completo|dettagliato))?|"
                                  r"approfondisci\s+(?:bene|a\s+fondo)|indaga\s+(?:bene|a\s+fondo))"
                                  r"\s*[:,]?\s*(?:(?:sulle|sulla|sullo|sugli|sui|sul|su|delle|della|dello|degli|dei|del|di|per|riguardo\s+(?:alla|allo|al|a))\s+|(?:sull|dell|all)['’]\s*)?(?P<t>.{2,})$", re.I)
PROMPT_RICERCA_PIANO = ("Devo fare una ricerca approfondita su internet su: «{tema}».\nScrivi in JSON {{\"domande\": [...]}} da 3 a 4 ricerche diverse e precise, "
                        "in italiano, brevi come quelle che si scrivono su un motore di ricerca, che insieme coprono il tema: cos'è e il contesto, dati e fatti "
                        "recenti, pro e contro o confronti, consigli pratici. Solo il JSON.")
PROMPT_RAPPORTO_SYS = ("Sei MAIK PRIME, un ricercatore preciso e chiaro. Scrivi in italiano, in Markdown, usando SOLO le fonti date e citandole col numero "
                       "tra parentesi quadre, es. [1] o [2][3]. Se le fonti non bastano o non sono d'accordo, dillo.")
PROMPT_RAPPORTO = ("[FONTI DELLA RICERCA su «{tema}» — {n} fonti, la persona non le vede]\n{fonti}\n[FINE FONTI]\n\n"
                   "Scrivi il rapporto: un titolo (# …), «**In breve:**» con 2-3 frasi, poi 3-5 sezioni (## …) che rispondono a queste domande: {domande}; "
                   "infine «## Cosa ti consiglio» con 2-4 punti pratici. Cita le fonti [n] in ogni sezione. Niente elenco delle fonti alla fine (lo aggiungo io).")


def ricerca_profonda(testo):
    m = _RE_RICERCA_PROFONDA.match((testo or "").strip().rstrip(" ?!."))
    return m.group("t").strip(" :,") if m else None


def rapporto_senza_modello(tema, domande, fonti):
    righe = [f"# 🔬 Ricerca: {tema}", "", f"**In breve:** ho letto {len(fonti)} fonti. Senza il modello non posso scrivere il rapporto: ecco i punti principali di ogni ricerca.", ""]
    for q in domande:
        fq = [f for f in fonti if f.get("domanda") == q]
        if not fq:
            continue
        righe.append(f"## {q[:1].upper() + q[1:]}")
        for f in fq[:3]:
            pezzo = (f.get("testo") or f.get("estratto") or "")[:260].rsplit(" ", 1)[0]
            righe.append(f"- **{f['titolo']}** [{f['n']}] — {pezzo}…")
        righe.append("")
    return "\n".join(righe).strip()


def ricerca_approfondita(tema, cervello, memoria, on_token, avvisa=lambda e: None):
    """→ {testo, fonti_web, ricerca, stat}. Gli eventi per la GUI: {"ricerca": {fase, di, q}} e i chip degli strumenti."""
    tema = re.sub(r"\s+", " ", tema).strip()[:150]
    avvisa({"lavoro": {"tipo": "cerca_internet", "icona": "🔬", "testo": f"Ricerca approfondita: «{tema}»…"}})
    online = cervello.disponibile()
    domande = []
    if online:
        j = cervello.pensa_json(PROMPT_RICERCA_PIANO.format(tema=tema)) or {}
        domande = [re.sub(r"\s+", " ", str(x)).strip(" ?.")[:150] for x in (j.get("domande") or []) if isinstance(x, str) and len(x.strip()) > 2][:4]
    if len(domande) < 2:
        domande = [tema, f"{tema} cos'è e come funziona", f"{tema} vantaggi e svantaggi", f"{tema} novità e consigli"]
    fonti, viste = [], set()
    for i, q in enumerate(domande, 1):
        avvisa({"ricerca": {"fase": i, "di": len(domande), "q": q}})
        w = WEB.ricerca(q)
        nuove = 0
        for f in w.get("fonti", []):
            if f["url"] in viste:
                continue
            viste.add(f["url"])
            nuove += 1
            fonti.append(dict(f, n=len(fonti) + 1, domanda=q))
        avvisa({"strumento": {"tipo": "cerca_internet", "ok": bool(w.get("ok")), "icona": "🔬",
                              "esito": f"«{q[:50]}»: {len(w.get('fonti', []))} fonti" + (f" ({nuove} nuove)" if w.get("ok") and nuove != len(w.get("fonti", [])) else "") if w.get("ok") else f"«{q[:50]}»: niente"}})
        if len(fonti) >= 10:
            break
    if not fonti:
        t = f"🔬 Non sono riuscito a trovare fonti su internet per «{tema}» (internet non risponde?). Riprova tra poco."
        on_token(t)
        return {"testo": t, "fonti_web": []}
    avvisa({"ricerca": {"fase": "scrivo", "fonti": len(fonti)}})
    dati = "\n\n".join(f"[{f['n']}] {f['titolo']} — {f['sito']}\n{(f.get('testo') or f.get('estratto') or '')[:1600]}" for f in fonti)
    stat, rapporto = {}, ""
    if online:
        rapporto = cervello.pensa_stream(PROMPT_RAPPORTO_SYS, [{"role": "user", "content": PROMPT_RAPPORTO.format(tema=tema, n=len(fonti), fonti=dati, domande="; ".join(domande))}], on_token, stat)
    if not rapporto or rapporto.startswith("__ERRORE"):
        rapporto = rapporto_senza_modello(tema, domande, fonti)
        on_token(rapporto)
    rapporto = pulisci_pensiero(rapporto).strip()
    pulito = re.sub(r'[\\/:*?"<>|]+', " ", tema)[:60].strip()
    nome = f"Ricerca — {pulito}.md"
    elenco = "\n".join(f"[{f['n']}] {f['titolo']} — {f['url']}" for f in fonti)
    doc, err = memoria.aggiungi_documento(nome, f"{rapporto}\n\n---\nRicerca approfondita del {data_it(datetime.datetime.now())}: {'; '.join(domande)}\n\n## Fonti\n{elenco}")
    fw = [{k: f[k] for k in ("n", "titolo", "url", "sito", "estratto")} for f in fonti]
    return {"testo": rapporto, "fonti_web": fw, "stat": stat,
            "ricerca": {"tema": tema, "domande": domande, "fonti": len(fonti), "documento": nome if doc else "", "errore_doc": err or "", "parole": len(rapporto.split())}}


# ── 🛰️ CENTRO DI CONTROLLO: la tua giornata in un colpo d'occhio, con il punteggio Prime ──
_RE_PRIME = re.compile(r"^(?:(?:maik|zep|prime)[,!]?\s+)?(?:(?:apri\s+(?:il\s+)?)?centro\s+di\s+controllo|(?:la\s+)?(?:mia\s+)?panoramica(?:\s+di\s+oggi)?|dashboard|"
                       r"(?:qual\s+[eè]\s+)?(?:il\s+)?(?:mio\s+)?punteggio(?:\s+(?:prime|di\s+oggi))?|come\s+sto\s+andando\s+oggi|come\s+va\s+la\s+(?:mia\s+)?giornata)$", re.I)


def prime_oggi(memoria, ora=None):
    """Tutto quello che conta oggi + il punteggio Prime (0-100: cose fatte, abitudini, concentrazione)."""
    ora = ora or datetime.datetime.now()
    oggi = ora.date()
    o = oggi.isoformat()
    att_oggi = ATTIVITA.vista("oggi", oggi)
    fatte_oggi = [a for a in ATTIVITA.tutte() if (a.get("fatta") or "")[:10] == o]
    st = ABITUDINI.tutte_stato()
    previste = [a for a in st if a["previsto_oggi"] and not a.get("settimanale")]
    foc = ATTIVITA.statistiche(oggi, oggi)
    voci = []
    if att_oggi or fatte_oggi:
        voci.append(("cose", len(fatte_oggi) / (len(fatte_oggi) + len(att_oggi))))
    if previste:
        voci.append(("abitudini", sum(1 for a in previste if a["fatta_oggi"]) / len(previste)))
    if voci or foc["pomodori"]:
        voci.append(("concentrazione", min(1.0, foc["pomodori"] / 4)))
    punteggio = round(100 * sum(v for _, v in voci) / len(voci)) if voci else None
    mese = o[:7]
    dd = {"spese": SPESE.tutte()}
    b = SPESE.budget()
    usato = Spese._tot_mese(dd, mese)
    occ = CAL.occorrenze(datetime.datetime.combine(oggi, datetime.time(0, 0)), datetime.datetime.combine(oggi + datetime.timedelta(days=2), datetime.time(0, 0)))
    umore = []
    for i in range(6, -1, -1):
        g = (oggi - datetime.timedelta(days=i)).isoformat()
        v = [valenza_umore(u.get("umore"), u.get("intensita", 5)) for u in memoria.umore if u.get("data") == g]
        umore.append({"data": g, "valore": round(sum(v) / len(v), 1) if v else None})
    pro = PROATTIVO.stato()
    autos = sorted([a for a in AUTOMAZIONI.elenco() if a.get("prossima")], key=lambda a: a["prossima"])[:4]
    prom = sorted([p for p in memoria.promemoria_attivi() if p.get("quando")], key=lambda p: p["quando"])[:4]
    return {"data": oggi.isoformat(), "ora": ora.strftime("%H:%M"), "titolo": data_it(oggi).capitalize(), "punteggio": punteggio,
            "voci": [{"nome": n, "perc": round(100 * v)} for n, v in voci],
            "attivita": {"da_fare": [{k: a[k] for k in ("id", "testo", "priorita", "scadenza")} for a in att_oggi[:6]], "n_da_fare": len(att_oggi),
                         "fatte": len(fatte_oggi), "ritardo": len(ATTIVITA.vista("ritardo", oggi))},
            "abitudini": [{k: a[k] for k in ("id", "emoji", "nome", "fatta_oggi", "serie", "oggi", "obiettivo")} for a in previste],
            "focus": foc,
            "spese": {"mese": usato, "budget": b.get("totale"), "perc": round(100 * usato / b["totale"]) if b.get("totale") else None,
                      "oggi": round(sum(s["importo"] for s in dd["spese"] if s["data"] == o), 2)},
            "agenda": [{"giorno": "oggi" if x["inizio"].date() == oggi else "domani", "ora": "tutto il giorno" if x["tutto_giorno"] else x["inizio"].strftime("%H:%M"),
                        "titolo": x["titolo"], "passato": x["inizio"] < ora and not x["tutto_giorno"]} for x in occ][:8],
            "umore": umore, "idee": {"attive": pro["attivo"], "oggi": pro["oggi"], "massimo": pro["massimo"]},
            "automazioni": [{k: a[k] for k in ("id", "comando", "descrizione", "prossima")} for a in autos],
            "promemoria": [{"testo": p["testo"], "quando": p["quando"]} for p in prom],
            "ricordi": len([x for x in memoria.diario if (x.get("tu") or "").strip()]),
            "obiettivi": [{"id": o["id"], "emoji": o["emoji"], "titolo": o["titolo"], "perc": o["perc"], "ritmo": o["ritmo"], "prossima": (o["prossima"] or {}).get("titolo", ""),
                           "giorni_rimasti": o["giorni_rimasti"]} for o in (OBIETTIVI.elenco() if "OBIETTIVI" in globals() else [])]}


def prime_testo(p):
    righe = [f"🛰️ **{p['titolo']}**" + (f" · punteggio Prime **{p['punteggio']}/100**" if p["punteggio"] is not None else "")]
    a = p["attivita"]
    righe.append(f"📋 Cose da fare: {a['fatte']} fatte, {a['n_da_fare']} per oggi" + (f" (⚠️ {a['ritardo']} in ritardo)" if a["ritardo"] else ""))
    if p["abitudini"]:
        righe.append("✅ Abitudini: " + " · ".join(f"{h['emoji']} {h['nome']} {'✓' if h['fatta_oggi'] else '—'}" for h in p["abitudini"][:5]))
    righe.append(f"🍅 Concentrazione: {p['focus']['pomodori']} pomodor{'o' if p['focus']['pomodori'] == 1 else 'i'} ({p['focus']['minuti']} min)")
    s = p["spese"]
    righe.append(f"💶 Spese: oggi {euro(s['oggi'])}, questo mese {euro(s['mese'])}" + (f" ({s['perc']}% del budget)" if s["perc"] is not None else ""))
    ag = [x for x in p["agenda"] if x["giorno"] == "oggi" and not x["passato"]]
    if ag:
        righe.append("📅 Ancora oggi: " + ", ".join(f"{x['ora']} {x['titolo']}" for x in ag[:3]))
    if p.get("obiettivi"):
        righe.append("🎯 Obiettivi: " + " · ".join(f"{o['emoji']} {o['titolo']} {o['perc']}%" for o in p["obiettivi"][:3]))
    if p["automazioni"]:
        x = p["automazioni"][0]
        righe.append(f"⚙️ Prossima automazione: «{x['comando']}» {fmt_quando(datetime.datetime.fromisoformat(x['prossima']))}")
    return "\n".join(righe)


def prime_router(testo, memoria):
    if not _RE_PRIME.match(re.sub(r"\s+", " ", (testo or "").strip()).rstrip(" ?!.")):
        return None
    p = prime_oggi(memoria)
    return {"testo": prime_testo(p), "prime": p}


