class FiltroTag:
    """Avvolge on_token: lascia passare il testo e trattiene i tag [[azione:…]] (anche spezzati tra chunk)."""

    def __init__(self, on_token):
        self.out, self.buf = on_token, ""

    PAROLE = ("azione", "action", "tool", "strumento")

    def __call__(self, chunk):
        self.buf += chunk
        while self.buf:
            i = self.buf.find("[[")
            if i < 0:
                tieni = 1 if self.buf.endswith("[") else 0          # forse è l'inizio di "[["
                if len(self.buf) > tieni:
                    self.out(self.buf[:len(self.buf) - tieni])
                self.buf = self.buf[len(self.buf) - tieni:]
                return
            if i:
                self.out(self.buf[:i])
                self.buf = self.buf[i:]
            testa = self.buf[2:].lstrip()[:12].lower()
            if not any(testa.startswith(p) for p in self.PAROLE):
                if any(p.startswith(testa) for p in self.PAROLE) and len(self.buf) < 40:
                    return                                          # ancora non si capisce: aspetta
                self.out(self.buf[:2])                              # non è un tag: mostralo
                self.buf = self.buf[2:]
                continue
            j = self.buf.find("]]")
            if j < 0:
                if len(self.buf) > 1500:                            # tag mai chiuso: lascia perdere
                    self.buf = ""
                return
            self.buf = self.buf[j + 2:]

    def fine(self):
        if self.buf and not _RE_TAG_APERTO.match(self.buf):
            self.out(self.buf)
        self.buf = ""


class Agente:

    @staticmethod
    def estrai(testo):
        """Ritorna (testo senza tag, [richieste]). Tollera JSON con apici singoli e tag lasciati aperti."""
        richieste, viste = [], set()
        corpi = [m.group(1) for m in _RE_TAG.finditer(testo)]
        aperto = _RE_TAG_APERTO.search(_RE_TAG.sub("", testo))
        if aperto:
            m = re.search(r"\{.*\}", aperto.group(0), re.S)
            if m:
                corpi.append(m.group(0))
        for corpo in corpi:
            a = None
            for prova in (corpo, corpo.replace("'", '"')):
                try:
                    a = json.loads(prova)
                    break
                except Exception:
                    continue
            if isinstance(a, dict) and isinstance(a.get("tipo"), str):
                chiave = json.dumps(a, sort_keys=True, ensure_ascii=False)
                if chiave not in viste:
                    viste.add(chiave)
                    richieste.append(a)
        pulito = _RE_TAG_APERTO.sub("", _RE_TAG.sub("", testo))
        pulito = re.sub(r"[ \t]+\n", "\n", pulito)
        pulito = re.sub(r"\n{3,}", "\n\n", pulito).strip()
        return pulito, richieste[:6]

    @staticmethod
    def esegui(a, memoria, n0=1):
        """Esegue una richiesta dopo averla controllata. Ritorna {tipo, ok, icona, esito, [dati], [fonti], [fonti_web]}.
        n0 = da che numero partono le fonti web (se in una risposta si cerca più volte)."""
        tipo = str(a.get("tipo", "")).strip().lower().replace("-", "_")
        tipo = {"reminder": "promemoria", "spesa": "lista", "calcolo": "calcola", "calc": "calcola",
                "documenti": "cerca_documenti", "memoria": "cerca_memoria", "orario": "ora",
                "sito": "apri_sito", "apri": "apri_sito", "url": "apri_sito", "app": "apri_app", "cartella": "apri_cartella",
                "cerca": "cerca_web", "google": "cerca_web", "pc": "info_pc", "stato_pc": "info_pc",
                "volume": "imposta_volume", "musica": "controlla_musica", "media": "controlla_musica",
                "schermata": "screenshot", "file": "apri_file", "trova_file": "cerca_file", "digita": "scrivi_testo",
                "scrivi": "scrivi_testo", "blocca": "blocca_pc", "routine": "esegui_routine", "modalita": "esegui_routine",
                "modalità": "esegui_routine", "internet": "cerca_internet", "ricerca_web": "cerca_internet", "web": "cerca_internet",
                "cerca_online": "cerca_internet", "ricerca": "cerca_internet", "news": "notizie", "giornale": "notizie",
                "pagina": "leggi_pagina", "apri_pagina": "leggi_pagina", "link": "leggi_pagina", "agenda": "calendario", "impegni": "calendario",
                "evento": "aggiungi_evento", "appuntamento": "aggiungi_evento",
                "spesa": "aggiungi_spesa", "segna_spesa": "aggiungi_spesa", "budget": "spese", "soldi": "spese", "abitudine": "abitudini", "obiettivi": "abitudini",
                "todo": "attivita", "cose_da_fare": "attivita", "compito": "aggiungi_attivita", "nuova_attivita": "aggiungi_attivita", "aggiungi_todo": "aggiungi_attivita",
                "chat": "cerca_chat", "conversazioni": "cerca_chat", "cerca_conversazioni": "cerca_chat", "chiacchierate": "cerca_chat", "ricordi": "cerca_chat",
                "automatizza": "automazione", "programma": "automazione", "crea_automazione": "automazione",
                "obiettivo_grande": "obiettivo_tappe", "traguardo": "obiettivo_tappe", "progetto": "obiettivo_tappe"}.get(tipo, tipo)
        s = lambda k, n=200: re.sub(r"\s+", " ", str(a.get(k) or "")).strip()[:n]
        r = {"tipo": tipo, "ok": False, "icona": ICONE_STRUMENTI.get(tipo, "🔧"), "esito": ""}
        try:
            if tipo == "promemoria":
                testo, qt = s("testo", 120) or s("cosa", 120), s("quando", 60)
                if len(testo) < 2:
                    return dict(r, esito="promemoria senza testo")
                quando = None
                if qt:
                    quando, _ = parse_quando(qt)
                    if not quando and re.fullmatch(r"\d{1,2}(?:[:.]\d{2})?", qt):
                        quando, _ = parse_quando("alle " + qt)
                q_iso = quando.isoformat(timespec="seconds") if quando else None
                poco_fa = (datetime.datetime.now() - datetime.timedelta(minutes=10)).isoformat(timespec="seconds")
                if any(p["testo"].lower() == testo.lower() and (p.get("quando") == q_iso or p.get("creato", "") >= poco_fa)
                       for p in memoria.promemoria_attivi()):
                    return dict(r, ok=True, esito=f"«{testo}» era già impostato")
                memoria.aggiungi_promemoria(testo, quando, "promemoria")
                return dict(r, ok=True, esito=f"«{testo}» " + (fmt_quando(quando) if quando else "(senza orario)"))
            if tipo == "timer":
                sec = parse_durata(s("durata", 40))
                if not sec and isinstance(a.get("secondi"), (int, float)):
                    sec = int(a["secondi"])
                if not 0 < sec <= 2 * 86400:
                    return dict(r, esito="durata del timer non valida")
                quando = datetime.datetime.now() + datetime.timedelta(seconds=sec)
                memoria.aggiungi_promemoria(f"Timer di {fmt_durata(sec)}", quando, "timer")
                return dict(r, ok=True, esito=f"timer di {fmt_durata(sec)} (suona alle {quando.strftime('%H:%M:%S')})")
            if tipo == "lista":
                agg = a.get("aggiungi", a.get("voci", a.get("voce")))
                agg = [agg] if isinstance(agg, str) else (agg if isinstance(agg, list) else [])
                agg = [re.sub(r"\s+", " ", str(v)).strip()[:80] for v in agg[:12] if str(v).strip()]
                togli = a.get("togli", a.get("rimuovi"))
                togli = [togli] if isinstance(togli, str) else (togli if isinstance(togli, list) else [])
                fatto = []
                if agg:
                    nuove = memoria.lista_aggiungi(agg)
                    fatto.append("aggiunto " + ", ".join(nuove) if nuove else "era già tutto in lista")
                for v in togli[:6]:
                    if memoria.lista_rimuovi(str(v)):
                        fatto.append(f"tolto {v}")
                if not fatto:
                    return dict(r, esito="niente da cambiare nella lista")
                return dict(r, ok=True, esito="; ".join(fatto))
            if tipo == "nota":
                testo = s("testo", 300)
                if len(testo) < 2:
                    return dict(r, esito="nota vuota")
                if not any(x.get("cosa", "").lower() == testo.lower() for x in memoria.imparato[-50:]):
                    memoria.impara_cosa(testo, "nota")
                return dict(r, ok=True, esito=f"annotato «{testo[:60]}»")
            if tipo == "obiettivo":
                testo = s("testo", 120)
                if len(testo) < 3:
                    return dict(r, esito="obiettivo vuoto")
                memoria.aggiungi_obiettivo(testo, "obiettivo")
                return dict(r, ok=True, esito=f"nuovo obiettivo: {testo}")
            if tipo == "personalita":
                k = s("chiave", 20).lower() or s("modalita", 20).lower()
                k = "prof" if k.startswith("prof") else k
                if not imposta_personalita(k, memoria):
                    return dict(r, esito=f"personalità «{k}» sconosciuta")
                return dict(r, ok=True, esito=f"modalità {PERSONALITA[k][1]}")
            if tipo == "meteo":
                citta = s("citta", 40) or s("città", 40) or memoria.get_valore_profilo("citta") or "Roma"
                d = ottieni_meteo(citta, timeout=6)
                if d.get("errore"):
                    return dict(r, esito=f"meteo di {citta} non disponibile", dati=f"meteo di {citta}: non disponibile (offline?)")
                prev = "; ".join(f"{p['giorno']}: {p['min']}°/{p['max']}° {p['emoji']}"
                                 for p in (d.get("previsioni") or [])[:3])
                dati = (f"meteo a {d['citta']} adesso: {d['temp']}°C, {d['descrizione'].lower()}, percepiti {d['percepita']}°, "
                        f"umidità {d['umidita']}%, vento {d['vento']} km/h. Prossimi giorni: {prev}")
                return dict(r, ok=True, esito=f"{d['citta']} {d['temp']}°C {d['emoji']}", dati=dati)
            if tipo == "ora":
                citta = s("citta", 40) or s("città", 40)
                k = trova_citta(citta) if citta else None
                if citta and not k:
                    d = datetime.datetime.now()
                    return dict(r, esito=f"fuso di {citta} sconosciuto",
                                dati=f"fuso orario di {citta} sconosciuto; qui sono le {d.strftime('%H:%M')}")
                d = ora_in(k) if k else datetime.datetime.now()
                dove = k.title() if k else "qui"
                return dict(r, ok=True, esito=f"{dove} {d.strftime('%H:%M')}",
                            dati=f"ora a {dove}: {d.strftime('%H:%M')} di {GIORNI_LUNGHI[d.weekday()]} {d.day} {MESI_IT[d.month-1]}")
            if tipo == "calcola":
                espr = s("espressione", 120) or s("expr", 120)
                v = calcola(espr)
                if v is None:
                    return dict(r, esito="calcolo non valido", dati=f"«{espr}» non è un calcolo valido")
                return dict(r, ok=True, esito=f"{espr} = {fmt_num(v)}", dati=f"{espr} = {fmt_num(v)}")
            if tipo == "cerca_documenti":
                q = s("q", 120) or s("query", 120)
                trovati = memoria.cerca_documenti(q, k=4, rigida=False)
                if not trovati:
                    return dict(r, ok=True, esito=f"«{q}»: niente nei documenti", dati=f"nei documenti non c'è niente su «{q}»")
                dati = "\n".join(f"[{x['nome']} · parte {x['pezzo']}] {x['testo'][:900]}" for x in trovati)
                return dict(r, ok=True, esito=f"«{q}»: {len(trovati)} risultati", dati=dati,
                            fonti=[{"nome": x["nome"], "pezzo": x["pezzo"], "anteprima": x["testo"][:200]} for x in trovati])
            if tipo == "cerca_chat":                       # v18: le chiacchierate passate (per significato o per parole)
                q = s("q", 120) or s("query", 120)
                trovati = RICORDI.cerca(memoria, q, k=4, rigida=False) if q else []
                if not trovati:
                    return dict(r, ok=True, esito=f"«{q}»: niente nelle chiacchierate", dati=f"nelle chiacchierate passate non c'è niente su «{q}»")
                dati = "\n".join(f"[{Ricordi._data(x)}] la persona: «{_testo_breve(x['tu'], 300)}» — tu: «{_testo_breve(x['ai'], 200)}»" for x in trovati)
                return dict(r, ok=True, esito=f"«{q}»: {len(trovati)} chiacchierat{'a' if len(trovati) == 1 else 'e'}", dati=dati)
            if tipo == "cerca_memoria":
                q = s("q", 80) or s("query", 80)
                trovati = memoria.cerca(q)
                if not trovati:
                    for w in sorted(_token(q), key=len, reverse=True)[:3]:   # riprova parola per parola
                        trovati = memoria.cerca(w)
                        if trovati:
                            break
                righe = []
                for x in trovati[:8]:
                    righe.append(" · ".join(str(v)[:120] for k, v in x.items() if k != "tipo"))
                return dict(r, ok=True, esito=f"«{q}»: {len(trovati)} ricordi",
                            dati=("\n".join(righe) if righe else f"nessun ricordo su «{q}»"))
            if tipo in ("cerca_internet", "notizie") and not CONFIG["web"]:
                return dict(r, esito="internet è spento (MAIK_WEB=0)", dati="niente internet: rispondi con quello che sai e dillo")
            if tipo == "cerca_internet":                # v14: legge le pagine e le passa numerate
                q = s("q", 150) or s("domanda", 150) or s("query", 150)
                x = WEB.ricerca(q)
                if not x["ok"]:
                    return dict(r, esito=f"«{q}»: internet non risponde", dati=f"ricerca «{q}» non riuscita ({x.get('errore', '')[:80]}): rispondi con quello che sai e dillo")
                fw = [{"n": f["n"] + n0 - 1, "titolo": f["titolo"], "url": f["url"], "sito": f["sito"], "estratto": f["estratto"]} for f in x["fonti"]]
                return dict(r, ok=True, esito=f"«{q}»: {len(fw)} fonti", dati=RicercaWeb.dati_per_modello(x, n0), fonti_web=fw)
            if tipo == "notizie":
                cat = _categoria_notizie(s("categoria", 30) or s("argomento", 30) or s("q", 30))
                x = NOTIZIE.prendi(cat, 8)
                if not x["ok"]:
                    return dict(r, esito=f"notizie di {cat} non disponibili", dati="notizie non disponibili (offline?)")
                dati = "\n".join(f"- {n['titolo']}" + (f" ({n['quando']})" if n["quando"] else "") + (f": {n['descrizione']}" if n["descrizione"] else "")
                                 for n in x["notizie"])
                return dict(r, ok=True, esito=f"{len(x['notizie'])} notizie ({cat})", dati=dati, notizie=dict(x, titolo=cat))
            if tipo == "aggiungi_spesa":                # v16: soldi
                try:
                    imp = float(str(a.get("importo", "")).replace("€", "").replace(",", ".").strip())
                except ValueError:
                    return dict(r, esito="importo non valido")
                x, err = SPESE.aggiungi(imp, s("descrizione", 80) or s("cosa", 80), s("categoria", 20) or None)
                return dict(r, ok=bool(x), esito=f"{x['descrizione']} {euro(x['importo'])} → {CAT_SPESE[x['categoria']]['nome']}" + (f" · {x['avviso']}" if x and x.get("avviso") else "") if x else err)
            if tipo == "spese":
                q = (s("periodo", 40) + " " + s("cosa", 40)).strip()
                rr = SPESE.router("quanto ho speso " + q)
                return dict(r, ok=True, esito=f"spese: {q or 'questo mese'}", dati=rr["testo"], spese=rr.get("spese"))
            if tipo == "abitudini":
                rr = ABITUDINI.router("come vanno le mie abitudini")
                return dict(r, ok=True, esito="abitudini", dati=rr["testo"])
            if tipo == "aggiungi_attivita":            # v17: cose da fare
                x, err = ATTIVITA.aggiungi_testo(s("testo", 200) or s("cosa", 200), fonte="agente")
                return dict(r, ok=bool(x), esito=(f"«{x['testo']}»" + (f" · scade {quando_scade(x['scadenza'])}" if x["scadenza"] else "")) if x else err)
            if tipo == "attivita":
                q = s("quando", 30)
                rr = ATTIVITA.elenco_testo("" if q in ("", "tutte", "tutto") else q)
                return dict(r, ok=True, esito=f"cose da fare: {q or 'tutte'}", dati=rr["testo"])
            if tipo == "leggi_pagina":                  # v15: una pagina intera
                if not CONFIG["web"]:
                    return dict(r, esito="internet è spento (MAIK_WEB=0)", dati="niente internet")
                url = s("url", 500)
                x = leggi_pagina(url, 8000)
                if not x["ok"]:
                    return dict(r, esito=f"pagina non leggibile ({x['errore'][:60]})", dati=f"non riesco a leggere {url}: {x['errore']}")
                fw = [{"n": n0, "titolo": x["titolo"], "url": x["url"], "sito": x["sito"], "estratto": x["descrizione"]}]
                return dict(r, ok=True, esito=f"«{x['titolo'][:50]}» ({x['parole']} parole)", dati=f"[{n0}] {x['titolo']} — {x['sito']}\n{x['testo']}", fonti_web=fw)
            if tipo == "calendario":
                q = s("quando", 40) or s("giorno", 40) or "questa settimana"
                rr = CAL.router("cosa ho " + q + " in calendario") or CAL.router("agenda")
                return dict(r, ok=True, esito=f"impegni: {q}", dati=rr["testo"], agenda=rr.get("agenda"))
            if tipo == "aggiungi_evento":
                titolo, qt = s("titolo", 120) or s("testo", 120), s("quando", 60)
                quando = parse_quando(qt)[0] if qt else None
                if not quando:
                    return dict(r, esito="evento senza data")
                e, err = CAL.aggiungi(titolo, quando, int(a.get("durata") or 60) if str(a.get("durata") or "").isdigit() else 60, s("luogo", 120))
                return dict(r, ok=bool(e), esito=f"«{titolo}» {fmt_quando(quando)}" if e else err)
            if tipo in STRUMENTI_PC and getattr(_CTX, "automazione", False):   # v19: un'automazione non tocca mai il PC
                return dict(r, esito="nelle automazioni niente comandi del PC: quelli li confermi sempre tu")
            if tipo == "obiettivo_tappe":                  # v20: un obiettivo grande diviso in tappe
                entro = s("entro", 60) or s("quando", 60)
                titolo, scad = scadenza_obiettivo(s("testo", 160) + (" " + entro if re.match(r"(?:entro|in|tra|fra|per)\b", entro, re.I) else " entro " + entro if entro else ""))
                x, err = OBIETTIVI.crea(titolo, scad, None)
                return dict(r, ok=bool(x), esito=f"{x['emoji']} «{x['titolo']}»: {x['totali']} tappe, entro il {x['scadenza']}" if x else err)
            if tipo == "automazione":                      # v19: «ogni lunedì alle 9 dimmi …»
                q = s("quando", 80)
                m_o = re.search(r"(?:alle|all['’]|verso\s+le)\s*(\d{1,2}(?:[:.]\d{2})?)", q)
                x, err = AUTOMAZIONI.crea(s("cosa", 200) or s("comando", 200), interpreta_quando_auto(q, m_o.group(1) if m_o else ""), "agente")
                return dict(r, ok=bool(x), esito=f"{x['descrizione']}: «{x['comando']}»" if x else err)
            if tipo in STRUMENTI_PC or tipo == "cerca_file":
                if not CONFIG["pc"]:
                    return dict(r, esito="i comandi del PC sono spenti (MAIK_PC=0)")
            if tipo in STRUMENTI_PC:                    # v11-v12: il PC (sempre con conferma)
                x = PC.prepara(STRUMENTI_PC[tipo], a, memoria)
                return dict(r, ok=x["ok"], esito=x["esito"], conferma=x.get("conferma"),
                            **({"schermata": {"immagine": x["immagine"], "analizza": x.get("analizza")}} if x.get("immagine") else {}))
            if tipo == "info_pc":
                d = info_pc()
                return dict(r, ok=True, esito=d["testo"].replace("💻 ", "")[:90], dati=d["testo"])
            if tipo == "cerca_file":
                q = s("q", 100) or s("nome", 100) or s("query", 100)
                trovati = cerca_file(q)
                if not trovati:
                    return dict(r, ok=True, esito=f"«{q}»: nessun file", dati=f"nessun file per «{q}» nelle cartelle personali")
                dati = "\n".join(f"- {f['nome']} ({f['tipo']}, in {f['cartella']}, modificato {f['modificato']}) percorso: {f['percorso']}"
                                 for f in trovati)
                return dict(r, ok=True, esito=f"«{q}»: {len(trovati)} file", dati=dati, file=trovati)
            return dict(r, esito=f"strumento «{tipo}» sconosciuto")
        except ZeroDivisionError:
            return dict(r, esito="divisione per zero", dati="divisione per zero: impossibile")
        except Exception as e:
            return dict(r, esito=f"errore: {e}"[:120])


PROMPT_ESTRAZIONE = """Sei il modulo di memoria di un assistente personale.
Leggi il MESSAGGIO dell'utente ed estrai SOLO informazioni NUOVE, personali e durature su di lui/lei
(nome, età, città, lavoro/studio, gusti, abitudini, persone care con il loro ruolo, obiettivi, eventi importanti).
Ignora saluti, domande generiche, opinioni passeggere e tutto ciò che è già noto.

GIÀ NOTO: {noto}

MESSAGGIO: {messaggio}

Rispondi SOLO con un oggetto JSON con queste chiavi:
{{"profilo": {{"chiave": "valore"}}, "fatti": ["frase breve in terza persona"], "persone": [{{"nome": "...", "ruolo": "..."}}], "obiettivi": ["..."], "eventi": [{{"cosa": "esame di storia", "quando": "domani alle 9", "domanda": "Com'è andato l'esame di storia?"}}]}}
"eventi" = solo cose FUTURE che la persona deve fare o vivere (esami, colloqui, visite, viaggi, partite,
appuntamenti), con "quando" in italiano semplice e la domanda che un amico le farebbe DOPO.
Se non c'è niente di nuovo usa oggetti e liste vuoti."""

_RE_PERSONALE = re.compile(
    r"\b(?:io|mi|mio|mia|miei|mie|ho|sono|sto|vivo|abito|lavoro|studio|voglio|vorrei|amo|adoro|odio|"
    r"piace|piacciono|preferisco|faccio|mamma|pap[aà]|fratello|sorella|ragazz[oa]|moglie|marito|"
    r"figli[oa]?|amic[oa]|cane|gatto|compleanno|nato|nata)\b", re.I)


# ════════════════════════════════════════════════════════════
# MOTORE AI
# ════════════════════════════════════════════════════════════
class MotoreAI:
    def __init__(self):
        self.memoria  = Memoria()
        self.cervello = Cervello()
        self.appreso_log = []                 # cosa ha imparato l'IA (per i toast della GUI)
        self._ia_lock = threading.Lock()      # una sola estrazione alla volta
        p = self.memoria.ricordi.get("personalita")
        if p in PERSONALITA:
            imposta_personalita(p)

    def _system_prompt(self, query="", fonti=None):
        """v22: prima la parte FISSA (carattere e strumenti), poi quella che cambia (ora, memoria, documenti):
        Ollama riusa la parte fissa che ha già letto e la risposta comincia molto prima."""
        ora = datetime.datetime.now()
        oggi = f"{data_it(ora)}, ore {ora.strftime('%H:%M')}"
        documenti, extra = "", ""
        if fonti:
            blocchi = "\n\n".join(f"[{f['nome']} · parte {f['pezzo']}]\n{f['testo']}" for f in fonti)
            documenti = (f"\n\n--- DAI DOCUMENTI DELLA PERSONA (usali solo se c'entrano con la domanda; quando li usi "
                         f"cita la fonte tra parentesi quadre, es. [{fonti[0]['nome']}]) ---\n{blocchi}\n--- FINE DOCUMENTI ---")
        if CONFIG["agente"]:
            nomi = [d.get("nome", "") for d in self.memoria.documenti[-12:]]
            routine = [r["nome"] for r in ROUTINE.elenco()][:12] if CONFIG["pc"] else []
            strumenti = (PROMPT_AGENTE + ("\n" + PROMPT_AGENTE_WEB if CONFIG["web"] else "") + "\n" + PROMPT_AGENTE_V15 + "\n" + PROMPT_AGENTE_V16 + "\n" + PROMPT_AGENTE_V18 + "\n" + PROMPT_AGENTE_V19 + "\n" + PROMPT_AGENTE_V20 + ("\n" + PROMPT_AGENTE_PC if CONFIG["pc"] else "")
)
            extra = ((f"\nDocumenti caricati dalla persona: {', '.join(nomi)}." if nomi else "")
                     + (f"\nRoutine salvate dalla persona: {', '.join(routine)}." if routine else ""))
        else:
            strumenti = ("Le azioni pratiche (timer, promemoria, lista, calcoli, ora nel mondo, briefing) le fai quando "
                         "te le chiedono con frasi come «metti un timer di 10 minuti» o «ricordami alle 18 di…»: "
                         "se te le chiedono in modo vago, suggerisci la frase giusta. "
                         "Non dire mai di aver impostato qualcosa se non è successo davvero.")
        return f"""{carattere_attivo()}

Usa la memoria che trovi più sotto con naturalezza, senza elencarla meccanicamente.
Se noti che la persona è di umore negativo, sii empatico e presente.
Se ha obiettivi o sogni, tienili a mente e incoraggiala.

{strumenti}

--- ADESSO ---
Oggi è {oggi}.{extra}

--- LA TUA MEMORIA DI QUESTA PERSONA ---
{self.memoria.costruisci_contesto(query)}
--- FINE MEMORIA ---{documenti}"""

    def _impara_con_ia(self, testo):
        """Estrazione di fatti con il modello (JSON). Gira in background dopo la risposta."""
        if not CONFIG["apprendimento_ia"] or len(testo.split()) < 4 or not _RE_PERSONALE.search(testo):
            return []
        if not self._ia_lock.acquire(blocking=False):
            return []
        try:
            dati = self.cervello.pensa_json(PROMPT_ESTRAZIONE.format(noto=self.memoria.gia_noto(),
                                                                     messaggio=testo[:800]))
            appreso = self.memoria.impara_da_ia(dati) if dati else []
            for e in ((dati or {}).get("eventi") or [])[:2]:
                s = self._seguito_da_ia(e, testo)
                if s:
                    appreso.append("🔁 " + s["evento"])
            if appreso:
                self.appreso_log.append({"ts": time.time(), "cosa": ", ".join(appreso[:3])})
                self.appreso_log = self.appreso_log[-30:]
            return appreso
        finally:
            self._ia_lock.release()

    def _seguito_da_ia(self, e, fonte):
        """Un evento trovato dal modello: migliora la domanda del follow-up già creato
        dalle regole, oppure ne crea uno nuovo. Ritorna il follow-up nuovo (o None)."""
        if not isinstance(e, dict):
            return None
        pulisci = lambda x, n: re.sub(r"\s+", " ", str(x or "")).strip()[:n]
        cosa, domanda, qt = pulisci(e.get("cosa"), 70), pulisci(e.get("domanda"), 160), pulisci(e.get("quando"), 60)
        if not domanda.endswith("?"):
            domanda = ""
        if any(s.get("fonte") == fonte[:300] for s in self.memoria.seguiti_in_attesa()):
            if domanda:
                self.memoria.aggiorna_seguito_da_fonte(fonte, domanda)
            return None
        if len(cosa) < 3 or not qt:
            return None
        ora = datetime.datetime.now()
        quando, _ = parse_quando(qt, ora)
        if not quando or not (ora < quando < ora + datetime.timedelta(days=15)):
            return None
        chiedi = calcola_chiedi(quando, bool(re.search(r"\d", qt)), ora)
        return self.memoria.aggiungi_seguito(cosa, quando, chiedi, domanda or f"Com'è andata con {cosa}?", fonte)

    def messaggio_seguito(self, s):
        """Il messaggio che Maik manda da solo quando è il momento di chiedere com'è andata."""
        nome = self.memoria.get_valore_profilo("nome")
        apertura = random.choice(["Ehi", "Ciao", "Allora"]) + (f" {nome}" if nome else "")
        domanda = s.get("domanda") or "Com'è andata?"
        return f"{apertura}! 🤞 {domanda} Raccontami tutto!"

    def seguiti_da_chiedere(self, sessione=None):
        """Follow-up arrivati: diventano messaggi di Maik nella chat (e nel diario)."""
        sid = self.memoria.sessione_valida(sessione)
        out = []
        for s in self.memoria.seguiti_scaduti():
            testo = self.messaggio_seguito(s)
            self.memoria.salva_scambio("", testo, sid, extra={"seguito": s["evento"]})
            out.append({"id": s["id"], "evento": s["evento"], "testo": testo})
        return out

    def _dopo_risposta(self, testo):
        for _ in range(240):                                 # v22: aspetto che tu sia in pausa (al massimo 2 minuti)
            if getattr(self, "chat_attive", 0) <= 0 and time.time() - getattr(self, "ultima_chat", 0) > CONFIG.get("pausa_apprendimento", 6):
                break
            time.sleep(0.5)
        self._forse_riassumi()
        self._impara_con_ia(testo)

    def briefing(self, auto=False):
        oggi = datetime.date.today().isoformat()
        if auto and (self.memoria.ricordi.get("ultimo_briefing") == oggi
                     or (not self.memoria.numero_scambi() and not self.memoria.profilo)):
            return None                       # già fatto oggi, o primo incontro
        self.memoria.imposta_ricordo("ultimo_briefing", oggi)
        return Azioni.briefing(self.memoria)

    def _costruisci_messaggi(self, testo, sessione=None):
        messaggi = []
        for s in self.memoria.ultimi_scambi(6, sessione or Memoria.PRINCIPALE):
            if s.get("tu"):                       # i follow-up di Maik non hanno una domanda
                messaggi.append({"role": "user", "content": s["tu"]})
            messaggi.append({"role": "assistant", "content": s["ai"]})
        messaggi.append({"role": "user", "content": testo})
        return messaggi

    def _forse_riassumi(self):
        n = self.memoria.numero_scambi()
        if n > 0 and n % CONFIG["ogni_n_riassumi"] == 0:
            scambi = self.memoria.ultimi_scambi(CONFIG["ogni_n_riassumi"])
            testo  = "\n".join(f"Persona: {s['tu']}\n{CONFIG['nome_ai']}: {s['ai']}" for s in scambi)
            vecchio = self.memoria.ricordi.get("riassunto", "")
            prompt = (f"Riassunto attuale:\n{vecchio or '(niente)'}\n\n"
                      f"Ultime chiacchierate:\n{testo}\n\n"
                      "Scrivi un riassunto aggiornato e breve (max 10 righe) di chi è la persona, "
                      "includendo umore prevalente, obiettivi, relazioni importanti. "
                      "In italiano, terza persona. Solo il riassunto.")
            nuovo = pulisci_pensiero(self.cervello.pensa("Riassumi.", [{"role": "user", "content": prompt}]))
            if nuovo and not nuovo.startswith("__ERRORE"):
                self.memoria.aggiorna_ricordi(nuovo)

    def _gestisci_comando(self, testo):
        tl = testo.strip().lower()
        if tl.startswith("__meteo__"):
            citta = testo[9:].strip() or self.memoria.get_valore_profilo("citta") or "Roma"
            return {"tipo": "meteo", "dati": ottieni_meteo(citta),
                    "giorni": self.memoria.ricordi.get("giorni_insieme", 1),
                    "scambi": self.memoria.numero_scambi()}
        if tl in ("__memoria__", "cosa sai di me?", "cosa sai di me"):
            return {"tipo": "memoria", "dati": self.memoria.statistiche(),
                    "giorni": self.memoria.ricordi.get("giorni_insieme", 1),
                    "scambi": self.memoria.numero_scambi()}
        if tl.startswith("__cerca__"):
            query = testo[9:].strip()
            return {"tipo": "cerca", "query": query, "risultati": self.memoria.cerca(query),
                    "giorni": self.memoria.ricordi.get("giorni_insieme", 1),
                    "scambi": self.memoria.numero_scambi()}
        if tl == "__timeline__":
            return {"tipo": "timeline", "eventi": self.memoria.timeline(),
                    "giorni": self.memoria.ricordi.get("giorni_insieme", 1),
                    "scambi": self.memoria.numero_scambi()}
        if tl == "__esporta__":
            return {"tipo": "esporta", "dati": self.memoria.esporta()}
        return None

    def _meta(self, **extra):
        return dict(giorni=self.memoria.ricordi.get("giorni_insieme", 1),
                    scambi=self.memoria.numero_scambi(), **extra)

    def rispondi(self, testo):
        """Risposta classica (completa). Mantenuta per compatibilità."""
        cmd = self._gestisci_comando(testo)
        if cmd:
            return cmd
        pc = (ROUTINE.router(testo, self.memoria) or PC.router(testo, self.memoria)) if CONFIG["pc"] and not getattr(_CTX, "automazione", False) else None
        if pc:
            self.memoria.salva_scambio(testo, pc["testo"])
            return self._meta(ok=True, risposta=pc["testo"], azione=True, **self._meta_pc(pc))
        att = ATTIVITA.router(testo)
        if att:
            self.memoria.salva_scambio(testo, att["testo"])
            return self._meta(ok=True, risposta=att["testo"], azione=True, **{k: att[k] for k in ("spesa", "spese", "budget", "abitudine", "abitudini", "settimana", "evento", "attivita", "attivita_lista", "piano", "giornata", "focus", "idee", "ricordi", "automazione", "automazioni", "prime", "agenda", "notizie", "fonti_web", "obiettivo", "obiettivi", "obiettivo_eventi", "piano_settimana", "tendenze", "multiverso", "tv", "invenzione", "invenzioni", "aiutanti", "webcam", "prestazioni", "presenza", "annulla", "annullabili", "diagnosi", "backup", "backup_ripristina", "radio", "storie", "mente", "studio", "quiz", "suoni", "ricetta", "menu", "cucina", "tutor", "respiro", "situazione", "hud", "piano_azione", "piano_fatto", "analisi", "previsione", "simulazione", "anno") if att.get(k)})
        cal = CAL.router(testo)
        if cal:
            self.memoria.salva_scambio(testo, cal["testo"])
            return self._meta(ok=True, risposta=cal["testo"], azione=True, **{k: cal[k] for k in ("agenda", "evento") if cal.get(k)})
        v16 = SPESE.router(testo) or ABITUDINI.router(testo) or ATTIVITA.router_fatto(testo) or (riepilogo_settimana(self.memoria) if _RE_SETTIMANA.match(testo.strip().rstrip(" ?!.")) else None) \
            or PROATTIVO.router(testo, self.memoria) or RICORDI.router(testo, self.memoria) or prime_router(testo, self.memoria) \
            or OBIETTIVI.router(testo, self.cervello, self.memoria) or tendenze_router(testo, self.memoria) or (pianifica_settimana() if _RE_SETT_PIANO.match(testo.strip().rstrip(" ?!.")) else None) \
            or (AUTOMAZIONI.router(testo, self) if not getattr(_CTX, "automazione", False) else None)
        if v16:
            self.memoria.salva_scambio(testo, v16["testo"])
            return self._meta(ok=True, risposta=v16["testo"], azione=True, **{k: v16[k] for k in ("spesa", "spese", "budget", "abitudine", "abitudini", "settimana", "evento", "attivita", "attivita_lista", "piano", "giornata", "focus", "idee", "ricordi", "automazione", "automazioni", "prime", "agenda", "notizie", "fonti_web", "obiettivo", "obiettivi", "obiettivo_eventi", "piano_settimana", "tendenze", "multiverso", "tv", "invenzione", "invenzioni", "aiutanti", "webcam", "prestazioni", "presenza", "annulla", "annullabili", "diagnosi", "backup", "backup_ripristina", "radio", "storie", "mente", "studio", "quiz", "suoni", "ricetta", "menu", "cucina", "tutor", "respiro", "situazione", "hud", "piano_azione", "piano_fatto", "analisi", "previsione", "simulazione", "anno") if v16.get(k)})
        nz = NOTIZIE.router(testo)
        if nz:
            self.memoria.salva_scambio(testo, nz["testo"])
            return self._meta(ok=True, risposta=nz["testo"], azione=True, notizie=nz["notizie"])
        azione = None if self._lascia_all_agente(testo) else Azioni.prova(testo, self.memoria)
        if azione:
            self.memoria.salva_scambio(testo, azione)
            return self._meta(ok=True, risposta=azione, azione=True)
        imparato = Estrattore.analizza(testo, self.memoria)
        risposta = self.cervello.pensa(self._system_prompt(testo), self._costruisci_messaggi(testo))
        if risposta.startswith("__ERRORE"):
            return {"ok": False, "risposta": "Ollama non risponde. Controlla che sia acceso."}
        azioni = []
        if CONFIG["agente"]:
            risposta, richieste = Agente.estrai(risposta)
            azioni = [Agente.esegui(a, self.memoria) for a in richieste if a.get("tipo") not in STRUMENTI_INFO]
        self.memoria.salva_scambio(testo, pulisci_pensiero(risposta) or risposta)
        threading.Thread(target=self._dopo_risposta, args=(testo,), daemon=True).start()
        return self._meta(ok=True, risposta=risposta, imparato=imparato, azioni=azioni)

    @staticmethod
    def _meta_pc(pc):
        """Per la GUI: schede di conferma, file trovati (con «apri»), screenshot già fatti."""
        return {"conferme": [pc["conferma"]] if pc.get("conferma") else [], "file": pc.get("file") or [],
                "schermate": [pc["schermata"]] if pc.get("schermata") else [], **({"routine": pc["routine"]} if pc.get("routine") else {})}

    def _lascia_all_agente(self, testo):
        return CONFIG["agente"] and multi_intento(testo) and self.cervello.disponibile()

    def _nota_seguito(self, testo):
        """Regole veloci: se racconti un evento futuro, Maik si segna di chiederti com'è andata."""
        ev = rileva_evento(testo)
        if not ev:
            return None
        s = self.memoria.aggiungi_seguito(ev["evento"], ev["quando"], ev["chiedi"], ev["domanda"], testo)
        return {"evento": s["evento"], "quando": fmt_quando(ev["quando"]), "chiedi": s["chiedi"]}

    def rispondi_stream(self, testo, on_token, allegato=None, rigenera=False, sessione=None, on_evento=None, accurato=False):
        """v23: prima capisco i refusi e «pensaci bene: …», poi rispondo (e mi segno cosa cambio, per «annulla»)."""
        tu = tutor_intercetta(self, testo, on_token, allegato, sessione, rigenera, on_evento)   # v26: 🗣️ in conversazione con il tutor
        if tu is not None:
            return tu
        pr = professore_intercetta(self, testo, on_token, allegato, sessione, on_evento)      # v29: 🧪 il Professor Flux
        if pr is not None:
            return pr if pr.get("done") else professore_risponde(self, pr, on_token, allegato, rigenera, sessione, on_evento, accurato)
        return rispondi_v23(self, self._rispondi_stream_v22, testo, on_token, allegato, rigenera, sessione, on_evento, accurato)

    def _rispondi_stream_v22(self, testo, on_token, allegato=None, rigenera=False, sessione=None, on_evento=None):
        """Versione in streaming: chiama on_token(chunk) e ritorna i metadati finali.
        allegato = {"nome", "contenuto"}: un file di testo che va al modello ma NON alle azioni/estrattori.
        rigenera = True: rifà l'ultima risposta (toglie lo scambio precedente dal diario).
        sessione = la chat (v10). on_evento(dict) = avvisi in diretta (es. strumento usato dall'agente)."""
        sid = self.memoria.sessione_valida(sessione)
        avvisa = on_evento or (lambda e: None)
        if rigenera:
            self.memoria.rimuovi_ultimo_scambio(testo, sid)
        if allegato and testo and _RE_DOC_SPESA.search(testo):   # v16: «aggiungi questa bolletta alle spese» (PDF/foto già letti)
            nome = str(allegato.get("nome") or "file")[:80]
            r = SPESE.registra_documento(str(allegato.get("contenuto") or ""), nome, bool(re.search(r"scontrin|ricevut", testo, re.I)), self.cervello)
            on_token(r["testo"])
            self.memoria.salva_scambio(testo + f" [📎 {nome}]", r["testo"], sid)
            return self._meta(done=True, ok=True, azione=True, sessione=sid, **{k: r[k] for k in ("spesa", "evento") if r.get(k)})
        if allegato and testo:                                   # v25: 🧠 «fammi le carte da questo file»
            cd = carte_da_allegato(testo, allegato, self)
            if cd:
                on_token(cd["testo"])
                self.memoria.salva_scambio(testo + f" [📎 {str(allegato.get('nome') or 'file')[:80]}]", cd["testo"], sid)
                return self._meta(done=True, ok=True, azione=True, sessione=sid, **({"studio": cd["studio"]} if cd.get("studio") else {}))
        ricordi_dom = ric_q = None
        if not allegato:
            cmd = self._gestisci_comando(testo)
            if cmd:
                return {"done": True, "comando": cmd}
            v23 = v23_router(testo, self)                            # v23: ↩ annulla · 🩺 funziona tutto? · 💾 backup
            if v23:
                on_token(v23["testo"])
                self.memoria.salva_scambio(testo, v23["testo"], sid)
                return self._meta(done=True, ok=True, azione=True, sessione=sid, **{k: v23[k] for k in ("spesa", "spese", "budget", "abitudine", "abitudini", "settimana", "evento", "attivita", "attivita_lista", "piano", "giornata", "focus", "idee", "ricordi", "automazione", "automazioni", "prime", "agenda", "notizie", "fonti_web", "obiettivo", "obiettivi", "obiettivo_eventi", "piano_settimana", "tendenze", "multiverso", "tv", "invenzione", "invenzioni", "aiutanti", "webcam", "prestazioni", "presenza", "annulla", "annullabili", "diagnosi", "backup", "backup_ripristina", "radio", "storie", "mente", "studio", "quiz", "suoni", "ricetta", "menu", "cucina", "tutor", "respiro", "situazione", "hud", "piano_azione", "piano_fatto", "analisi", "previsione", "simulazione", "anno") if v23.get(k)})
            v24 = v24_router(testo, self, avvisa)                    # v24: 📻 radio maik · 🎞️ storie · 🧠 mappa della mente
            if v24:
                on_token(v24["testo"])
                self.memoria.salva_scambio(testo, v24["testo"], sid)
                return self._meta(done=True, ok=True, azione=True, sessione=sid, **{k: v24[k] for k in ("spesa", "spese", "budget", "abitudine", "abitudini", "settimana", "evento", "attivita", "attivita_lista", "piano", "giornata", "focus", "idee", "ricordi", "automazione", "automazioni", "prime", "agenda", "notizie", "fonti_web", "obiettivo", "obiettivi", "obiettivo_eventi", "piano_settimana", "tendenze", "multiverso", "tv", "invenzione", "invenzioni", "aiutanti", "webcam", "prestazioni", "presenza", "annulla", "annullabili", "diagnosi", "backup", "backup_ripristina", "radio", "storie", "mente", "studio", "quiz", "suoni", "ricetta", "menu", "cucina", "tutor", "respiro", "situazione", "hud", "piano_azione", "piano_fatto", "analisi", "previsione", "simulazione", "anno") if v24.get(k)})
            v27 = v27_router(testo, self, avvisa, sid)               # v27: 🛰️ hud · 🧠 situazione · ⚡ piano d'azione
