# SERVER WEB
# ════════════════════════════════════════════════════════════
MOTORE = MotoreAI()

def _parse_qs(path):
    if "?" in path:
        return dict(urllib.parse.parse_qsl(path.split("?", 1)[1]))
    return {}

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass  # silenzio

    # ── helper risposte ─────────────────────────────────────
    def _json(self, dati, code=200):
        body = json.dumps(dati, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(body)

    def _html_body(self, body, code=200):
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _invia(self, corpo, tipo, cache=None):
        if isinstance(corpo, str):
            corpo = corpo.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", tipo)
        self.send_header("Content-Length", str(len(corpo)))
        if cache:
            self.send_header("Cache-Control", cache)
        self.end_headers()
        self.wfile.write(corpo)

    def _richiesta_locale(self):
        """Comandi del PC e avatar: solo dalla GUI di questo computer. Blocca altri siti (Origin),
        DNS rebinding (Host) e altri dispositivi in rete (a meno di MAIK_PC_REMOTO=1)."""
        host = self.headers.get("Host", "")
        origine = self.headers.get("Origin")
        if origine is not None and origine != f"http://{host}":
            return False
        if CONFIG["pc_remoto"]:
            return True
        nome_host = host.rsplit(":", 1)[0] if not host.startswith("[") else host.split("]")[0] + "]"
        ip = self.client_address[0]
        return nome_host in ("localhost", "127.0.0.1", "[::1]") and (ip.startswith("127.") or ip in ("::1", "::ffff:127.0.0.1"))

    def _servi_file(self, percorso, tipo, cache="public, max-age=604800"):
        dim = os.path.getsize(percorso)
        self.send_response(200)
        self.send_header("Content-Type", tipo)
        self.send_header("Content-Length", str(dim))
        self.send_header("Cache-Control", cache)
        self.end_headers()
        with open(percorso, "rb") as f:
            shutil.copyfileobj(f, self.wfile, 256 * 1024)

    def _servi_gui(self):
        # Preferisci aria.html (la tua GUI completa); altrimenti usa quella integrata.
        if os.path.exists(HTML_FILE):
            try:
                with open(HTML_FILE, "rb") as f:
                    self._html_body(f.read())
                    return
            except Exception:
                pass
        self._html_body(GUI_FALLBACK)

    def _read_json_body(self):
        lung = int(self.headers.get("Content-Length", 0))
        if lung <= 0 or lung > 12_000_000:        # niente corpi giganti
            return {}
        try:
            return json.loads(self.rfile.read(lung).decode("utf-8"))
        except Exception:
            return {}

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    # ── GET ─────────────────────────────────────────────────
    def do_GET(self):
        base = self.path.split("?")[0]
        qs   = _parse_qs(self.path)
        try:
            if base in ("/", "/index.html", "/aria.html"):
                self._servi_gui()
            elif base == "/stato":
                self._json(MOTORE.stato())
            elif base == "/salute":
                self._json({"ok": True, "online": MOTORE.cervello.disponibile(),
                            "modello": CONFIG["modello"], "nome": CONFIG["nome_ai"]})
            elif base == "/config":
                self._json({"nome": CONFIG["nome_ai"], "modello": CONFIG["modello"],
                            "modello_visione": CONFIG["modello_visione"],
                            "modelli": MOTORE.cervello.modelli(), "carattere": CONFIG["carattere"],
                            "ollama": CONFIG["ollama_base"],
                            "apprendimento_ia": CONFIG["apprendimento_ia"],
                            "personalita": CONFIG["personalita"],
                            "personalita_disponibili": [{"chiave": k, "emoji": v[0], "nome": v[1]}
                                                        for k, v in PERSONALITA.items()]})
            elif base == "/promemoria":
                self._json({"promemoria": MOTORE.memoria.promemoria_attivi()})
            elif base == "/promemoria/scaduti":
                self._json({"scaduti": MOTORE.memoria.promemoria_scaduti()})
            elif base == "/lista":
                self._json({"lista": MOTORE.memoria.lista})
            elif base == "/briefing":
                self._json({"testo": MOTORE.briefing(auto=qs.get("auto") == "1")})
            elif base == "/appreso":
                try:
                    dopo = float(qs.get("dopo", "0"))
                except ValueError:
                    dopo = 0.0
                self._json({"appreso": [x for x in MOTORE.appreso_log if x["ts"] > dopo], "ora": time.time()})
            elif base == "/meteo":
                self._json(ottieni_meteo(qs.get("citta", "Roma")))
            elif base == "/statistiche":
                self._json(MOTORE.memoria.statistiche())
            elif base == "/esporta":
                self._json(MOTORE.memoria.esporta())
            elif base == "/timeline":
                self._json({"eventi": MOTORE.memoria.timeline()})
            elif base == "/cerca":
                q = qs.get("q", "").strip()
                self._json({"risultati": MOTORE.memoria.cerca(q) if q else []})
            # ── v10: conversazioni, documenti, follow-up ──
            elif base == "/sessioni":
                self._json({"sessioni": MOTORE.memoria.sessioni_elenco()})
            elif base == "/sessioni/storia":
                sid = MOTORE.memoria.sessione_valida(qs.get("id", ""))
                self._json({"sessione": sid, "scambi": MOTORE.memoria.storia_sessione(sid)})
            elif base == "/documenti":
                docs = MOTORE.memoria.documenti_elenco()
                VETTORI.pronta()
                self._json({"documenti": docs, "caratteri": sum(d["caratteri"] for d in docs),
                            "limite": Memoria.MAX_DOC_TOTALE, "semantica": VETTORI.info(MOTORE.memoria)})
            elif base == "/spese":                                    # v16: le spese di un periodo (di default il mese)
                oggi = datetime.date.today()
                try:
                    if qs.get("mese"):
                        da = datetime.date.fromisoformat(qs["mese"][:7] + "-01")
                        a = (da.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - datetime.timedelta(days=1)
                    else:
                        da = datetime.date.fromisoformat(qs["da"]) if qs.get("da") else oggi.replace(day=1)
                        a = datetime.date.fromisoformat(qs["a"]) if qs.get("a") else oggi
                except ValueError:
                    da, a = oggi.replace(day=1), oggi
                r = SPESE.riepilogo(da, a)
                self._json(dict(r, ok=True, budget_impostati=SPESE.budget(), categorie=[CAT_SPESE[k] for k, *_ in CATEGORIE_SPESE]))
            elif base == "/abitudini":
                self._json({"ok": True, "abitudini": ABITUDINI.tutte_stato()})
            elif base == "/attivita":                                 # v17: cose da fare (oggi, domani, settimana, tutte, fatte)
                f = qs.get("filtro", "tutte")
                self._json({"ok": True, "attivita": ATTIVITA.vista(f if f in ("oggi", "domani", "settimana", "ritardo", "fatte") else "tutte"),
                            "conta": {k: len(ATTIVITA.vista(k)) for k in ("oggi", "tutte", "ritardo")}})
            elif base == "/focus":
                oggi = datetime.date.today()
                self._json({"ok": True, "oggi": ATTIVITA.statistiche(oggi, oggi), "settimana": ATTIVITA.statistiche(oggi - datetime.timedelta(days=oggi.weekday()), oggi)})
            elif base == "/piano":
                self._json(dict(pianifica_giornata(), ok=True))
            elif base == "/giornata":
                self._json(dict(fine_giornata(), ok=True))
            elif base == "/automazioni":                              # v19: ⚙️ le automazioni e gli ultimi risultati
                self._json({"ok": True, "automazioni": AUTOMAZIONI.elenco(), "esiti": AUTOMAZIONI.esiti(int(qs.get("n", "20") or 20))})
            elif base == "/automazioni/avvisi":
                self._json({"avvisi": AUTOMAZIONI.prendi_avvisi()})
            elif base == "/professore":                               # v29: 🧪 il Professore c'è (in questa chat)?
                self._json(dict(stato_professore(MOTORE.memoria.sessione_valida(qs.get("sessione"))), ok=True))
            elif base == "/previsione":                               # v28: 🔮 come finisce il mese (spese)
                p = previsione_spese()
                self._json(dict(p, ok=True) if p else {"ok": True, "vuoto": True})
            elif base == "/anno":                                     # v28: 🗓️ il tuo anno, un quadratino per giorno
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                self._json(dict(anno_v28(MOTORE.memoria, (q.get("metrica") or ["attivita"])[0]), ok=True))
            elif base == "/hud":                                      # v27: 🛰️ tutto quello che mostra l'interfaccia olografica
                self._json(dict(stato_hud(MOTORE.memoria), ok=True))
            elif base == "/situazione":                               # v27: 🧠 le allerte in ordine di priorità
                self._json({"ok": True, "allerte": analizza_situazione(MOTORE.memoria, ollama=_ollama_ok_hud(), meteo=_meteo_hud(MOTORE.memoria), presenza=PRESENZA.stato())})
            elif base == "/cucina":                                   # v26: 🍳 il ricettario e le ricette di serie
                self._json({"ok": True, "ricettario": RICETTARIO.elenco(),
                            "di_serie": [{"id": k, "nome": r["nome"], "emoji": r["emoji"], "tempo": r["tempo"], "tag": r["tag"]} for k, r in RICETTE_DI_SERIE.items()]})
            elif base == "/cucina/ricetta":                           # v26: una ricetta (?id=&persone=)
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                rid = q.get("id", [""])[0][:80]
                try:
                    pers = max(1, min(20, int(q.get("persone", ["0"])[0]))) or None
                except ValueError:
                    pers = None
                r = prepara_ricetta(RICETTE_DI_SERIE[rid], pers, rid) if rid in RICETTE_DI_SERIE else trova_ricetta(rid, pers)
                self._json({"ok": bool(r), "ricetta": r} if r else {"ok": False, "errore": "ricetta non trovata"}, 200 if r else 404)
            elif base == "/tutor":                                    # v26: 🗣️ le conversazioni fatte
                self._json(dict(TUTOR_STAT.riassunto(), ok=True))
            elif base == "/respiro":                                  # v26: 🫧 i minuti di respiro
                self._json(dict(RESPIRO.riassunto(), ok=True))
            elif base == "/studio":                                   # v25: 🧠 i mazzi, le carte da ripassare oggi, la serie
                self._json(dict(STUDIO.panoramica(), ok=True))
            elif base == "/studio/ripasso":                           # v25: le carte da ripassare (?mazzo=&libero=1)
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                mz = q.get("mazzo", [""])[0] or None
                self._json({"ok": True, "carte": STUDIO.da_ripassare(mz, libero=q.get("libero", ["0"])[0] == "1")})
            elif base == "/quiz":                                     # v25: 🎮 le domande (?tema=&difficolta=facile|medio|difficile)
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                d = q.get("difficolta", ["medio"])[0]
                self._json(dict(QUIZ.prepara(q.get("tema", [""])[0][:80], d if d in ("facile", "medio", "difficile") else "medio", MOTORE.cervello), ok=True))
            elif base == "/radio":                                    # v24: 📻 il copione dello show (?momento=mattina|pomeriggio|sera)
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                mo = q.get("momento", [""])[0]
                self._json(dict(radio_maik(MOTORE, mo if mo in ("mattina", "pomeriggio", "sera") else None), ok=True))
            elif base == "/storie":                                   # v24: 🎞️ le storie (?periodo=settimana|mese|anno)
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                self._json(dict(storie(MOTORE.memoria, q.get("periodo", ["mese"])[0]), ok=True))
            elif base == "/mente":                                    # v24: 🧠 la mappa della mente
                self._json(dict(mente(MOTORE.memoria), ok=True))
            elif base == "/diagnosi":                                 # v23: 🩺 funziona tutto? (?veloce=1: senza internet e file)
                self._json(diagnosi(MOTORE, veloce=urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query).get("veloce", ["0"])[0] == "1"))
            elif base == "/annulla":                                  # v23: ↩ le ultime modifiche che posso annullare
                self._json({"ok": True, "annullabili": GIORNALE.elenco()})
            elif base == "/backup":                                   # v23: 💾 le copie di sicurezza
                self._json({"ok": True, "elenco": BACKUP.elenco(), "automatico": CONFIG.get("backup", True), "giorni": CONFIG.get("backup_giorni", 7),
                            "cartella": BACKUP.cartella()})
            elif base == "/prestazioni":                              # v22: ⚡ quanto vado veloce (e i consigli)
                self._json(prestazioni())
            elif base == "/presenza":                                 # v22: ⏱️ il tempo davanti al PC
                self._json(dict(PRESENZA.stato(), ok=True))
            elif base == "/laboratorio":                              # v21: 🔬 le invenzioni
                self._json({"ok": True, "invenzioni": LABORATORIO.elenco()})
            elif base == "/laboratorio/app":                          # l'invenzione in una gabbia: CSP sandbox (origine opaca), niente rete, niente dati di MAIK
                x = LABORATORIO.prendi(qs.get("id", ""))
                if not x:
                    self._json({"ok": False, "errore": "invenzione non trovata"}, 404)
                else:
                    corpo = x["html"].encode("utf-8")
                    self.send_response(200)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.send_header("Content-Security-Policy", CSP_LAB)
                    self.send_header("X-Content-Type-Options", "nosniff")
                    self.send_header("Referrer-Policy", "no-referrer")
                    self.send_header("Cache-Control", "no-store")
                    if qs.get("scarica") == "1":
                        nome = re.sub(r"[^\w\- ]+", "", x["nome"]).strip() or "invenzione"
                        self.send_header("Content-Disposition", "attachment; filename*=UTF-8''" + urllib.parse.quote(nome + ".html"))
                    self.send_header("Content-Length", str(len(corpo)))
                    self.end_headers()
                    self.wfile.write(corpo)
            elif base == "/aiutanti":                                 # v21: 🧪 gli aiutanti lampo
                self._json({"ok": True, "aiutanti": AIUTANTI.elenco()})
            elif base == "/aiutanti/avvisi":
                self._json({"avvisi": AIUTANTI.prendi_avvisi()})
            elif base == "/tv":                                       # v21: 📺 altri canali del multiverso
                self._json(dict(tv_multiverso(MOTORE.cervello), ok=True))
            elif base == "/obiettivi":                                # v20: 🎯 gli obiettivi con le tappe
                self._json({"ok": True, "obiettivi": OBIETTIVI.elenco(tutti=qs.get("tutti") == "1")})
            elif base == "/obiettivi/avvisi":
                self._json({"avvisi": OBIETTIVI.prendi_avvisi()})
            elif base == "/prime/settimana":                          # v20: 🗓️ il piano della settimana
                self._json(dict(pianifica_settimana(), ok=True))
            elif base == "/prime/tendenze":                           # v20: 📈 30 giorni
                try:
                    n = int(qs.get("giorni", "30") or 30)
                except ValueError:
                    n = 30
                self._json(dict(tendenze(MOTORE.memoria, n), ok=True))
            elif base == "/prime/oggi":                               # v19: 🛰️ il centro di controllo
                self._json(dict(prime_oggi(MOTORE.memoria), ok=True))
            elif base == "/proattivo":                                # v18: 💡 le idee nuove (la GUI chiede ogni tanto)
                self._json({"idee": PROATTIVO.prendi(), "attivo": PROATTIVO.stato()["attivo"]})
            elif base == "/proattivo/stato":
                self._json(dict(PROATTIVO.stato(), ok=True))
            elif base == "/ricordi":                                  # v18: cerca nelle chiacchierate passate
                q = qs.get("q", "").strip()[:200]
                per = periodo_ricordi(qs.get("quando", "")) if qs.get("quando") else None
                self._json({"ok": True, "risultati": RICORDI.cerca(MOTORE.memoria, q, k=8, da=per[0] if per else None, a=per[1] if per else None, rigida=False) if q else [],
                            "info": RICORDI.info(MOTORE.memoria)})
            elif base == "/ricordi/giorno":
                r = RICORDI.router("di cosa abbiamo parlato " + (qs.get("q", "") or "ieri")[:40], MOTORE.memoria)
                self._json(dict(r or {"testo": "Non capisco il giorno."}, ok=bool(r)))
            elif base == "/abitudini/avvisi":
                self._json({"avvisi": ABITUDINI.prendi_avvisi()})
            elif base == "/settimana":
                self._json(dict(riepilogo_settimana(MOTORE.memoria), ok=True))
            elif base == "/documenti/cerca":
                q = qs.get("q", "").strip()
                self._json({"risultati": MOTORE.memoria.cerca_documenti(q, k=6, rigida=False) if q else []})
            elif base == "/seguiti":
                self._json({"seguiti": MOTORE.memoria.seguiti_in_attesa()})
            elif base == "/seguiti/scaduti":
                self._json({"seguiti": MOTORE.seguiti_da_chiedere(qs.get("sessione"))})
            # ── v10: app installabile ──
            elif base == "/manifest.webmanifest":
                self._invia(json.dumps(MANIFEST, ensure_ascii=False), "application/manifest+json; charset=utf-8")
            elif base == "/sw.js":
                self._invia(SERVICE_WORKER, "application/javascript; charset=utf-8", "no-cache")
            # ── v11: PC, avatar 3D, librerie ──
            elif base == "/pc/info":
                self._json(info_pc())
            elif base == "/pc/attesa":
                self._json({"attesa": [{k: v[k] for k in ("id", "tipo", "descrizione", "icona")} for v in PC.attesa.values()]})
            elif base == "/pc/registro":
                self._json({"registro": PC.registro, "fiducia": MOTORE.memoria.ricordi.get("pc_fiducia") or [],
                            "attivo": CONFIG["pc"], "finto": CONFIG["pc_finto"],
                            "app": sorted(APP_PC) + sorted(ComandiPC.app_utente()), "siti": sorted(SITI_PC)})
            elif base.startswith("/pc/screenshot/"):                 # v12: solo gli screenshot fatti da MAIK, solo da qui
                p = PC.schermate.get(urllib.parse.unquote(base[len("/pc/screenshot/"):]))
                if not self._richiesta_locale() or not p or not os.path.isfile(p):
                    self.send_error(404)
                else:
                    self._servi_file(p, "image/png", "no-cache")
            elif base == "/pc/file":
                if not self._richiesta_locale():
                    self._json({"file": [], "errore": "Solo da questo computer."}, 403)
                else:
                    self._json({"file": cerca_file(qs.get("q", "")) if CONFIG["pc"] else []})
            # ── v13: routine, avvisi, voce neurale, animazioni ──
            elif base == "/routine":
                self._json({"routine": [dict(r, analisi=[ROUTINE.analizza(p) for p in r["passi"]], quando=ROUTINE.descrivi_orario(r))
                                        for r in ROUTINE.elenco()]})
            elif base == "/calendario":                               # v15: gli impegni (anche ricorrenti) da una data
                try:
                    da = datetime.datetime.fromisoformat(qs.get("da", "")) if qs.get("da") else datetime.datetime.now()
                except ValueError:
                    da = datetime.datetime.now()
                giorni = max(1, min(62, int(qs.get("giorni", "7") or 7) if str(qs.get("giorni", "7")).isdigit() else 7))
                da = da.replace(hour=0, minute=0, second=0, microsecond=0)
                self._json({"ok": True, "eventi": [Calendario.json_occ(o) for o in CAL.occorrenze(da, da + datetime.timedelta(days=giorni))],
                            "agenda": CAL.agenda(da, giorni), "totale": len(CAL.eventi())})
            elif base == "/calendario/avvisi":
                self._json({"avvisi": CAL.prendi_avvisi()})
            elif base == "/notizie":                                  # v14: notizie per argomento (RSS)
                self._json(NOTIZIE.prendi(_categoria_notizie(qs.get("cat", "")), 10) if CONFIG["web"] else {"ok": False, "notizie": [], "errore": "MAIK_WEB=0"})
            elif base == "/routine/notizie":
                self._json({"notizie": ROUTINE.prendi_notizie() if self._richiesta_locale() else []})
            elif base == "/pc/avvisi":
                self._json({"avvisi": MONITOR.prendi() if self._richiesta_locale() else []})
            elif base == "/voce/info":
                self._json(VOCE.info(MOTORE.memoria))
            elif base == "/animazioni":
                self._json({"animazioni": animazioni_elenco()})
            elif base.startswith("/animazioni/"):
                n = os.path.basename(urllib.parse.unquote(base[len("/animazioni/"):]))
                p = os.path.join(_cartella_animazioni(), n)
                if not n.lower().endswith(".vrma") or not os.path.isfile(p):
                    self.send_error(404)
                else:
                    self._servi_file(p, "model/gltf-binary", "no-cache")
            elif base == "/avatar/info":
                info = _avatar_info()
                self._json({"presente": bool(info), **(info or {})})
            elif base == "/avatar":
                info = _avatar_info()
                if not info:
                    self.send_error(404)
                else:
                    self._servi_file(os.path.join(DATA_DIR, "avatar", info["file"]), "model/gltf-binary", "no-cache")
            elif base.startswith("/lib/"):
                percorso, errore = lib_locale(base[len("/lib/"):])
                if not percorso:
                    self._json({"errore": errore}, 404 if errore == "file non permesso" else 502)
                else:
                    tipo = ("text/javascript; charset=utf-8" if percorso.endswith((".js", ".mjs")) else
                            "application/wasm" if percorso.endswith(".wasm") else "application/octet-stream")
                    self._servi_file(percorso, tipo)
            elif base in ("/icona-192.png", "/icona-512.png", "/favicon.ico", "/apple-touch-icon.png"):
                n = 512 if "512" in base else 192
                self._invia(icona_png(n), "image/png", "public, max-age=86400")
            else:
                self.send_error(404)
        except (BrokenPipeError, ConnectionResetError):
            pass

    # ── POST ────────────────────────────────────────────────
    def do_POST(self):
        base = self.path.split("?")[0]
        try:
            if base in ("/documenti/file", "/documenti/estrai", "/calendario/importa"):     # v15: file grezzi (Word, PDF, .ics)
                lung = int(self.headers.get("Content-Length", 0) or 0)
                nome = urllib.parse.unquote(self.headers.get("X-Nome", "documento"))[:120]
                if lung <= 0 or lung > 25 * 1024 * 1024:
                    self._json({"ok": False, "errore": "Il file deve essere tra 1 byte e 25 MB."}, 413); return
                dati = self.rfile.read(lung)
                if base == "/calendario/importa":
                    try:
                        imp, agg = CAL.importa(dati.decode("utf-8-sig", errors="replace"), nome)
                    except Exception as e:
                        self._json({"ok": False, "errore": f"calendario non valido: {str(e)[:80]}"}); return
                    self._json({"ok": imp + agg > 0, "importati": imp, "aggiornati": agg, "totale": len(CAL.eventi()),
                                **({} if imp + agg else {"errore": "nel file non ci sono eventi (serve un .ics)"})}); return
                testo, errore = estrai_testo(nome, dati)
                if base == "/documenti/estrai" or not testo:
                    self._json({"ok": bool(testo), "testo": (testo or "")[:60000], "caratteri": len(testo or ""), "errore": errore}); return
                info, errore = MOTORE.memoria.aggiungi_documento(nome, testo)
                self._json({"ok": bool(info), "documento": info, "errore": errore, "caratteri": len(testo)}); return
            if base == "/animazioni":                               # v13: animazione .vrma (file grezzo)
                lung = int(self.headers.get("Content-Length", 0) or 0)
                if not self._richiesta_locale():
                    self._json({"ok": False, "errore": "Solo da questo computer."}, 403); return
                if lung <= 0 or lung > 20 * 1024 * 1024:
                    self._json({"ok": False, "errore": "Il file deve essere tra 1 byte e 20 MB."}, 413); return
                info, errore = salva_animazione(urllib.parse.unquote(self.headers.get("X-Nome", "animazione.vrma")), self.rfile.read(lung))
                self._json({"ok": bool(info), "animazione": info, "errore": errore}); return
            if base == "/avatar":                                   # v11: il tuo personaggio 3D (file grezzo)
                lung = int(self.headers.get("Content-Length", 0) or 0)
                if not self._richiesta_locale():
                    self._json({"ok": False, "errore": "Solo da questo computer."}, 403); return
                if lung <= 0 or lung > CONFIG["avatar_max_mb"] * 1024 * 1024:
                    self._json({"ok": False, "errore": f"Il file deve essere tra 1 byte e {CONFIG['avatar_max_mb']} MB."}, 413); return
                dati = self.rfile.read(lung)
                info, errore = salva_avatar(urllib.parse.unquote(self.headers.get("X-Nome", "avatar.glb")), dati)
                self._json({"ok": bool(info), "avatar": info, "errore": errore}); return
            if base == "/chat":
                testo = self._read_json_body().get("testo", "").strip()
                if not testo:
                    self._json({"ok": False, "risposta": "..."})
                    return
                self._json(MOTORE.rispondi(testo))

            elif base == "/chat/stream":
                self._chat_stream()

            elif base == "/ricorda":
                c = self._read_json_body()
                k, v = c.get("k", "").strip(), c.get("v", "").strip()
                if k and v:
                    MOTORE.memoria.ricorda_fatto(k, v); self._json({"ok": True})
                else:
                    self._json({"ok": False})

            elif base == "/dimentica":
                MOTORE.memoria.dimentica_fatto(self._read_json_body().get("k", "").strip())
                self._json({"ok": True})

            elif base == "/episodio":
                c = self._read_json_body()
                titolo, desc = c.get("titolo", "").strip(), c.get("desc", "").strip()
                if titolo:
                    MOTORE.memoria.salva_episodio(titolo, desc); self._json({"ok": True})
                else:
                    self._json({"ok": False})

            elif base == "/obiettivo":
                c = self._read_json_body()
                testo = c.get("testo", "").strip()
                if testo:
                    MOTORE.memoria.aggiungi_obiettivo(testo, c.get("tipo", "obiettivo")); self._json({"ok": True})
                else:
                    self._json({"ok": False})

            elif base == "/obiettivo/completa":
                idx = self._read_json_body().get("indice", -1)
                self._json({"ok": MOTORE.memoria.chiudi_obiettivo(idx)})

            elif base == "/relazione":
                c = self._read_json_body()
                nome, ruolo = c.get("nome", "").strip(), c.get("ruolo", "").strip()
                if nome and ruolo:
                    MOTORE.memoria.ricorda_persona(nome, ruolo, c.get("dettaglio", "").strip())
                    self._json({"ok": True})
                else:
                    self._json({"ok": False})

            elif base in ("/imparato/elimina", "/episodio/elimina"):
                try:
                    indice = int(self._read_json_body().get("indice", -1))
                except (TypeError, ValueError):
                    indice = -1
                self._json({"ok": MOTORE.memoria.dimentica_elemento(base.split("/")[1], indice)})

            elif base == "/riassunto/elimina":
                MOTORE.memoria.aggiorna_ricordi(""); self._json({"ok": True})

            elif base == "/reset":
                cat = self._read_json_body().get("categoria", "").strip()
                self._json({"ok": MOTORE.memoria.reset_categoria(cat)})

            elif base == "/importa":
                MOTORE.memoria.importa(self._read_json_body()); self._json({"ok": True})

            elif base == "/modello":
                m = self._read_json_body().get("modello", "").strip()
                if m:
                    CONFIG["modello"] = m; self._json({"ok": True, "modello": m})
                else:
                    self._json({"ok": False})

            elif base == "/carattere":
                c = self._read_json_body().get("carattere", "").strip()
                if c:
                    CONFIG["carattere"] = c; self._json({"ok": True})
                else:
                    self._json({"ok": False})

            elif base == "/personalita":
                k = self._read_json_body().get("chiave", "").strip()
                ok = imposta_personalita(k, MOTORE.memoria)
                if ok and CONFIG.get("riscalda", True):
                    threading.Thread(target=riscalda_modello, daemon=True).start()            # v22: le istruzioni nuove già lette
                self._json({"ok": ok, "personalita": CONFIG["personalita"],
                            "nome": PERSONALITA[k][1] if ok else "", "emoji": PERSONALITA[k][0] if ok else ""})

            elif base == "/lista":
                c = self._read_json_body()
                try:
                    indice = int(c.get("indice", -1))
                except (TypeError, ValueError):
                    indice = -1
                ok = MOTORE.memoria.lista_modifica(c.get("azione", ""), indice, str(c.get("testo", "")))
                self._json({"ok": ok, "lista": MOTORE.memoria.lista})

            elif base == "/sessioni/nuova":
                self._json({"ok": True, "sessione": MOTORE.memoria.crea_sessione(self._read_json_body().get("titolo", ""))})

            elif base == "/sessioni/rinomina":
                c = self._read_json_body()
                self._json({"ok": MOTORE.memoria.rinomina_sessione(str(c.get("id", "")), c.get("titolo", ""))})

            elif base == "/sessioni/elimina":
                self._json({"ok": MOTORE.memoria.elimina_sessione(str(self._read_json_body().get("id", "")))})

            elif base == "/documenti":
                c = self._read_json_body()
                info, errore = MOTORE.memoria.aggiungi_documento(c.get("nome", ""), c.get("contenuto", ""))
                self._json({"ok": bool(info), "documento": info, "errore": errore})

            elif base == "/calendario/evento":                        # v15: un impegno a mano (dalla GUI)
                c = self._read_json_body()
                quando = None
                if c.get("inizio"):
                    try:
                        quando = datetime.datetime.fromisoformat(str(c["inizio"]))
                    except ValueError:
                        quando = None
                quando = quando or (parse_quando(str(c.get("quando", "")))[0] if c.get("quando") else None)
                if not quando:
                    self._json({"ok": False, "errore": "manca la data dell'evento"})
                else:
                    e, err = CAL.aggiungi(c.get("titolo", ""), quando, int(c.get("durata") or 60), c.get("luogo", ""), bool(c.get("tutto_giorno")))
                    self._json({"ok": bool(e), "evento": e, "errore": err})
            elif base == "/calendario/elimina":
                self._json({"ok": CAL.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/spese/aggiungi":                           # v16: una spesa dal modulo
                c = self._read_json_body()
                try:
                    data = datetime.date.fromisoformat(str(c.get("data"))[:10]) if c.get("data") else None
                except ValueError:
                    data = None
                imp = c.get("importo")
                if isinstance(imp, str):
                    imp = trova_importo(imp, serve_valuta=False)[0]
                x, err = SPESE.aggiungi(imp, c.get("descrizione", ""), c.get("categoria") or None, data, fonte="gui")
                self._json({"ok": bool(x), "spesa": x, "errore": err})
            elif base == "/spese/elimina":
                self._json({"ok": SPESE.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/spese/budget":
                c = self._read_json_body()
                try:
                    imp = float(str(c.get("importo") or 0).replace(",", "."))
                except ValueError:
                    imp = 0
                self._json({"ok": True, "budget": SPESE.imposta_budget(imp, c.get("categoria") or None)})
            elif base == "/spese/documento":                          # v16: bolletta/scontrino (testo già estratto) → spese e calendario
                c = self._read_json_body()
                self._json(dict(SPESE.registra_documento(str(c.get("testo", ""))[:200000], str(c.get("nome", ""))[:80], bool(c.get("scontrino")), MOTORE.cervello), ok=True))
            elif base == "/abitudini/crea":
                c = self._read_json_body()
                x = Abitudini.interpreta(c["testo"]) if c.get("testo") else {}
                for k in ("nome", "emoji", "giorni", "settimanale", "ora", "obiettivo", "unita"):
                    if c.get(k) not in (None, "", []):
                        x[k] = c[k]
                a, err = ABITUDINI.crea(**{k: x.get(k) for k in ("nome", "emoji", "giorni", "settimanale", "ora", "obiettivo", "unita") if x.get(k) is not None})
                self._json({"ok": bool(a), "abitudine": ABITUDINI.stato(a) if a else None, "errore": err})
            elif base == "/abitudini/segna":
                c = self._read_json_body()
                try:
                    giorno = datetime.date.fromisoformat(str(c.get("data"))[:10]) if c.get("data") else None
                except ValueError:
                    giorno = None
                st = ABITUDINI.segna(str(c.get("id", "")), int(c.get("n", 1) or 1), giorno)
                self._json({"ok": bool(st), "abitudine": st, "testo": ABITUDINI.testo_segnato(st) if st else ""})
            elif base == "/attivita/aggiungi":                        # v17
                c = self._read_json_body()
                if c.get("testo") and not c.get("campi"):
                    a, err = ATTIVITA.aggiungi_testo(str(c["testo"]), fonte=str(c.get("fonte") or "gui")[:20], quando=str(c.get("quando") or "")[:60])
                else:
                    a, err = ATTIVITA.aggiungi(**{k: c[k] for k in ("testo", "priorita", "scadenza", "ora", "progetto", "durata") if k in c}, fonte="gui")
                self._json({"ok": bool(a), "attivita": a, "errore": err})
            elif base == "/attivita/fatta":
                c = self._read_json_body()
                a = ATTIVITA.modifica(str(c.get("id", "")), fatta=c.get("fatta", True) is not False)
                ev = OBIETTIVI.sincronizza() if a and a.get("fatta") else []          # v20: era una tappa? → 🏆 (arriva come avviso)
                self._json({"ok": bool(a), "attivita": a, "oggi": len(ATTIVITA.vista("oggi")), "tappe": len(ev)})
            elif base == "/attivita/modifica":
                c = self._read_json_body()
                a = ATTIVITA.modifica(str(c.get("id", "")), **{k: c[k] for k in ("testo", "priorita", "scadenza", "ora", "progetto", "durata") if k in c})
                self._json({"ok": bool(a), "attivita": a})
            elif base == "/attivita/rimanda":
                c = self._read_json_body()
                q = interpreta_attivita("x per " + str(c.get("a") or "domani"))["scadenza"] or (datetime.date.today() + datetime.timedelta(days=1)).isoformat()
                fatte = [ATTIVITA.modifica(str(i), scadenza=q) for i in (c.get("ids") or [])[:50]]
                self._json({"ok": True, "spostate": len([x for x in fatte if x]), "scadenza": q})
            elif base == "/attivita/elimina":
                self._json({"ok": ATTIVITA.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/attivita/trova":
                a = ATTIVITA.trova(str(self._read_json_body().get("testo", ""))[:200])
                self._json({"ok": bool(a), "attivita": a})
            elif base == "/focus/sessione":
                c = self._read_json_body()
                x = ATTIVITA.sessione(c.get("minuti", 0), str(c.get("attivita") or ""), str(c.get("testo") or ""), c.get("completa", True) is not False)
                oggi = datetime.date.today()
                self._json({"ok": bool(x), "sessione": x, "oggi": ATTIVITA.statistiche(oggi, oggi)})
            elif base == "/abitudini/elimina":
                self._json({"ok": ABITUDINI.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/traduci":                                  # v15: interprete
                c = self._read_json_body()
                self._json(traduci(c.get("testo", ""), c.get("a", "inglese"), c.get("da", "italiano"), MOTORE.cervello))
            elif base == "/pagina":                                   # v15: «📖 leggimi» su una fonte
                c = self._read_json_body()
                self._json(leggi_pagina(str(c.get("url", ""))[:1000]) if CONFIG["web"] else {"ok": False, "errore": "internet è spento (MAIK_WEB=0)"})
            elif base == "/riunione":                                 # v14: trascrizione → riassunto, decisioni, cose da fare
                c = self._read_json_body()
                self._json(riassumi_riunione(c.get("testo", ""), c.get("durata", 0), c.get("titolo", ""), MOTORE.memoria, MOTORE.cervello))
            elif base == "/promemoria/aggiungi":                      # v14: «ricordamelo» dalle cose da fare
                c = self._read_json_body()
                testo = re.sub(r"\s+", " ", str(c.get("testo", ""))).strip()[:160]
                quando = parse_quando(str(c.get("quando", "")))[0] if c.get("quando") else None
                if len(testo) < 2:
                    self._json({"ok": False, "errore": "promemoria vuoto"})
                else:
                    p = MOTORE.memoria.aggiungi_promemoria(testo, quando, "promemoria")
                    self._json({"ok": True, "promemoria": p, "quando": fmt_quando(quando) if quando else "senza orario"})
            elif base == "/documenti/elimina":
                self._json({"ok": MOTORE.memoria.elimina_documento(str(self._read_json_body().get("id", "")))})

            elif base in ("/pc/conferma", "/pc/fiducia", "/pc/prepara", "/avatar/elimina", "/routine", "/routine/elimina",
                          "/routine/esegui", "/routine/analizza", "/voce", "/voce/scarica", "/voce/imposta", "/animazioni/elimina"):
                c = self._read_json_body()
                if not self._richiesta_locale():
                    self._json({"ok": False, "esito": "🔒 I comandi del PC si confermano solo da questo computer."}, 403)
                elif base == "/avatar/elimina":
                    self._json({"ok": elimina_avatar()})
                elif base == "/routine":
                    passi = ROUTINE.passi_da(c.get("passi"))
                    r, errore = ROUTINE.salva(c.get("nome"), passi, c.get("orario") or None, c.get("giorni"), c.get("id"),
                                              "modalità" if c.get("tipo") == "modalità" else "routine")
                    self._json({"ok": bool(r), "routine": r, "errore": errore,
                                "analisi": [ROUTINE.analizza(p) for p in r["passi"]] if r else []})
                elif base == "/routine/analizza":                     # v13: cosa farà ogni passo (senza farlo)
                    self._json({"analisi": [ROUTINE.analizza(p) for p in ROUTINE.passi_da(c.get("passi"))]})
                elif base == "/routine/elimina":
                    self._json({"ok": ROUTINE.elimina(str(c.get("id", "")))})
                elif base == "/routine/esegui":
                    self._json(PC.prepara("routine", {"id": str(c.get("id", ""))}, MOTORE.memoria) if CONFIG["pc"]
                               else {"ok": False, "esito": "I comandi del PC sono spenti."})
                elif base == "/voce":
                    try:
                        r = VOCE.sintetizza(c.get("testo", ""), c.get("voce"), c.get("velocita", 1.0), MOTORE.memoria)
                        self._json({"ok": True, "audio": base64.b64encode(r["wav"]).decode("ascii"), "durata_ms": r["durata_ms"], "fonemi": r["fonemi"]})
                    except Exception as e:
                        self._json({"ok": False, "errore": str(e)[:200]})
                elif base == "/voce/scarica":
                    ok, errore = VOCE.scarica(str(c.get("voce", "")))
                    self._json({"ok": ok, "errore": errore, "info": VOCE.info(MOTORE.memoria)})
                elif base == "/voce/imposta":
                    v = str(c.get("voce", ""))
                    ok = v in VOCE.scaricate()
                    if ok:
                        MOTORE.memoria.imposta_ricordo("voce_neurale", v)
                    self._json({"ok": ok, "info": VOCE.info(MOTORE.memoria)})
                elif base == "/animazioni/elimina":
                    self._json({"ok": elimina_animazione(c.get("file"))})
                elif base == "/pc/conferma":
                    self._json(PC.conferma(str(c.get("id", "")), bool(c.get("si", True)), bool(c.get("sempre")), MOTORE.memoria))
                elif base == "/pc/prepara":                          # v12: «apri» su un file trovato → di nuovo con conferma
                    tipo = str(c.get("tipo", ""))
                    if not CONFIG["pc"] or tipo not in ComandiPC.TIPI:
                        self._json({"ok": False, "esito": "Azione non disponibile."})
                    else:
                        self._json(PC.prepara(tipo, {k: v for k, v in c.items() if k != "tipo"}, MOTORE.memoria))
                else:
                    fid = set(MOTORE.memoria.ricordi.get("pc_fiducia") or [])
                    tipo = str(c.get("tipo", ""))
                    if c.get("azzera"):
                        fid = set()
                    elif tipo in ComandiPC.TIPI and tipo not in SENZA_FIDUCIA and tipo != "routine":
                        (fid.add if c.get("attiva") else fid.discard)(tipo)
                    MOTORE.memoria.imposta_ricordo("pc_fiducia", sorted(fid))
                    self._json({"ok": True, "fiducia": sorted(fid)})

            elif base == "/seguiti/elimina":
                self._json({"ok": MOTORE.memoria.elimina_seguito(str(self._read_json_body().get("id", "")))})

            elif base == "/promemoria/completa":
                n = MOTORE.memoria.chiudi_promemoria(self._read_json_body().get("id", ""))
                self._json({"ok": bool(n)})

            elif base == "/presenza":                                 # v22: {secondi} visti dalla webcam (solo il tempo)
                c = self._read_json_body()
                try:
                    sec = int(c.get("secondi", 0))
                except (TypeError, ValueError):
                    sec = 0
                self._json(dict(PRESENZA.aggiungi(sec), ok=True))
            elif base in ("/diagnosi/ripara", "/annulla", "/backup/crea", "/backup/ripristina", "/mente/dimentica", "/studio/voto", "/studio/elimina", "/quiz/fine",
                          "/cucina/salva", "/cucina/elimina", "/cucina/spesa", "/cucina/cucinata", "/respiro/fine", "/piano/esegui") and not stessa_origine(self):
                self._json({"ok": False, "errore": "richiesta da un altro sito"}, 403)          # v23: solo dalla GUI di MAIK
            elif base == "/analisi":                                  # v28: 🔬 {domanda} o {spec} (rifare la stessa domanda con un altro periodo) → solo letture
                c = self._read_json_body()
                if isinstance(c.get("spec"), dict):
                    sp = normalizza_spec_v28(c["spec"])
                    r = esegui_spec_v28(sp, MOTORE.memoria) if sp else None
                    self._json(dict(r, ok=True) if r else {"ok": False, "errore": "richiesta non valida"}, 200 if r else 400)
                else:
                    r = analisi_router(str(c.get("domanda") or "")[:220], MOTORE)
                    self._json(dict(r["analisi"], ok=True, testo=r["testo"]) if r else {"ok": False, "errore": "non è una domanda sui tuoi dati"}, 200 if r else 400)
            elif base == "/piano/esegui":                             # v27: ⚡ {id, scelte: [indici]} → le azioni del piano, tutte insieme (un solo «annulla»)
                c = self._read_json_body()
                sc = c.get("scelte")
                sc = [int(x) for x in sc if isinstance(x, (int, float)) or str(x).isdigit()] if isinstance(sc, list) else None
                GIORNALE.inizia("piano d'azione")
                r = esegui_piano_azione(MOTORE, str(c.get("id", ""))[:20], sc)
                if r and getattr(_CTX, "giornale", None):
                    _CTX.giornale["testo"] = f"piano d'azione ({r['n']} azion{'e' if r['n'] == 1 else 'i'})"
                mod = GIORNALE.chiudi()
                self._json(dict(r, ok=True, testo=testo_piano_fatto(r), annullabile=mod) if r else {"ok": False, "errore": "piano non trovato (scaduto?)"}, 200 if r else 404)
            elif base == "/cucina/salva":                             # v26: ⭐ {ricetta} nel ricettario (si può annullare)
                c = self._read_json_body()
                r0 = c.get("ricetta") if isinstance(c.get("ricetta"), dict) else None
                if not r0 or not isinstance(r0.get("ingredienti"), list) or not isinstance(r0.get("passi"), list):
                    self._json({"ok": False, "errore": "ricetta non valida"}, 400)
                else:
                    GIORNALE.inizia("salva una ricetta")
                    r = RICETTARIO.salva(r0)
                    if getattr(_CTX, "giornale", None):
                        _CTX.giornale["testo"] = f"salva la ricetta «{r['nome']}»"
                    self._json({"ok": True, "ricetta": r, "annullabile": GIORNALE.chiudi()})
            elif base == "/cucina/elimina":                           # v26: {id} (si può annullare)
                GIORNALE.inizia("elimina una ricetta")
                r = RICETTARIO.elimina(str(self._read_json_body().get("id", ""))[:40])
                if r and getattr(_CTX, "giornale", None):
                    _CTX.giornale["testo"] = f"elimina la ricetta «{r['nome']}»"
                mod = GIORNALE.chiudi()
                self._json({"ok": bool(r), "annullabile": mod}, 200 if r else 404)
            elif base == "/cucina/spesa":                             # v26: 🛒 {voci} nella lista della spesa (si può annullare)
                c = self._read_json_body()
                voci = [re.sub(r"\s+", " ", str(v)).strip()[:80] for v in (c.get("voci") if isinstance(c.get("voci"), list) else [])[:80] if str(v).strip()]
                GIORNALE.inizia("aggiungi gli ingredienti alla lista della spesa")
                agg = MOTORE.memoria.lista_aggiungi(voci) if voci else []
                self._json({"ok": True, "aggiunte": agg, "gia": len(voci) - len(agg), "annullabile": GIORNALE.chiudi()})
            elif base == "/cucina/cucinata":                          # v26: 👨‍🍳 {id}: l'hai cucinata (per il ricettario)
                self._json(dict(RICETTARIO.cucinata(str(self._read_json_body().get("id", "")) or "?"), ok=True))
            elif base == "/respiro/fine":                             # v26: 🫧 {tecnica, secondi}
                c = self._read_json_body()
                try:
                    self._json(dict(RESPIRO.registra(str(c.get("tecnica", "calma")), int(c.get("secondi", 0))), ok=True))
                except (TypeError, ValueError):
                    self._json({"ok": False, "errore": "dati non validi"}, 400)
            elif base == "/studio/voto":                              # v25: {id, voto: 0-5} → la carta con la prossima data
                c = self._read_json_body()
                try:
                    x = STUDIO.vota(str(c.get("id", "")), int(c.get("voto", 0)))
                except (TypeError, ValueError):
                    x = None
                self._json({"ok": bool(x), "carta": x, "studio": STUDIO.panoramica()} if x else {"ok": False, "errore": "carta non trovata"}, 200 if x else 404)
            elif base == "/studio/elimina":                           # v25: {mazzo} (si può annullare)
                GIORNALE.inizia("elimina un mazzo")
                m = STUDIO.elimina_mazzo(str(self._read_json_body().get("mazzo", "")))
                if m and getattr(_CTX, "giornale", None):
                    _CTX.giornale["testo"] = f"elimina il mazzo «{m['nome']}»"
                mod = GIORNALE.chiudi()
                self._json({"ok": bool(m), "annullabile": mod, "studio": STUDIO.panoramica()}, 200 if m else 404)
            elif base == "/quiz/fine":                                # v25: {categoria, punti, giuste, totale} → record?
                c = self._read_json_body()
                try:
                    self._json(dict(QUIZ.fine(c.get("categoria"), c.get("punti", 0), c.get("giuste", 0), c.get("totale", 10)), ok=True))
                except (TypeError, ValueError):
                    self._json({"ok": False, "errore": "dati non validi"}, 400)
            elif base == "/mente/dimentica":                          # v24: {tipo: profilo|persona|fatto|sogno, chiave} (si può annullare)
                c = self._read_json_body()
                r = dimentica_nodo(MOTORE.memoria, str(c.get("tipo", "")), str(c.get("chiave", "")))
                self._json(dict(r, mente=mente(MOTORE.memoria)) if r["ok"] else r, 200 if r["ok"] else 404)
            elif base == "/diagnosi/ripara":                          # v23: {cosa: json|tmp|backup} (niente si cancella davvero)
                r = ripara(str(self._read_json_body().get("cosa", "")), MOTORE.memoria)
                self._json(dict(r, diagnosi=diagnosi(MOTORE)))
            elif base == "/annulla":                                  # v23: {id?} → rimette com'erano i dati cambiati
                r = GIORNALE.annulla(str(self._read_json_body().get("id") or "") or None, MOTORE.memoria)
                self._json(dict(r, annullabili=GIORNALE.elenco()))
            elif base == "/backup/crea":                              # v23: 💾 una copia adesso
                r = BACKUP.crea("manuale")
                self._json(dict(r, elenco=BACKUP.elenco()))
            elif base == "/backup/ripristina":                        # v23: {nome} (la GUI chiede sempre conferma)
                r = BACKUP.ripristina(str(self._read_json_body().get("nome", "")), MOTORE.memoria)
                self._json(dict(r, elenco=BACKUP.elenco()), 200 if r["ok"] else 400)
            elif base in ("/laboratorio/crea", "/laboratorio/migliora", "/laboratorio/indietro", "/laboratorio/elimina", "/aiutanti/chiama") and not stessa_origine(self):
                self._json({"ok": False, "errore": "richiesta da un altro sito"}, 403)          # v21: solo dalla GUI di MAIK
            elif base == "/laboratorio/crea":                         # v21: {testo} (risponde quando il modello ha finito)
                x, err = LABORATORIO.crea(str(self._read_json_body().get("testo", ""))[:300], MOTORE.cervello)
                self._json({"ok": bool(x), "invenzione": x, "errore": err})
            elif base == "/laboratorio/migliora":                     # {id, testo}
                c = self._read_json_body()
                x, err = LABORATORIO.migliora(str(c.get("id", "")), str(c.get("testo", ""))[:300], MOTORE.cervello)
                self._json({"ok": bool(x), "invenzione": x, "errore": err})
            elif base == "/laboratorio/indietro":                     # ↩ la versione prima
                x = LABORATORIO.indietro(str(self._read_json_body().get("id", "")))
                self._json({"ok": bool(x), "invenzione": x})
            elif base == "/laboratorio/elimina":
                self._json({"ok": LABORATORIO.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/aiutanti/chiama":                          # {compito}
                a = AIUTANTI.chiama(str(self._read_json_body().get("compito", "")), MOTORE)
                self._json({"ok": bool(a), "aiutante": a, "errore": "" if a else "troppi aiutanti in fila, o compito vuoto"})
            elif base == "/obiettivi/crea":                           # v20: {testo: «imparare lo spagnolo entro giugno»} o {titolo, scadenza}
                c = self._read_json_body()
                if c.get("testo"):
                    titolo, scad = scadenza_obiettivo(str(c["testo"])[:200])
                else:
                    titolo = str(c.get("titolo", ""))[:120]
                    try:
                        scad = datetime.date.fromisoformat(str(c.get("scadenza", ""))[:10]) if c.get("scadenza") else None
                    except ValueError:
                        scad = None
                o, err = OBIETTIVI.crea(titolo, scad, MOTORE.cervello)
                if o:
                    MOTORE.memoria.aggiungi_obiettivo(o["titolo"], "obiettivo")
                self._json({"ok": bool(o), "obiettivo": o, "errore": err})
            elif base == "/obiettivi/tappa":                          # ✓ la tappa in corso
                oid = str(self._read_json_body().get("id", ""))
                ev = OBIETTIVI.segna_tappa(oid)
                self._json({"ok": ev is not None, "eventi": ev or [], "obiettivo": next((x for x in OBIETTIVI.elenco(tutti=True) if x["id"] == oid), None)})
            elif base == "/obiettivi/elimina":
                self._json({"ok": OBIETTIVI.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/settimana/applica":                        # 📌 fissa i giorni (solo per le cose senza data)
                c = self._read_json_body()
                senza = {a["id"] for a in ATTIVITA.aperte() if not a.get("scadenza")}
                n = 0
                for x in (c.get("assegna") or [])[:100]:
                    if str(x.get("id")) in senza and re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(x.get("data", ""))):
                        n += bool(ATTIVITA.modifica(str(x["id"]), scadenza=str(x["data"]), fissata=str(x["data"])))
                self._json({"ok": True, "fissate": n})
            elif base == "/automazioni/crea":                         # v19: {testo} in italiano, oppure {comando, giorni, ora | ogni_min}
                c = self._read_json_body()
                if c.get("testo"):
                    a, err = AUTOMAZIONI.crea_da_testo(str(c["testo"])[:300])
                else:
                    q = {k: c[k] for k in ("giorni", "ora", "ogni_min") if c.get(k) not in (None, "", [])}
                    if "giorni" in q:
                        q["giorni"] = sorted({int(g) for g in q["giorni"] if str(g).isdigit() and 0 <= int(g) <= 6}) or list(range(7))
                    if "ora" in q and not re.fullmatch(r"\d{2}:\d{2}", str(q["ora"])):
                        q.pop("ora")
                    if "ogni_min" in q:
                        q = {"ogni_min": max(15, min(1440, int(q["ogni_min"])))}
                    elif q:
                        q.setdefault("giorni", list(range(7)))
                        q.setdefault("ora", "09:00")
                    a, err = AUTOMAZIONI.crea(str(c.get("comando", ""))[:200], q or None, "gui")
                self._json({"ok": bool(a), "automazione": a, "errore": err})
            elif base == "/automazioni/elimina":
                self._json({"ok": AUTOMAZIONI.elimina(str(self._read_json_body().get("id", "")))})
            elif base == "/automazioni/attiva":
                c = self._read_json_body()
                a = AUTOMAZIONI.imposta(str(c.get("id", "")), c.get("attiva", True) is not False)
                self._json({"ok": bool(a), "automazione": a})
            elif base == "/automazioni/esegui":                       # ▶ Prova adesso: aspetta il risultato
                c = self._read_json_body()
                a = next((x for x in AUTOMAZIONI._carica()["automazioni"] if x["id"] == str(c.get("id", ""))), None)
                if not a:
                    self._json({"ok": False, "errore": "automazione non trovata"})
                else:
                    es = AUTOMAZIONI.esegui(a, MOTORE, avvisa=False)          # lo mostra già chi l'ha chiesto
                    self._json({"ok": True, "esito": es})
            elif base == "/proattivo/azione":                         # v18: i pulsanti delle idee
                c = self._read_json_body()
                self._json(PROATTIVO.esegui(str(c.get("azione", "")), c.get("dati") or {}, MOTORE.memoria))
            elif base == "/proattivo/imposta":
                c = self._read_json_body()
                self._json(dict(PROATTIVO.imposta(c.get("attivo"), c.get("regola"), c.get("on")), ok=True))
            elif base == "/proattivo/controlla":                       # «hai qualche idea?» dalla GUI (rispetta silenzio e limite)
                PROATTIVO.controlla(memoria=MOTORE.memoria, forza=True)
                self._json({"ok": True, "idee": PROATTIVO.prendi()})
            elif base == "/ocr":                                     # v18: 📷 il testo di una foto (scopo «spesa»: scontrino/bolletta → spese)
                c = self._read_json_body()
                if c.get("scopo") == "spesa":
                    sid = MOTORE.memoria.sessione_valida(str(c.get("sessione") or "")[:40] or None)
                    self._json(foto_alle_spese(c.get("immagine", ""), MOTORE.cervello, str(c.get("domanda", ""))[:300], str(c.get("nome") or "foto")[:80],
                                               MOTORE.memoria, sid))
                else:
                    self._json(ocr_immagine(c.get("immagine", ""), MOTORE.cervello))
            elif base == "/vedi":
                c = self._read_json_body()
                img = c.get("immagine", "")
                if "," in img:                       # togli il prefisso data:image/...;base64,
                    img = img.split(",", 1)[1]
                if not img:
                    self._json({"ok": False, "errore": "nessuna immagine"}); return
                testo = MOTORE.cervello.vedi(img, c.get("prompt", "").strip())
                if testo.startswith("__ERRORE"):
                    low = testo.lower()
                    if "mllama" in low or "architecture" in low:
                        msg = ("Il tuo Ollama è troppo vecchio per llama3.2-vision (errore 'mllama'). "
                               "Soluzione veloce:  ollama pull llava   —  oppure aggiorna Ollama "
                               "all'ultima versione da https://ollama.com/download")
                    elif "not found" in low:
                        msg = "Nessun modello visione installato. Esegui:  ollama pull llava"
                    else:
                        msg = "Modello visione non raggiungibile. Prova:  ollama pull llava"
                    self._json({"ok": False, "errore": msg})
                else:
                    self._json({"ok": True, "testo": testo})

            else:
                self.send_error(404)
        except (BrokenPipeError, ConnectionResetError):
            pass

    # ── streaming SSE ───────────────────────────────────────
    def _chat_stream(self):
        corpo = self._read_json_body()
        testo = str(corpo.get("testo", "")).strip()
        allegato = corpo.get("allegato") if isinstance(corpo.get("allegato"), dict) else None
        rigenera = bool(corpo.get("rigenera"))
        sessione = str(corpo.get("sessione") or "")[:40] or None
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Connection", "close")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()

        def invia(obj):
            try:
                self.wfile.write(("data: " + json.dumps(obj, ensure_ascii=False) + "\n\n").encode("utf-8"))
                self.wfile.flush()
            except (BrokenPipeError, ConnectionResetError):
                raise

        if not testo and not allegato:
            invia({"done": True, "ok": False, "risposta": "..."})
            return
        MOTORE.chat_attive = getattr(MOTORE, "chat_attive", 0) + 1              # v22: c'è una risposta in corso
        MOTORE.ultima_chat = time.time()
        try:
            meta = MOTORE.rispondi_stream(testo, lambda chunk: invia({"t": chunk}), allegato=allegato,
                                          rigenera=rigenera, sessione=sessione, on_evento=invia, accurato=bool(corpo.get("accurato")))
            invia(meta)
        except (BrokenPipeError, ConnectionResetError):
            pass  # il client ha chiuso, niente da fare
        finally:
            MOTORE.chat_attive -= 1
            MOTORE.ultima_chat = time.time()


# ════════════════════════════════════════════════════════════
